@@private
<%_
var shiomiXunStore = {};
try {
  var shiomiXunVars = typeof getVariables === 'function' ? getVariables({ type: 'chat' }) : {};
  shiomiXunStore = shiomiXunVars && shiomiXunVars['$迅网正文'] || (shiomiXunVars['$迅网'] && !shiomiXunVars['$迅网'].storageFormat ? shiomiXunVars['$迅网'] : {});
} catch (e) {
  try { shiomiXunStore = getvar('$迅网正文') || {};  } catch (_) { shiomiXunStore = {}; }
}
var shiomiXunApi = null;
try {
  var shiomiHosts = typeof window !== 'undefined' ? [window,window.parent] : [];
  for(var hi=0;hi<shiomiHosts.length&&!shiomiXunApi;hi++){
    var wh=shiomiHosts[hi];
    if(wh.ShiomiXun && typeof wh.ShiomiXun.narrativeRecords==='function')shiomiXunApi=wh.ShiomiXun;
    if(!shiomiXunApi&&wh.document)for(var fi=0;fi<wh.document.querySelectorAll('iframe').length;fi++){
      try{var fa=wh.document.querySelectorAll('iframe')[fi].contentWindow.ShiomiXun;if(fa&&typeof fa.narrativeRecords==='function'){shiomiXunApi=fa;break;}}catch(_){}
    }
  }
  if(shiomiXunApi)shiomiXunStore=shiomiXunApi.narrativeRecords();
}catch(_){}
var shiomiXunMemories = Array.isArray(shiomiXunStore.memories) ? shiomiXunStore.memories : [];
var shiomiXunLife = getvar('stat_data.城市生活') || {};
var shiomiXunScene = shiomiXunLife && shiomiXunLife.当前场景 && typeof shiomiXunLife.当前场景 === 'object' ? shiomiXunLife.当前场景 : {};
var shiomiXunSceneNames = Array.isArray(shiomiXunScene.在场人物) ? shiomiXunScene.在场人物.map(String) : [];
var shiomiXunRecent = '';
try {
  var shiomiXunCtx = SillyTavern && SillyTavern.getContext ? SillyTavern.getContext() : null;
  var shiomiXunChat = shiomiXunCtx && Array.isArray(shiomiXunCtx.chat) ? shiomiXunCtx.chat : [];
  shiomiXunRecent = shiomiXunChat.slice(-6).map(function(m) { return String(m && (m.mes || m.message || m.content) || ''); }).join('\n');
} catch (_) { shiomiXunRecent = ''; }
var shiomiXunRows = shiomiXunMemories.slice().reverse();
var shiomiXunPicked = [];
var shiomiXunChars = 0;
for (var shiomiXunI = 0; shiomiXunI < shiomiXunRows.length; shiomiXunI++) {
  var shiomiXunM = shiomiXunRows[shiomiXunI] || {};
  var shiomiXunNames = Array.isArray(shiomiXunM.characters) ? shiomiXunM.characters.map(String) : [];
  var shiomiXunTopics = Array.isArray(shiomiXunM.topics) ? shiomiXunM.topics.map(String) : [];
  var shiomiXunRelevant = shiomiXunI < 3;
  if (!shiomiXunRelevant) shiomiXunRelevant = shiomiXunNames.some(function(n) { return shiomiXunSceneNames.indexOf(n) !== -1 || (shiomiXunRecent && shiomiXunRecent.indexOf(n) !== -1); });
  if (!shiomiXunRelevant) shiomiXunRelevant = shiomiXunTopics.some(function(t) { return t && shiomiXunRecent && shiomiXunRecent.indexOf(t) !== -1; });
  if (!shiomiXunRelevant) continue;
  var shiomiXunLine = '- ' + (shiomiXunM.worldTime ? '[' + String(shiomiXunM.worldTime) + '] ' : '') + String(shiomiXunM.summary || '').trim();
  if (!shiomiXunLine || shiomiXunLine === '- ') continue;
  if (shiomiXunChars + shiomiXunLine.length > 1800) continue;
  shiomiXunPicked.push(shiomiXunLine);
  shiomiXunChars += shiomiXunLine.length;
  if (shiomiXunPicked.length >= 8) break;
}
var shiomiXunRendered = shiomiXunPicked.join('\n');
_%>
<%_ if (shiomiXunRendered) { _%>
<讯匣记录>
<%= shiomiXunRendered %>
</讯匣记录>
<%_ } _%>
<%_
var shiomiAccountRows = Object.values(shiomiXunStore.accounts || {}).filter(function(a) {
  if (!a || a.id === 'user') return false;
  return [a.person && a.person.realName, a.characterName, a.displayName, a.handle].some(function(n) {
    return n && n.length > 1 && (shiomiXunSceneNames.indexOf(n) !== -1 || shiomiXunRecent.indexOf(n) !== -1);
  });
});
var shiomiAccountText = '', shiomiAccountCount = 0;
for (var ai = 0; ai < shiomiAccountRows.length; ai++) {
  var a = shiomiAccountRows[ai];
  var line = JSON.stringify({id:a.id,name:a.displayName,handle:a.handle,entityType:a.entityType,person:a.person,company:a.company,background:a.background});
  if (shiomiAccountText.length + line.length > 9000) continue;
  shiomiAccountText += line + '\n';
  if (++shiomiAccountCount >= 8) break;
}
_%>
<%_ if (shiomiAccountText) { _%>
<讯匣人物与公司档案>
账户id保持同一人物身份；公开称呼沿用账户名，读取档案不等于获知未公开的真名。沿着这些人和公司的既有来历续写。档案中的隐私留在创作视野里；故事中的人物只凭亲身经历、公开资料与实际得到的消息行动。相貌与性格照旧，公司业务与地址依已有记录，不另造一个同名的人或店。
<%= shiomiAccountText %>
</讯匣人物与公司档案>
<%_ } _%>

<%_
var shiomiAgreementRender=function(records,context){
var xunArr=function(v){return Array.isArray(v)?v:[];},xunObj=function(v){return v&&typeof v==='object'&&!Array.isArray(v)?v:{};},xunText=function(v){return String(v==null?'':v).trim();},xunUnique=function(v){return Array.from(new Set(xunArr(v).map(xunText).filter(Boolean)));};
var xunGetStatPath=function(stat,path){var parts=String(path||'').replace(/^stat_data\.?/,'').split('.').filter(Boolean),cur=stat;for(var pi=0;pi<parts.length;pi++){if(!cur||typeof cur!=='object')return undefined;cur=cur[parts[pi]];}return cur;};
var xunRenderEjsTemplate=eval("(function xunRenderEjsTemplate(template, stat) {\n  let raw = String(template || '').replace(/^\\s*@@private\\s*/i, '');\n  if (!raw.includes('\u003c%')) return raw.trim();\n  let code = `let __out = '';\\n`, last = 0;\n  const re = /\u003c%([_=-]?)([\\s\\S]*?)%\u003e/g;\n  let m;\n  while ((m = re.exec(raw))) {\n    code += `__out += ${JSON.stringify(raw.slice(last, m.index))};\\n`;\n    const marker = String(m[1] || '');\n    let js = String(m[2] || '');\n    if (js.endsWith('_') || js.endsWith('-')) js = js.slice(0, -1);\n    if (marker === '=' || marker === '-') code += `__out += String((${js.trim()}) ?? '');\\n`;\n    else code += `${js}\\n`;\n    last = re.lastIndex;\n  }\n  code += `__out += ${JSON.stringify(raw.slice(last))};\\nreturn __out;`;\n  try {\n    const fn = new Function('getvar', 'SillyTavern', code);\n    const rendered = fn(path =\u003e xunGetStatPath(stat, path), (() =\u003e { try { return SillyTavern; } catch (_) { return {}; } })());\n    return xunText(rendered).replace(/\\n{3,}/g, '\\n\\n');\n  } catch (_) { return ''; }\n}\n)");
function xunNarrativeAccountProfile(account,{stat={}}={}){
  if(!account)return {档案状态:'账户档案不存在；不得自行建立同名人物设定'};
  const person=Object.fromEntries(Object.entries(xunObj(account.person)).filter(([key])=>key!=='portraitPrompt'));
  const canon=xunArr(account.canonicalSources).map(row=>({条目:row.title,内容:xunRenderEjsTemplate(row.content,stat)})).filter(row=>row.内容);
  return {账户id:account.id,账户名:account.displayName||account.handle||account.id,号码:account.handle||'未公开',人物档案:person,机构档案:account.company,背景:account.background,世界书人物设定:canon,
    使用要求:'以账户id保持同一人。依已有外貌、性格、职业、经历、说话习惯和边界续写；未知字段保持未知，不为赴约另造人设。世界书固定人物沿用角色卷和当前阶段设定。真名与隐私是创作依据，不能因为读取档案就被主角知晓；未在实际交流中获知姓名时，按账户名识别对方。'};
}
function xunAgreementSelect(records,{sceneNames=[],recent='',schedule={},world={}}={}){
  const ranked=xunArr(records).map(r=>{
    const f=r.facts||{},names=xunUnique([r.contact,r.handle,...xunArr(r.aliases)]),state=xunObj(schedule[f.name]);
    let score=names.some(n=>n&&sceneNames.includes(n))?8:0;
    if(names.some(n=>n&&recent.includes(n)))score+=6;
    if(f.name&&recent.includes(f.name))score+=9;
    if(f.place&&recent.includes(f.place))score+=5;
    if(xunText(state.状态)==='进行中')score+=8;
    const day=xunText(world.日期);if(day&&f.time&&f.time.includes(day))score+=2;
    if(!score&&/赴约|约好的|按约|见面|约定|约会|碰头/.test(recent)&&f.status!=='已取消'&&!['已完成','已取消','已错过'].includes(state.状态))score=1;
    if(!score)return null;
    return {r,state,score};
  }).filter(Boolean).sort((a,b)=>b.score-a.score||String(b.r.createdAt).localeCompare(String(a.r.createdAt)));
  return ranked.slice(0,3);
}
function xunAgreementPrompt(records,{sceneNames=[],recent='',schedule={},world={},accounts={},stat={}}={}){
  const ranked=xunAgreementSelect(records,{sceneNames,recent,schedule,world});
  const blocks=[];let size=0;
  for(const {r,state} of ranked){
    const f=r.facts||{},status=f.status==='已取消'?'已取消':xunText(state.状态)||f.status||'待发生';
    const core={id:r.id,账户id:r.ownerId,对方账户:r.contact,号码:r.handle||'未公开',关联账户档案:xunUnique([...(r.kind==='dm'?[r.ownerId]:[]),...xunArr(r.participantIds)]).map(id=>xunNarrativeAccountProfile(accounts[id],{stat})),记录依据:r.verified?'双方确认原话已保存':'旧约定或依据不完整，按原文核对，不能补造条款',通讯时剧情日期:r.worldTime,确认内容:f,日程状态:status,修改总数:r.revisionCount||xunArr(r.revisions).length,近期修改:xunArr(r.revisions).slice(-3).map(v=>({通讯时剧情日期:v.worldTime,内容:v.facts,确认原话:v.confirmationQuotes}))};
    const quotes=r.evidence.filter(m=>r.confirmationQuotes.some(q=>m.text.includes(q))||xunArr(f.terms).some(t=>m.text.includes(t.quote)));
    const keyIds=new Set(quotes.map(m=>m.id));const originals=[...quotes,...r.evidence.filter(m=>!keyIds.has(m.id)).slice(-8)].sort((a,b)=>r.evidence.indexOf(a)-r.evidence.indexOf(b));
    let body=JSON.stringify({...core,相关私讯原文:originals.map(m=>({消息id:m.id,发言人:m.name,原文:m.text}))});
    if(size+body.length>24000){body=JSON.stringify({...core,关键原话:[...new Set([...r.confirmationQuotes,...xunArr(f.terms).map(t=>t.quote)])],说明:'补充原文超过正文上下文预算；保留确认条款及关键原话，缺项仍为未知'});}
    blocks.push(body);size+=body.length;
  }
  return blocks.length?'【讯匣约定与私讯依据】\n以下是实际交流记录与其账户档案。约定始终按账户id关联，以账户名识别，不依赖真名公开。读取约定时同时沿用对应人物设定，不能另造赴约对象。姓名与隐私只供维持人设，是否为故事中的人物所知取决于实际告知和接触。多个同名账户保持独立，无法判定赴约对象时保留歧义，不合并人设。按确认原话延续约定，单方提议、未确定与未答应事项保持原意。先前承诺不扩大为其它承诺，约定不代表已经履行。按最新修改执行；取消的约定不得继续写成待赴约。人物只知道自己参加或实际获知的交流。通讯中的相对时间以通讯时剧情日期为基准，日期未知时不推算。现场变化作为新发生的情况写出，不改写成此前谈妥的条件。\n'+blocks.join('\n'):'';
}

return xunAgreementPrompt(records,context);
};
var shiomiAgreementOptions={sceneNames:shiomiXunSceneNames,recent:shiomiXunRecent,schedule:shiomiXunLife.日程||{},world:shiomiXunLife.世界||{},accounts:shiomiXunStore.accounts||{},stat:getvar('stat_data')||{城市生活:shiomiXunLife}};
var shiomiAgreementContext=shiomiAgreementRender(shiomiXunStore.agreements||[],shiomiAgreementOptions);

_%>
<%_ if(shiomiAgreementContext){ _%>
<讯匣约定依据>
<%= shiomiAgreementContext %>
</讯匣约定依据>
<%_ } _%>

