@@dont_preload
@@if getvar('$人工案件管理.request.case_id', {scope:'local', defaults:''}) || getvar('$人工案件管理.active_case', {scope:'local', defaults:''})
@@private
<%_
var acManager = getvar('$人工案件管理', {scope:'local', defaults:{}}) || {};
var acCurrent = getvar('$当前人工案件', {scope:'local', defaults:{}}) || {};
var acAction = getvar('$人工案件行动', {scope:'local', defaults:{}}) || {};
var acRequest = acManager.request || {};
var acCaseId = String(acRequest.case_id || acManager.active_case || acCurrent.case_id || '').trim();
var acDefinitionEntry = String(acRequest.definition_entry || acCurrent.definition_entry || '').trim();
var acOutput = '';
var acStat = (variables && variables.stat_data) || {};

function acText(v) { return String(v == null ? '' : v).trim(); }
function acObj(v) { return v && typeof v === 'object' && !Array.isArray(v) ? v : {}; }

if (acCaseId && acDefinitionEntry) {
  var acRaw = await getwi('汐见', acDefinitionEntry);
  var acDef = JSON.parse(acText(acRaw || ''));
  if (!acDef || acText(acDef.id) !== acCaseId) throw new Error('当前人工案件定义读取失败');

  var acStarted = acText(acManager.active_case) === acCaseId && acText(acCurrent.case_id) === acCaseId;
  var acRequested = acText(acRequest.case_id) === acCaseId && acRequest.requested === true && !acStarted;
  var acInitialPersonStates = acObj(acObj(acDef.runtime).initial_person_states);
  var acInitialStateRows = {};
  Object.keys(acInitialPersonStates).forEach(function(acPersonName) {
    var acState = acObj(acInitialPersonStates[acPersonName]);
    var acPublicState = {};
    ['工作状态','身体状态','司法状态','联络状态'].forEach(function(acField) {
      var acValue = acText(acState[acField]);
      if (acValue) acPublicState[acField] = acValue;
    });
    if (Object.keys(acPublicState).length) acInitialStateRows[acPersonName] = acPublicState;
  });
  var acParts = [];

  if (acRequested) {
    var acStateInstruction = Object.keys(acInitialStateRows).length
      ? `\n如果本轮确实已经首次进入警方处理、并准备记录上述start事件，则同轮把以下已经公开成立的动态状态写入MVU的城市生活.人物；只写列出的动态字段，不复制人物本体，也不据此补充任何隐藏案件事实。若本轮还停留在案件发生前的request剧情，则不要写这些状态：\n${JSON.stringify(acInitialStateRows)}`
      : '';
    acParts.push(`用户已经明确选择现在开始《${acText(acDef.title)}》。案件开局资料由当前启用的案件开局条目提供。让案件通过当前已经成立的时间、地点、工作状态与现实警务来源自然进入{{user}}的工作，不瞬移，也不借启动补写尚未取得的调查结果。

案件第一次实际进入警方处理后，在回复末尾记录：
<authored_case_event>
${JSON.stringify({case:acCaseId,start:true})}
</authored_case_event>${acStateInstruction}`);
  }

  if (acStarted && acText(acAction.case_id) === acCaseId && acText(acAction.type)) {
    var acTarget = acObj(acAction.target);
    var acType = acText(acAction.type);
    var acTargetName = acText(acTarget.clue_name || acTarget.content_entry || acTarget.person || acTarget.target_name || acTarget.record_name || acTarget.clue_id || acTarget.detail_id || acTarget.operation_id);
    var acIntent = acType === 'investigate_clue' ? '调查' : acType === 'interview_person' ? '询问' : acType === 'review_record' ? '继续核查' : acType === 'submit_conclusion' ? '提交正式判断' : '执行调查动作';
    acParts.push(`本轮存在来自案件前端的调查动作请求。${acTargetName ? acIntent + '对象：' + acTargetName + '。' : ''}
动作：${JSON.stringify({ type:acType, target:acTarget, payload:acObj(acAction.payload) })}
这是{{user}}本轮明确选择的行动，只表示调查意图已经成立。行动能否立即完成、需要前往哪里、是否需要程序权限或等待结果，都依据当前现实条件处理；尚未实际取得的信息不得提前进入警方知识。真正形成的询问内容、痕迹、事实与调查经过分别写入人物说法、已掌握痕迹、已确认事实与调查记录。`);
  }

  if (acStarted) {
    var acManifest = acObj(acDef.content_manifest);
    var acHidden = acObj(acManifest.hidden_histories);
    var acMatters = acObj(acStat.警务事项);
    var acMatter = acObj(acMatters[acText(acDef.matterName)]);
    var acAuthor = acObj(acObj(acMatter.后台).作者案件);
    var acOpened = acObj(acAuthor.已开放内容);
    var acUnlockRows = [];
    Object.keys(acHidden).forEach(function(acName) {
      var acRow = acObj(acHidden[acName]);
      var acUnlock = acObj(acRow.unlock_when);
      var acKey = acText(acRow.unlock_key || acName);
      var acRule = acText(acUnlock.rule);
      if (!acRule || acOpened[acKey] === true) return;
