function shiomiBuildAutoBackendView(base, current, back) {
  if (String(base.案件来源 || '') !== '自动生成') return {};
  var clues = shiomiObj(current.调查线索);
  var mapping = shiomiObj(back.线索对应);
  var facts = shiomiObj(back.客观事实);
  var traces = shiomiObj(back.客观痕迹);
  var cognition = shiomiObj(back.人物认知);
  var sceneLocation = String(shiomiScene.地点 || '');
  var focusedMap = {};

  Object.keys(clues).forEach(function(clueName) {
    var clue = shiomiObj(clues[clueName]);
    var status = String(clue.状态 || '');
    if (status === '调查中' || status === '等待结果' || shiomiClueMentioned(clueName, clue, shiomiLastUserText)) focusedMap[clueName] = true;
  });

  var traceToClues = {}, factToClues = {}, personToClues = {};
  Object.keys(mapping).forEach(function(clueName) {
    var link = shiomiObj(mapping[clueName]);
    shiomiArr(link.客观痕迹).forEach(function(key){ (traceToClues[key] || (traceToClues[key] = [])).push(clueName); });
    shiomiArr(link.客观事实).forEach(function(key){ (factToClues[key] || (factToClues[key] = [])).push(clueName); });
    shiomiArr(link.人物认知).forEach(function(key){ (personToClues[key] || (personToClues[key] = [])).push(clueName); });
  });

  var waitingProcedureNames = Object.keys(traces).filter(function(key) {
    var trace = shiomiObj(traces[key]);
    if (String(trace.接触门槛 || '') !== '程序结果') return false;
    return (traceToClues[key] || []).some(function(clueName){ return String(shiomiObj(clues[clueName]).状态 || '') === '等待结果'; });
  });

  var accessibleTraceNames = {}, traceOut = {};
  Object.keys(traces).forEach(function(key) {
    var trace = shiomiObj(traces[key]);
    var gate = String(trace.接触门槛 || '');
    var mappedClues = traceToClues[key] || [];
    if (!mappedClues.length) return;
    var accessible = false;
    if (gate === '直接可见') {
      accessible = shiomiDirectPlaceVisible(trace.当前所在, sceneLocation);
    } else if (gate === '针对检查') {
      accessible = shiomiTraceIntent(key, trace, shiomiLastUserText);
    } else if (gate === '程序结果') {
      var mappedWaiting = mappedClues.some(function(clueName){ return String(shiomiObj(clues[clueName]).状态 || '') === '等待结果'; });
      var explicitResult = shiomiResultIntent(shiomiLastUserText);
      var targetedResult = shiomiTraceIntent(key, trace, shiomiLastUserText);
      var onlyWaitingResult = waitingProcedureNames.length === 1 && waitingProcedureNames[0] === key;
      var planFinished = shiomiPlanFinishedForTrace(key, trace, shiomiObj(current.__plans || {}));
      accessible = planFinished || (mappedWaiting && explicitResult && (targetedResult || onlyWaitingResult));
    }
    if (!accessible) return;
    accessibleTraceNames[key] = true;
    traceOut[key] = shiomiTraceView(trace);
    mappedClues.forEach(function(clueName){ focusedMap[clueName] = true; });
  });

  // 只有已经开放的痕迹能够把其直接支持的客观事实带入本轮；不再因地点、事实名称或用户猜测直接泄露后台事实。
  var factOut = {};
  Object.keys(accessibleTraceNames).forEach(function(traceName) {
    shiomiArr(shiomiObj(traces[traceName]).支持事实).forEach(function(factName) {
      if (!Object.prototype.hasOwnProperty.call(facts, factName)) return;
      factOut[factName] = facts[factName];
      (factToClues[factName] || []).forEach(function(clueName){ focusedMap[clueName] = true; });
    });
  });

  var personOut = {};
  Object.keys(cognition).forEach(function(personName) {
    var directlyRelevant = !!shiomiSceneNames[personName] || (!!shiomiLastUserText && shiomiLastUserText.indexOf(personName) !== -1);
    if (!directlyRelevant) return;
    personOut[personName] = cognition[personName];
    (personToClues[personName] || []).forEach(function(clueName){ focusedMap[clueName] = true; });
  });

  var out = {};
  var focused = Object.keys(focusedMap);
  if (focused.length) out.相关调查线索 = focused;
  if (Object.keys(personOut).length) out.人物认知 = personOut;
  if (Object.keys(factOut).length) out.客观事实 = factOut;
  if (Object.keys(traceOut).length) out.客观痕迹 = traceOut;

  if (shiomiFormalConclusionIntent(shiomiLastUserText)) {
    var shiomiBoundary = shiomiObj(back.结论边界);
    if (Object.keys(shiomiBoundary).length) {
      out.结论核对 = {
        真实情况: shiomiObj(back.真实情况),
        结论边界: shiomiBoundary
      };
    }
  }
  return out;
}
Object.keys(shiomiEvents).forEach(function(name) {
  var item = shiomiObj(shiomiEvents[name]);
  var base = shiomiObj(item.基础);
  var current = shiomiObj(item.当前案情);
  var back = shiomiObj(item.后台);
  var systemMark = shiomiObj(back.系统标识);
  var authoredMatter = String(systemMark.类型 || '') === 'authored_case';
  var people = shiomiObj(current.人物);
  var plans = shiomiObj(item.安排);
  var state = String(base.状态 || '');
  var ended = state === '已结案' || state === '已处理' || state === '已移交';
  if (!ended) {
    shiomiPoliceIndex[name] = {
      性质: String(base.性质 || ''),
      状态: state,
      阶段: String(base.阶段 || ''),
      发生时间: String(base.发生时间 || ''),
      发生地点: String(base.发生地点 || '')
    };
  }
  var clueNamesNow = Object.keys(shiomiObj(current.调查线索));
  var mentioned = !!shiomiRecentText && (
    shiomiRecentText.indexOf(name) !== -1 ||
    Object.keys(people).some(function(personName) { return shiomiRecentText.indexOf(personName) !== -1; }) ||
    Object.keys(plans).some(function(planName) { return shiomiRecentText.indexOf(planName) !== -1; }) ||
    clueNamesNow.some(function(clueName) { return shiomiRecentText.indexOf(clueName) !== -1; })
  );
  // 后台人物认知不能反向把案件拉入当前上下文；案件相关性只由当前已知案情、当前场景、既有安排或明确调查方向决定。
  var sceneRelated = Object.keys(people).some(function(personName){ return !!shiomiSceneNames[personName]; });
  var locationRelated = shiomiDirectPlaceVisible(String(base.发生地点 || ''), String(shiomiScene.地点 || ''));
  var planRelated = Object.values(plans).some(function(planRaw){
    var plan = shiomiObj(planRaw), ps = String(plan.状态 || '');
    if (ps !== '待发生' && ps !== '进行中') return false;
    if (String(plan.地点 || '') && String(plan.地点 || '') === String(shiomiScene.地点 || '')) return true;
    return shiomiArr(plan.人物).some(function(personName){ return !!shiomiSceneNames[String(personName || '').trim()]; });
  });
  if (!mentioned && !sceneRelated && !locationRelated && !planRelated) return;
  // 案件来源与后台系统标识只供脚本判定，不进入正文模型的常规变量视图。
  var visibleBase = {
    性质: String(base.性质 || ''),
    处理性质: String(base.处理性质 || ''),
    状态: String(base.状态 || ''),
    阶段: String(base.阶段 || ''),
    发生时间: String(base.发生时间 || ''),
    发生地点: String(base.发生地点 || ''),
    来源: String(base.来源 || '')
  };
  if (base.受理时间 != null && String(base.受理时间 || '')) visibleBase.受理时间 = String(base.受理时间);

  if(base.声望结算)visibleBase.声望结算=base.声望结算;

  // 人工案件的实际调查历史以MVU为唯一记录；世界书保存潜在案件内容，<authored_case_event>只保存开始/归档生命周期。
  // 人工案件不使用当前案情.调查线索，因此这里只投放已经实际形成的人物说法、痕迹、事实、调查记录与结论。
  var visibleCurrent = current;
  if (authoredMatter) {
    visibleCurrent = {
      事件: String(current.事件 || ''),
      人物: shiomiObj(current.人物),
      人物说法: shiomiObj(current.人物说法),
      已掌握痕迹: shiomiObj(current.已掌握痕迹),
      已确认事实: shiomiObj(current.已确认事实),
      调查记录: shiomiObj(current.调查记录),
      正式结论: shiomiObj(current.正式结论)
    };
    if (current.结案结论 != null && String(current.结案结论 || '')) visibleCurrent.结案结论 = String(current.结案结论);
  }

  var visibleItem = {
    基础: visibleBase,
    当前案情: visibleCurrent,
    安排: plans
  };
  var autoCurrentForView = current;
  if (!authoredMatter) {
    autoCurrentForView = Object.assign({}, current, { __plans: plans });
  }
  var backendView = authoredMatter ? {} : shiomiBuildAutoBackendView(base, autoCurrentForView, back);
  if (Object.keys(backendView).length) visibleItem.当前可用案件资料 = backendView;
  shiomiVisibleEvents[name] = visibleItem;
  Object.keys(people).forEach(shiomiMarkName);
  // 仅存在于案件后台的人物不因模型已知后台而自动进入当前人物相关集合。
  Object.values(plans).forEach(function(plan){ shiomiArr(shiomiObj(plan).人物).forEach(shiomiMarkName); });
});

var shiomiVisibleLifePeople = {};
var shiomiVisibleProfiles = {};
var shiomiVisibleRelations = {};
Object.keys(shiomiRelevantNames).forEach(function(name) {
  if (Object.prototype.hasOwnProperty.call(shiomiLifePeople, name)) shiomiVisibleLifePeople[name] = shiomiLifePeople[name];
  if (Object.prototype.hasOwnProperty.call(shiomiProfiles, name)) shiomiVisibleProfiles[name] = shiomiProfiles[name];
  if (Object.prototype.hasOwnProperty.call(shiomiRelations, name)) shiomiVisibleRelations[name] = shiomiRelations[name];
});

var shiomiVisibleState = {
  城市生活: {
    世界: shiomiObj(shiomiLife.世界),
    当前场景: shiomiScene,
    用户: shiomiUser,
    人物: shiomiVisibleLifePeople,
    日程: shiomiVisibleSchedules,
    公共信息: shiomiVisiblePublicInfo
  },
  人物档案: shiomiVisibleProfiles,
  警务事项索引: shiomiPoliceIndex,
  警务事项: shiomiVisibleEvents,
  人物关系: shiomiVisibleRelations,
  既有记录索引: {人物生活:Object.keys(shiomiLifePeople),人物档案:Object.keys(shiomiProfiles),人物关系:Object.keys(shiomiRelations),日程:Object.keys(shiomiSchedules),公共信息:Object.keys(shiomiPublicInfo)}
};


var shiomiRawState={城市生活:shiomiLife,人物档案:shiomiProfiles,警务事项:shiomiEvents,人物关系:shiomiRelations};
var shiomiFieldIndex={};
function shiomiIndexFields(view,raw,path){
  if(!view||typeof view!=='object'||Array.isArray(view)||!raw||typeof raw!=='object'||Array.isArray(raw))return;
  shiomiFieldIndex[path||'/']=Object.keys(raw).filter(function(k){return k!=='系统记录';});
  Object.keys(view).forEach(function(k){
    if(['系统记录','后台','当前可用案件资料','既有记录索引','警务事项索引'].indexOf(k)>=0)return;
    if(!Object.prototype.hasOwnProperty.call(raw,k))return;
    shiomiIndexFields(view[k],raw[k],path+'/'+String(k).replace(/~/g,'~0').replace(/\//g,'~1'));
  });
}
shiomiIndexFields(shiomiVisibleState,shiomiRawState,'');
shiomiVisibleState.可写字段索引=shiomiFieldIndex;
shiomiVisibleState.案件类型索引={};
Object.keys(shiomiVisibleEvents).forEach(function(name){
  var base=shiomiObj(shiomiObj(shiomiEvents[name]).基础),back=shiomiObj(shiomiObj(shiomiEvents[name]).后台);
  shiomiVisibleState.案件类型索引[name]=back.作者案件?'人工':base.案件来源==='自动生成'?'自动':'未明确';
});

var shiomiSpacetimeView = JSON.stringify({
  日期: String(shiomiWorld.日期 || ''),
  时间: String(shiomiWorld.时间 || ''),
  地点: String(shiomiScene.地点 || ''),
  在场人物: shiomiArr(shiomiScene.在场人物)
}, null, 2);
var shiomiVariableView = JSON.stringify(shiomiVisibleState, null, 2);
_%>
<current_spacetime>
<%- shiomiSpacetimeView %>
</current_spacetime>
<status_current_variable>
<%- shiomiVariableView %>
</status_current_variable>

---
变量更新规则:
  事实依据与旧记录继承:
    check:
      - "MVU保存当前状态、持续事项、长期关系和必要的历史。已有MVU是本轮更新基线，只修改实际发生或通过有效来源确认的变化；重复提及不算变化，不重新初始化已有记录。"
      - "本轮未提及、人物离场、事项暂时不受关注或记录未出现在裁剪视图中，都不自动使旧记录失效。已确认旧状态结束时应更新已确认的部分，未知的新状态不以正常、零值或初始值补齐。"
      - "只看到记录名称不能推断其内部字段、旧值或缺失情况。新增前核对既有记录索引，修改前使用已展示的目标字段；信息不足时不整段覆盖，也不另建同一事项绕开旧记录。"
      - "提议、准备、猜测、尚未完成的程序和预期结果不写成已经发生。禁止迁移语言：不得为了剧情功能预写人物发展、关系走向、犯罪、案件结果、命运或阶段目标，不用未来设定反推当前事实。"
      - "变量存在不等于人物知情。城市生活中的人物动态与警方当前案情仍须有相应的获知来源；后台和稳定人物资料也不能越过正文认知边界。"

  记录身份与变化类型:
    check:
      - "根据记录所指的人物、物件、约定或事件识别是否为同一对象，名称只承担识别作用。同一对象继续发展沿用原键，独立发生的新事项使用可区分的语义名称。"
      - "重述、引用、回忆或重复展示已有事实不新建记录、不重复结算。后来确实再次发生的行为按该类记录的保存条件处理，不能只因文字相同而忽略。"
      - "当前状态保存回复结束时仍有效的结果。历史记录保留当时发生、取得或说出的内容；补充、更正、撤回和失效须保留必要的原记录及对应关系。"
      - "当前判断根据有效依据维护。依据改变时只检查实际依赖它的判断；仍有充分独立依据的结论可以保留，依据不足的相应降级、修正或标明不再成立。"
      - "地点和在场人物只保存回复结束时的当前集合。中途发生的证言、调查、物品取得等若符合历史记录条件，仍保留必要经过，不因最终状态变化而遗漏。"
      - "同一事实跨字段产生实际影响时分别维护对应职责，例如交出物件会改变携带状态与案卷保管情况；没有事实依据时不机械联动联系方式、信任、伤病、司法处置或关系称谓。"

  数值、集合与修改范围:
    check:
      - "财务、数量依据实际收支与获得消耗计算；关系值依据已经形成的长期变化调整；当前强度按此刻状态记录，各自遵守字段语义。"
      - "同一变化只使用一次delta或一次最终值更新，不同时结算。delta要求目标已有有效数值；可靠信息明确最终值时可局部replace。旧值未知时不从零或中性值推算，不对说明性字符串做算术。"
      - "当前成员集合更新为完整现状；历史集合保留旧经过并追加新项；当前有效依据集合同时反映新增与失效。只掌握部分旧集合时不整段replace，不把本轮新增项冒充完整集合。"
      - "新建符合创建条件的记录，保留已有对象中未变化的字段。空串、空数组、false与remove仅在字段定义及明确事实支持清空、否定或移除时使用，不作未知占位。"
      - "历史时间、地点、来源按实际掌握的精度填写；未知可选项省略，已知“大约”“当天下午”等保留原精度。区分事情发生时间与获知时间，不为满足格式虚构分钟或场景。"

  分支与职责:
    check:
      - "城市生活记录生活状态，人物档案记录运行中新人物的稳定本体，警务事项记录警方处理及调查历史，人物关系记录角色对{{user}}的长期关系。同一记录不要在多个容器维护相互竞争的副本。"
      - "删除、编辑、重roll后的继承与回退由MVU处理。模型只根据当前分支有效基线生成本轮变化，不读取失效分支补回状态，不自行输出回滚补偿性加减。"
      - "讯匣脚本已经写入当前基线的事实再次被叙述时不重复结算；只有本轮另有实际变化才新增Patch。脚本同步批次标记仅约束对应脚本通道，不能替代对正文变化依据的判断。"
      - "既有记录索引、可写字段索引、警务事项索引、当前可用案件资料都是只读视图。系统记录由脚本维护，模型不得修改它及其父对象；读视图不得用作JSONPatch路径。"

  城市生活:
    type: |-
      {
        世界: {
          日期: string;
          时间: string;
          天气: string;
        };
        当前场景: {
          地点: string;
          在场人物: string[];
          远程互动人物: string[];
          亲密状态: '普通' | '浪漫亲密' | '性亲密' | '余韵';
          快感值: {
            用户: number;
            人物: {
              [角色名: string]: number;
            };
          };
        };
        用户: {
          居住: {
            住所: string;
            居住状态: string;
          };
          工作: {
            身份: string;
            单位: string;
            当前状态: string;
            职业声望: number;
            晋升意向: string;
            当前班次?: {
              开始: string;
              结束: string;
            };
          };
          财务: {
            [项目名: string]: number | string;
          };
          随身物品: {
            [物品名: string]: {
              数量: number | string;
              描述: string;
            };
          };
          待结款项?: {[事项名: string]: {性质: string; 对象: string; 未结金额: number | string; 状态: string; 来源: string; 币种?: string; 到期时间?: string;}};
          保管物品?: {[物品名: string]: {数量: number | string; 描述: string; 存放地点: string;}};
          身体: {
            状态: string;
            伤病: {
              [伤病名称: string]: {
                状态: string;
                描述: string;
              };
            };
          };
          交通工具: {
            [名称: string]: {
              类型: string;
              状态: string;
              停放地点?: string;
            };
          };
        };
        人物: {
          [角色名: string]: {
            最后所知位置?: {
              地点: string;
              时间?: string;
              依据: string;
            };
            工作状态?: string;
            身体状态?: string;
            司法状态?: string;
            联络状态?: string;
            联系方式?: {
              已取得: boolean;
              方式: string;
              来源: string;
              失效依据?: string;
            };
          };
        };
        日程: {
          [事项名称: string]: {
            领域: string;
            时间: string;
            地点?: string;
            人物: string[];
            内容: string;
            状态: string;
            来源: string;
          };
        };
        公共信息: {
          [事项名称: string]: {
            时间?: string;
            类别: string;
            内容: string;
            来源: string;
            状态: string;
            涉及人物?: string[];
          };
        };
      }
  城市生活.世界与当前场景:
    check:
      - "日期和时间沿用已有基线，仅按实际经过的时长、跨日或可靠校时更新。计划出发、预定抵达、回忆和未来约定不改变当前时间。"
      - "日期使用“景和七年四月三日•星期一”的完整格式。跨日同步推进日期与星期，月末和年末正常进位；景和七年平年、八年闰年，之后沿既定四年一闰规则处理二月，不按现实西历改算星期。"
      - "时间精度不超过事实依据。短暂行动无新时间依据可沿用旧值；明确经过较长时间但只知现为傍晚时，可以更新为傍晚，不能为保留分钟精度而编造时刻。可靠校时允许更正错误旧值。"
      - "天气依当前地点的实际观察或有效信息更新，预报保持预测性质，时间经过和进入室内不自动改变天气。跨区域后不能把原地局部天气无条件当作新地点现状；信息不足时保留地域限定，不猜测。"
