import 'https://testingcf.jsdelivr.net/gh/MagicalAstrogy/MagVarUpdate@beta/artifact/bundle.js';
import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

const NumOrText = z.union([z.number(), z.string()]);
const PleasureValue = z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0);
const ScheduleItem = z.object({
  领域: z.string().prefault(''),
  时间: z.string().prefault(''),
  地点: z.string().optional(),
  人物: z.array(z.string()).prefault([]),
  内容: z.string().prefault(''),
  状态: z.string().prefault(''),
  来源: z.string().prefault('')
}).passthrough();
const ContactInfo = z.object({
  已取得: z.boolean().prefault(false),
  失效依据: z.string().optional(),
  方式: z.string().prefault(''),
  来源: z.string().prefault('')
}).passthrough();
const LifePerson = z.object({
  最后所知位置: z.object({地点:z.string().prefault(''), 时间:z.string().optional(), 依据:z.string().prefault('')}).passthrough().optional(),
  工作状态: z.string().optional(),
  身体状态: z.string().optional(),
  联络状态: z.string().optional(),
  司法状态: z.string().optional(),
  联系方式: ContactInfo.optional()
}).passthrough();
const PublicInfo = z.object({
  时间: z.string().optional(),
  类别: z.string().prefault(''),
  内容: z.string().prefault(''),
  来源: z.string().prefault(''),
  状态: z.string().prefault(''),
  涉及人物: z.array(z.string()).optional()
}).passthrough();
const Profile = z.object({
  年龄: NumOrText.optional(),
  性别: z.string().optional(),
  身份: z.object({职业:z.string().optional(), 所属:z.string().optional(), 生活区域:z.string().optional()}).passthrough().optional(),
  外貌: z.string().optional(),
  人格: z.record(z.string(), z.string()).optional(),
  生活与关系: z.string().optional()
}).passthrough();
const PoliceArrangement = z.object({
  时间: z.string().prefault(''),
  地点: z.string().optional(),
  人物: z.array(z.string()).prefault([]),
  内容: z.string().prefault(''),
  状态: z.string().prefault(''),
  来源: z.string().prefault('')
}).passthrough();
const PoliceInvestigationClue = z.object({
  问题: z.string().prefault(''),
  依据: z.array(z.string()).prefault([]),
  状态: z.string().prefault('未调查'),
  调查结果: z.array(z.string()).prefault([])
}).passthrough();
const PoliceFormalConclusion = z.object({
  内容: z.string().optional(),
  结果: z.string().optional(),
  当前依据: z.array(z.string()).optional(),
  时间: z.string().optional()
}).passthrough().prefault({});
const PoliceMatter = z.object({
  基础: z.object({
    性质: z.string().prefault(''),
    处理性质: z.string().prefault(''),
    状态: z.string().prefault(''),
    案件来源: z.string().optional(),
    阶段: z.string().prefault(''),
    发生时间: z.string().prefault(''),
    发生地点: z.string().prefault(''),
    来源: z.string().prefault(''),
    受理时间: z.string().optional(),
    声望结算:z.object({已计入:z.union([z.literal(-1),z.literal(0),z.literal(1)]),结论结果:z.enum(['成立','证据不足','不成立'])}).passthrough().optional()
  }).passthrough().prefault({}),
  当前案情: z.object({
    事件: z.string().prefault(''),
    人物: z.record(z.string(), z.string()).prefault({}),
    人物说法: z.record(z.string(), z.record(z.string(), z.union([z.string(), z.object({
      时间:z.string().optional(),场景:z.string().optional(),主题:z.string().prefault(''),内容:z.string(),
      性质:z.enum(['初次陈述','补充','更正','撤回','拒绝说明']).prefault('初次陈述'),对应:z.string().optional()
    }).passthrough()]))).prefault({}),
    调查记录: z.record(z.string(),z.object({时间:z.string().optional(),场景:z.string().optional(),类型:z.string().prefault(''),摘要:z.string(),关联:z.array(z.string()).optional()}).passthrough()).prefault({}),
    已掌握痕迹: z.record(z.string(), z.object({
      内容: z.string().prefault(''),
      取得时间: z.string().optional(),
      取得地点: z.string().optional(),
      当前状态: z.string().prefault(''),
      来源: z.string().optional()
    }).passthrough()).prefault({}),
    已确认事实: z.record(z.string(), z.object({
      内容: z.string().prefault(''),
      依据: z.array(z.string()).prefault([]),
      性质: z.string().prefault(''),
      修订记录:z.record(z.string(),z.object({原内容:z.string(),原性质:z.string(),原依据:z.array(z.string()),变更原因:z.string(),时间:z.string().optional()}).passthrough()).optional()
    }).passthrough()).prefault({}),
    调查线索: z.record(z.string(), PoliceInvestigationClue).optional(),
    正式结论: PoliceFormalConclusion,
    结案结论: z.string().optional()
  }).passthrough().prefault({}),
  安排: z.record(z.string(), PoliceArrangement).prefault({}),
  后台: z.object({
    作者案件: z.object({案件ID:z.string(),已开放内容:z.record(z.string(),z.literal(true)).optional()}).passthrough().optional(),
    真实情况: z.object({
      概要: z.string().prefault(''),
      因果链: z.array(z.string()).prefault([]),
      社会背景: z.array(z.string()).prefault([])
    }).passthrough().optional(),
    人物认知: z.record(z.string(), z.object({
      事件位置: z.string().prefault(''),
      亲历事实: z.array(z.string()).prefault([]),
      已知事实: z.array(z.string()).prefault([]),
      误解: z.array(z.string()).prefault([]),
      隐瞒事实: z.array(z.string()).prefault([]),
      当前顾虑: z.array(z.string()).prefault([])
    }).passthrough()).optional(),
    客观事实: z.record(z.string(), z.object({
      内容: z.string().prefault(''),
      来源基础: z.string().prefault('')
    }).passthrough()).optional(),
    客观痕迹: z.record(z.string(), z.object({
      内容: z.string().prefault(''),
      当前状态: z.string().prefault(''),
      形成原因: z.string().prefault(''),
      当前所在: z.string().prefault(''),
      接触门槛: z.enum(['直接可见','针对检查','程序结果']),
      取得条件: z.array(z.string()).prefault([]),
      支持事实: z.array(z.string()).prefault([])
    }).passthrough()).optional(),
    线索对应: z.record(z.string(), z.object({
      客观事实: z.array(z.string()).prefault([]),
      客观痕迹: z.array(z.string()).prefault([]),
      人物认知: z.array(z.string()).prefault([])
    }).passthrough()).optional(),
    结论边界: z.object({
      核心问题: z.array(z.string()).prefault([]),
      关键证明: z.record(z.string(), z.object({
        结论: z.string().prefault(''),
        客观事实: z.array(z.string()).prefault([]),
        客观痕迹: z.array(z.string()).prefault([])
      }).passthrough()).optional(),
      无法充分证明: z.array(z.string()).prefault([])
    }).passthrough().optional(),
    系统标识: z.object({
      类型: z.string().prefault(''),
      案件ID: z.string().prefault('')
    }).passthrough().optional()
  }).passthrough().optional()
}).passthrough();

const Relation = z.object({
  好感度: z.coerce.number().transform(v => _.clamp(v, 0, 200)).prefault(100),
  信任度: z.coerce.number().transform(v => _.clamp(v, 0, 200)).prefault(100),
  熟悉度: z.coerce.number().transform(v => _.clamp(v, 0, 200)).prefault(0),
  友情值: z.coerce.number().transform(v => _.clamp(v, 0, 200)).prefault(0),
  爱情值: z.coerce.number().transform(v => _.clamp(v, 0, 200)).prefault(0),
  关系状态: z.string().prefault('初识')
}).passthrough();

export const Schema = z.object({
  系统记录: z.object({讯匣同步:z.record(z.string(),z.boolean()).prefault({})}).passthrough().optional(),
  城市生活: z.object({
    世界: z.object({日期:z.string().prefault(''), 时间:z.string().prefault(''), 天气:z.string().prefault('')}).passthrough().prefault({}),
    当前场景: z.object({地点:z.string().prefault(''), 在场人物:z.array(z.string()).prefault([]), 远程互动人物:z.array(z.string()).prefault([]), 亲密状态:z.enum(['普通','浪漫亲密','性亲密','余韵']).prefault('普通'), 快感值:z.object({用户:PleasureValue, 人物:z.record(z.string(), PleasureValue).prefault({})}).passthrough().prefault({})}).passthrough().prefault({}),
    用户: z.object({
      居住: z.object({住所:z.string().prefault(''), 居住状态:z.string().prefault('')}).passthrough().prefault({}),
      工作: z.object({身份:z.string().prefault(''), 单位:z.string().prefault(''), 当前状态:z.string().prefault(''), 职业声望:z.coerce.number().prefault(0), 晋升意向:z.string().prefault('未表态'), 当前班次:z.object({开始:z.string().prefault(''),结束:z.string().prefault('')}).passthrough().optional()}).passthrough().prefault({}),
      财务: z.record(z.string(), NumOrText).prefault({}),
      待结款项:z.record(z.string(),z.object({性质:z.string(),对象:z.string(),未结金额:NumOrText,状态:z.string(),来源:z.string(),币种:z.string().optional(),到期时间:z.string().optional()}).passthrough()).optional(),
      保管物品:z.record(z.string(),z.object({数量:NumOrText,描述:z.string(),存放地点:z.string()}).passthrough()).optional(),
      随身物品: z.record(z.string(), z.object({数量:NumOrText, 描述:z.string()}).passthrough()).prefault({}),
      身体: z.object({状态:z.string().prefault(''), 伤病:z.record(z.string(), z.object({状态:z.string(), 描述:z.string()}).passthrough()).prefault({})}).passthrough().prefault({}),
      交通工具: z.record(z.string(), z.object({类型:z.string(), 状态:z.string(), 停放地点:z.string().optional()}).passthrough()).prefault({})
    }).passthrough().prefault({}),
    人物: z.record(z.string(), LifePerson).prefault({}),
    日程: z.record(z.string(), ScheduleItem).prefault({}),
    公共信息: z.record(z.string(), PublicInfo).prefault({})
  }).passthrough().prefault({}),
  人物档案: z.record(z.string(), Profile).prefault({}),
  警务事项: z.record(z.string(), PoliceMatter).prefault({}),
  人物关系: z.record(z.string(), Relation).prefault({})
}).passthrough();

const SHIOMI_INITIAL_STATE = {"城市生活":{"世界":{"日期":"景和七年四月三日•星期一","时间":"约14:25","天气":""},"当前场景":{"地点":"汐见中央警署一楼接待窗口前","在场人物":[],"远程互动人物":[],"亲密状态":"普通","快感值":{"用户":0,"人物":{}}},"用户":{"居住":{"住所":"汐见市鹤见町临河公寓","居住状态":"独居"},"工作":{"身份":"刑警","单位":"汐见中央警署","当前状态":"调任报到","职业声望":0,"晋升意向":"未表态"},"财务":{"现金":240,"银行存款":6800},"随身物品":{"皮箱":{"数量":1,"描述":"装有几件衣物与剑道服"},"调任文件":{"数量":1,"描述":"装在牛皮纸袋中，用于汐见中央警署刑事课调任报到"}},"身体":{"状态":"无已知异常","伤病":{}},"交通工具":{}},"人物":{},"日程":{"调任报到":{"领域":"工作","时间":"今日下午","地点":"汐见中央警署","人物":[],"内容":"前往汐见中央警署刑事课办理调任报到","状态":"进行中","来源":"调任安排"}},"公共信息":{}},"人物档案":{},"警务事项":{},"人物关系":{}};
let shiomiInitFallbackRan = false;
function shiomiHasStatData(data){
  const stat=data?.stat_data;
  return !!(stat&&typeof stat==='object'&&['城市生活','人物关系','人物档案','警务事项'].some(k=>stat[k]&&typeof stat[k]==='object'&&Object.keys(stat[k]).length));
}
function shiomiChatRows(){
  try{return SillyTavern.getContext().chat||[];}catch(_){return [];}
}
async function shiomiEnsureInitialState(){
  if(shiomiInitFallbackRan)return;shiomiInitFallbackRan=true;
  const origin=shiomiChatRows();
  try{
    if(typeof waitGlobalInitialized!=='function')return;
    const api=await waitGlobalInitialized('Mvu');
    if(!api||typeof api.getMvuData!=='function')return;
    await new Promise(resolve=>setTimeout(resolve,1200));
    if(shiomiChatRows()!==origin)return;
    const id=origin.length-1;if(id<0)return;
    const scope={type:'message',message_id:id},current=api.getMvuData(scope)||{};
    if(shiomiHasStatData(current))return;


    if(id>0){
      console.warn('[ShiomiMVU] 后续楼层暂缺变量，等待MVU从当前分支历史继承；未使用开场初始值。');return;
    }
    if(origin[0]?.is_user)return;
    const latest=api.getMvuData(scope)||{};
    if(shiomiHasStatData(latest)||shiomiChatRows()!==origin||origin.length!==1)return;
    const next={...latest,initialized_lorebooks:latest.initialized_lorebooks||{},stat_data:Schema.parse(SHIOMI_INITIAL_STATE)};
    if(typeof api.replaceMvuData==='function')await api.replaceMvuData(next,scope);
    try{if(api.events?.VARIABLE_INITIALIZED&&typeof eventEmit==='function')eventEmit(api.events.VARIABLE_INITIALIZED,next,0);}catch(_){}
  }catch(err){console.warn('[ShiomiMVU] 开局变量兜底初始化失败',err);}
}

$(() => {
  registerMvuSchema(Schema);
  void shiomiEnsureInitialState();
});




const SHIOMI_XUN_VERSION = 60;
const SHIOMI_XUN_STORE_KEY = '$迅网';
const SHIOMI_XUN_CONFIG_KEY = '$迅网设置';
