const SHIOMI_XUN_SKIP_ENTRY = /^(?:\[initvar\]|\[mvu_update\]|变量列表|【分阶段人设】|【讯匣提示词】|【讯匣分类】|【讯匣账户类型】|【购务提示词】|【购务价目】)/;

const xunClone = value => JSON.parse(JSON.stringify(value ?? null));
const xunObj = value => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const xunArr = value => Array.isArray(value) ? value : [];
const xunNow = () => new Date().toISOString();
const xunId = prefix => `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 9)}`;
const xunText = value => String(value ?? '').trim();
const xunUnique = values => [...new Set(xunArr(values).map(xunText).filter(Boolean))];

function xunSubstituteMacros(text) {
  const raw = String(text ?? '');
  try {
    if (typeof substitudeMacros === 'function') return String(substitudeMacros(raw) ?? raw);
  } catch (_) {}
  let user = '', char = '';
  try {
    const ctx = SillyTavern?.getContext?.();
    user = xunText(ctx?.name1 || ctx?.userName || ctx?.user_name);
    char = xunText(ctx?.name2 || ctx?.characterName || ctx?.char_name);
  } catch (_) {}
  return raw
    .replace(/\{\{user\}\}/gi, user || '我')
    .replace(/\{\{char\}\}/gi, char || '');
}
function xunIsUserMacro(value) {
  const raw = xunText(value);
  return /^\{\{user\}\}$/i.test(raw) || (!!raw && raw !== '我' && xunSubstituteMacros(raw) === xunCurrentUserName());
}
function xunCurrentUserName() {
  try {
    const macro = xunText(typeof substitudeMacros === 'function' ? substitudeMacros('{{user}}') : '');
    if (macro && macro !== '{{user}}') return macro;
  } catch (_) {}
  try {
    const ctx = SillyTavern?.getContext?.();
    return xunText(ctx?.name1 || ctx?.userName || ctx?.user_name) || '我';
  } catch (_) { return '我'; }
}

function xunChatRows() {
  try {
    const ctx = SillyTavern?.getContext?.();
    return Array.isArray(ctx?.chat) ? ctx.chat : [];
  } catch (_) { return []; }
}

function xunHash(text) {
  let h = 2166136261;
  const s = String(text || '');
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return (h >>> 0).toString(36);
}

function xunRowSwipeId(row) {
  const raw = row?.swipe_id ?? row?.swipeId ?? row?.extra?.swipe_id ?? 0;
  const n = Number(raw);
  return Number.isInteger(n) && n >= 0 ? n : 0;
}

function xunRowBody(row, swipeId = null) {
  const sid = swipeId == null ? xunRowSwipeId(row) : Math.max(0, Number(swipeId) || 0);
  const current = xunText(row?.mes || row?.message || row?.content || row?.text);
  if (current) return current;
  const swipes = Array.isArray(row?.swipes) ? row.swipes : [];
  if (swipes[sid] != null) return xunText(swipes[sid]);
  return '';
}

function xunRowSendDate(row) {
  return xunText(row?.send_date || row?.sendDate || row?.extra?.send_date || '');
}

function xunNormalizeAnchor(anchor) {
  const a = xunObj(anchor);
  const mid = Number(a.messageId);
  const sid = Number(a.swipeId);
  return {
    messageId: Number.isInteger(mid) && mid >= 0 ? mid : null,
    swipeId: Number.isInteger(sid) && sid >= 0 ? sid : null,
    fingerprint: xunText(a.fingerprint),
    sendDate: xunText(a.sendDate),
    at: xunText(a.at)
  };
}

function xunAnchor() {
  const rows = xunChatRows();
  const id = Math.max(0, rows.length - 1);
  const row = rows[id] || {};
  const swipeId = xunRowSwipeId(row);
  const body = xunRowBody(row, swipeId);
  return { messageId: id, swipeId, fingerprint: xunHash(body), sendDate: xunRowSendDate(row), at: xunNow() };
}

function xunAnchorMatchesRow(anchor, row) {
  const a = xunNormalizeAnchor(anchor);
  if (!row) return false;
  const currentSwipe = xunRowSwipeId(row);
  if (a.swipeId != null && currentSwipe !== a.swipeId) return false;
  if (a.sendDate && xunRowSendDate(row) && a.sendDate !== xunRowSendDate(row)) return false;
  const body = xunRowBody(row, currentSwipe);
  return !a.fingerprint || xunHash(body) === a.fingerprint;
}

function xunResolveAnchor(anchor) {
  if (!anchor || typeof anchor !== 'object') return { alive: true, anchor: null, moved: false };
  const a = xunNormalizeAnchor(anchor);
  if (a.messageId == null) return { alive: true, anchor: a, moved: false };
  const rows = xunChatRows();
  const direct = rows[a.messageId];
  if (direct && xunAnchorMatchesRow(a, direct)) {
    const next = { ...a, swipeId: xunRowSwipeId(direct), sendDate: a.sendDate || xunRowSendDate(direct) };
    return { alive: true, anchor: next, moved: false };
  }
  if (!a.fingerprint) return { alive: false, anchor: a, moved: false };
  let bestId = -1, bestDistance = Infinity;
  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    if (!xunAnchorMatchesRow(a, row)) continue;
    const distance = Math.abs(i - a.messageId);
    if (distance < bestDistance) { bestId = i; bestDistance = distance; }
  }
  if (bestId < 0) return { alive: false, anchor: a, moved: false };
  const row = rows[bestId] || {};
  return {
    alive: true,
    moved: bestId !== a.messageId,
    anchor: { ...a, messageId: bestId, swipeId: xunRowSwipeId(row), sendDate: a.sendDate || xunRowSendDate(row) }
  };
}

function xunAnchorAlive(anchor) {
  return xunResolveAnchor(anchor).alive;
}

function xunDefaultStore() {
  return {
    version: SHIOMI_XUN_VERSION,
    accounts: {},
    posts: {},
    postOrder: [],
    chats: {},
    rooms: {},
    media: {},
    memories: [],
    agreements:{},agreementReceipts:{},agreementMigrationVersion:0,
    notifications: [],
    signals: { likes: {}, follows: {}, hiddenPosts: {} },
    meta: { lastFeedAt: '', lastStateSyncAt: '', lastMemoryAt: '', createdAt: xunNow() }
  };
}

function xunNormalizeAccount(account, fallbackId = '') {
  const a = xunObj(account);
  const id = xunText(a.id || fallbackId) || xunId('acct');
  const privateOnly = a.privateOnly === true;
  const fallbackHandle = `@${xunText(a.displayName || a.name || id).replace(/\s+/g, '')}`;
  return {
    id,
    kind: ['user','character','local','anonymous','institution','commercial','underground','adult_personal'].includes(a.kind) ? a.kind : 'local',
    displayName: xunText(xunSubstituteMacros(a.displayName || a.name || id)),
    handle: privateOnly ? xunText(xunSubstituteMacros(a.handle)) : xunText(xunSubstituteMacros(a.handle || fallbackHandle)),
    characterName: xunText(xunSubstituteMacros(a.characterName)),
    userRelationship: xunText(a.userRelationship).slice(0,1800),
    mvuName: xunText(a.mvuName).slice(0,80),
    identityAliases: xunText(a.identityAliases).slice(0,1800),
    bio: xunText(a.bio).slice(0, 500),
    background: xunText(a.background).slice(0, 4000),
    entityType: xunEntityType(a),
    person: xunProfileObject(a.person, XUN_PERSON_FIELDS),
    portrait: {media:xunArr(a.portrait?.media).filter(id=>typeof id==='string').slice(-2),anchor:a.portrait?.anchor||a.anchor||null},
    company: xunProfileObject(a.company, XUN_COMPANY_FIELDS),
    profileRevision: Math.max(0,Number(a.profileRevision)||0),
    profileHistory: xunArr(a.profileHistory).filter(h=>h&&Array.isArray(h.changes)),
    referenceOnly: a.referenceOnly === true,
    introduction: xunText(a.introduction).slice(0, 1600),
    topics: xunUnique(a.topics).slice(0, 12),
    avatar: xunText(a.avatar),
    privateOnly,
    anchor: a.anchor ? xunNormalizeAnchor(a.anchor) : null
  };
}

function xunAccountEqual(a,b) {
  try {
    const aa=xunNormalizeAccount(a, a?.id||''), bb=xunNormalizeAccount(b, b?.id||'');
    return aa.id===bb.id && aa.kind===bb.kind && aa.displayName===bb.displayName && aa.handle===bb.handle && aa.characterName===bb.characterName && aa.bio===bb.bio && aa.background===bb.background && aa.referenceOnly===bb.referenceOnly && aa.introduction===bb.introduction && aa.avatar===bb.avatar && aa.privateOnly===bb.privateOnly && JSON.stringify(aa.topics)===JSON.stringify(bb.topics) && JSON.stringify(aa.anchor)===JSON.stringify(bb.anchor);
  } catch (_) { return false; }
}

function xunNormalizeStore(raw) {
  const base = xunDefaultStore();
  const src = xunObj(raw);
  const out = { ...base, ...src };
  out.version = SHIOMI_XUN_VERSION;
  out.accountDatabaseVersion = 1;
  out.accounts = {};
  for (const [id, a] of Object.entries(xunObj(src.accounts))) out.accounts[id] = xunNormalizeAccount(a, id);
  out.posts = xunObj(src.posts);
  for (const p of Object.values(out.posts)) if (p && (p.category === '成人商业' || p.category === '情色行业')) p.category = '情色商业';
  out.postOrder = xunUnique(src.postOrder).filter(id => out.posts[id]);
  out.chats = xunObj(src.chats);
  for (const chat of Object.values(out.chats)) if (chat && typeof chat === 'object') chat.unread = Math.max(0, Number(chat.unread) || 0);
  out.rooms = xunObj(src.rooms);
  for (const room of Object.values(out.rooms)) if (room && typeof room === 'object') room.unread = Math.max(0, Number(room.unread) || 0);
  out.media = xunObj(src.media);
  out.narrativePersonaSources=xunObj(src.narrativePersonaSources);
  out.agreements=xunObj(src.agreements);out.agreementReceipts=xunObj(src.agreementReceipts);out.agreementMigrationVersion=Number(src.agreementMigrationVersion)||0;
  out.memories = xunArr(src.memories).filter(m => m && typeof m === 'object');
  out.notifications = xunArr(src.notifications).filter(n => n && typeof n === 'object').map(n => ({ ...n, read: n.read === true }));
  const sig=xunObj(src.signals); out.signals={likes:xunObj(sig.likes),follows:xunObj(sig.follows),hiddenPosts:xunObj(sig.hiddenPosts)};
  out.meta = { ...base.meta, ...xunObj(src.meta) };
  return out;
}

function xunGetChatVariables() {
  try { return xunObj(getVariables({ type: 'chat' })); } catch (_) { return {}; }
}

