      const ret = bus.on(name, fn);
      if (typeof ret === 'function') return ret;
      return () => { try { if (typeof bus.off === 'function') bus.off(name, fn); else if (typeof bus.removeListener === 'function') bus.removeListener(name, fn); } catch (_) {} };
    }
  } catch (_) {}
