        try {
          const gen = obj.getModule('imageGen');
          if (gen && xunImageGeneratorScore(gen) >= 4) candidates.push({ gen, label: '统一生成器', score: 35 + xunImageGeneratorScore(gen) });
        } catch (_) {}
      }
      for (const k of ['imageGen','imageGenerator','generator','GeneratorManager']) {
        try {
          const gen = obj[k];
          if (gen && xunImageGeneratorScore(gen) >= 4) candidates.push({ gen, label: '统一生成器', score: 25 + xunImageGeneratorScore(gen) });
        } catch (_) {}
      }
      const score = xunImageGeneratorScore(obj);
      if (score >= 10) candidates.push({ gen: obj, label: '统一生成器', score });
    } catch (_) {}
  };
  for (const w of xunWindowList()) {
    try {
      for (const key of Object.getOwnPropertyNames(w).slice(0, 700)) {
        let obj; try { obj = w[key]; } catch (_) { continue; }
        if (/image|scene|draw|generator|plugin/i.test(String(key)) || typeof obj?.getModule === 'function' || typeof obj?.generateFromPrompt === 'function') push(obj);
      }
