function xunBytesToDataUrl(bytes, mime = 'image/png') {
  let binary = '', chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) binary += String.fromCharCode(...bytes.subarray(i, Math.min(bytes.length, i + chunk)));
  return `data:${mime};base64,${btoa(binary)}`;
}

async function xunImageValue(v, depth = 0) {
  if (v == null || depth > 6) return '';
  if (typeof v === 'string') {
    const t = v.trim(); if (!t) return '';
    if (/^data:image\//i.test(t) || /^blob:/i.test(t) || /^https?:\/\//i.test(t) || /^\/[^/]/.test(t)) return t;
    const compact = t.replace(/\s+/g, '');
    if (compact.length > 800 && /^[A-Za-z0-9+/=]+$/.test(compact)) return 'data:image/png;base64,' + compact;
    try { return await xunImageValue(JSON.parse(t), depth + 1); } catch (_) {}
    return '';
  }
  try { if (typeof Blob !== 'undefined' && v instanceof Blob) return xunBytesToDataUrl(new Uint8Array(await v.arrayBuffer()), v.type || 'image/png'); } catch (_) {}
  try { if (v instanceof ArrayBuffer) return xunBytesToDataUrl(new Uint8Array(v)); } catch (_) {}
  try { if (ArrayBuffer.isView(v)) return xunBytesToDataUrl(new Uint8Array(v.buffer, v.byteOffset, v.byteLength)); } catch (_) {}
  if (Array.isArray(v)) { for (const x of v) { const r = await xunImageValue(x, depth + 1); if (r) return r; } return ''; }
  if (typeof v === 'object') {
    for (const k of ['imageData','image','imageUrl','url','serverPath','src','b64_json','base64','output','data','result','file','path']) {
      if (Object.prototype.hasOwnProperty.call(v, k)) { const r = await xunImageValue(v[k], depth + 1); if (r) return r; }
    }
    for (const k of Object.keys(v)) { const r = await xunImageValue(v[k], depth + 1); if (r) return r; }
  }
  return '';
}

const SHIOMI_XUN_IMAGE_DB = 'SHIOMI_XUN_IMAGE_CACHE_V1';
const SHIOMI_XUN_IMAGE_STORE = 'images';
const xunImageMemCache = new Map();
let xunImageDbPromise = null;

function xunOpenImageDb() {
  if (xunImageDbPromise) return xunImageDbPromise;
  xunImageDbPromise = new Promise((resolve, reject) => {
    try {
      let idb = null;
      for (const w of xunWindowList()) { try { if (w?.indexedDB) { idb = w.indexedDB; break; } } catch (_) {} }
      if (!idb) throw new Error('当前环境不支持 IndexedDB。');
      const req = idb.open(SHIOMI_XUN_IMAGE_DB, 1);
      req.onupgradeneeded = () => { const db = req.result; if (!db.objectStoreNames.contains(SHIOMI_XUN_IMAGE_STORE)) db.createObjectStore(SHIOMI_XUN_IMAGE_STORE, { keyPath: 'id' }); };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error || new Error('讯匣图片缓存数据库打不开。'));
    } catch (err) { reject(err); }
  }).catch(err => { xunImageDbPromise = null; throw err; });
  return xunImageDbPromise;
}

async function xunImageDbPut(id, src) {
  const db = await xunOpenImageDb();
  return await new Promise((resolve, reject) => {
    try {
      const tx = db.transaction(SHIOMI_XUN_IMAGE_STORE, 'readwrite');
      tx.objectStore(SHIOMI_XUN_IMAGE_STORE).put({ id, src, updatedAt: Date.now() });
      tx.oncomplete = () => resolve(id);
      tx.onerror = () => reject(tx.error || new Error('讯匣图片缓存写入失败。'));
    } catch (err) { reject(err); }
  });
}

async function xunImageDbGet(id) {
  if (xunImageMemCache.has(id)) return xunImageMemCache.get(id) || '';
  try {
    const db = await xunOpenImageDb();
    const src = await new Promise((resolve, reject) => {
      const tx = db.transaction(SHIOMI_XUN_IMAGE_STORE, 'readonly'), req = tx.objectStore(SHIOMI_XUN_IMAGE_STORE).get(id);
      req.onsuccess = () => resolve(req.result?.src ? String(req.result.src) : '');
      req.onerror = () => reject(req.error || new Error('讯匣图片缓存读取失败。'));
    });
    if (src) xunImageMemCache.set(id, src);
    return src;
  } catch (_) { return ''; }
}

async function xunImageDbDelete(id) {
  id=xunText(id); if(!id)return false;
  xunImageMemCache.delete(id);
  try{
    const db=await xunOpenImageDb();
    await new Promise((resolve,reject)=>{
      const tx=db.transaction(SHIOMI_XUN_IMAGE_STORE,'readwrite');
      tx.objectStore(SHIOMI_XUN_IMAGE_STORE).delete(id);
      tx.oncomplete=()=>resolve(true);
      tx.onerror=()=>reject(tx.error||new Error('讯匣图片缓存删除失败。'));
    });
    return true;
  }catch(_){return false;}
}

