async function xunGenerateImageEvent({ prompt, negative = '', width, height, timeout = 180000, transparent_background = false }) {
  const bus = xunImageEventSource();
  if (!bus || !xunImageEventBridgeActive()) throw new Error('当前没有活动的酒馆画图插件事件。');
  const id = `shiomi_img_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,8)}`;
  return await new Promise((resolve, reject) => {
    let done = false;
    const finish = (fn, v) => { if (done) return; done = true; clearTimeout(timer); try { off(); } catch (_) {} fn(v); };
    const handler = async data => {
      if (!data || String(data.id || '') !== id) return;
      if (data.success === false) return finish(reject, new Error(String(data.error || '酒馆画图插件返回失败。')));
      const val = data.imageData || data.image || data.imageUrl || data.url || data.result || data.data;
      if (!val) return finish(reject, new Error('酒馆画图插件没有返回图片数据。'));
      const image = await xunImageValue(val);
      if (!image) return finish(reject, new Error('酒馆画图插件返回内容中没有可识别图片。'));
      finish(resolve, image);
    };
    const off = xunBusOn(bus, 'generate-image-response', handler);
    const timer = setTimeout(() => finish(reject, new Error('酒馆画图插件等待超时。')), Math.max(30000, Number(timeout) || 180000));
    try {
      bus.emit('generate-image-request', { id, prompt: xunText(prompt), negative_prompt: xunText(negative), width: Number(width) || undefined, height: Number(height) || undefined, source: 'shiomi-xun', skipInsertToChat: true, transparent_background });
    } catch (err) { finish(reject, err); }
  });
}

async function xunGenerateImagePublic({ prompt, negative = '', width, height, timeout = 180000, transparent_background = false }, candidate) {
  const gen = candidate?.gen;
  if (!gen) throw new Error('没有找到可调用的酒馆画图插件生成器。');
  const snapshot = xunChatImageSnapshot();
  let completed = null, errorPayload = null; const cleanups = [];
  const bus = gen?.ctx?.events || gen?.pluginContext?.events || gen?.events || null;
  const add = (name, fn) => { try { if (bus && typeof bus.on === 'function') { const ret = bus.on(name, fn); cleanups.push(typeof ret === 'function' ? ret : () => { try { bus.off?.(name, fn); } catch (_) {} }); } } catch (_) {} };
  for (const n of ['IMAGE_GEN_COMPLETE','image-gen:complete','image_gen_complete','image-generation-complete']) add(n, p => { completed = p && Object.prototype.hasOwnProperty.call(p, 'result') ? p.result : p; });
  for (const n of ['IMAGE_GEN_ERROR','image-gen:error','image_gen_error','image-generation-error']) add(n, p => { errorPayload = p; });
  const options = { skipAiProcessing: true, skipInsertToChat: true, insertToChat: false, autoInsert: false, isModalCall: true, transparent_background, transparentBackground:transparent_background, width: Number(width) || undefined, height: Number(height) || undefined };
  try {
    let result;
    if (typeof gen.generateFromPrompt === 'function') result = await gen.generateFromPrompt(xunText(prompt), xunText(negative), options);
    else if (typeof gen.generateImageFromPrompt === 'function') result = await gen.generateImageFromPrompt(xunText(prompt), xunText(negative), options);
    else if (typeof gen.txt2img === 'function') result = await gen.txt2img({ prompt: xunText(prompt), negative_prompt: xunText(negative), ...options });
    else if (typeof gen.text2img === 'function') result = await gen.text2img({ prompt: xunText(prompt), negative_prompt: xunText(negative), ...options });
    else if (typeof gen.generateImage === 'function') { try { result = await gen.generateImage({ prompt: xunText(prompt), negative_prompt: xunText(negative), ...options }); } catch (_) { result = await gen.generateImage(xunText(prompt), xunText(negative), options); } }
    else throw new Error('当前酒馆画图插件没有提供可直接调用的提示词入口。');
    let image = await xunImageValue(result);
    const until = Date.now() + Math.min(Math.max(1200, Number(timeout) || 180000), 18000);
    while (!image && Date.now() < until) {
      if (completed != null) { image = await xunImageValue(completed); completed = null; if (image) break; }
      if (errorPayload) { const msg = errorPayload?.error ? (errorPayload.error.message || String(errorPayload.error)) : String(errorPayload); throw new Error(msg); }
      await new Promise(r => setTimeout(r, 120));
    }
    if (!image) throw new Error('酒馆画图插件完成了调用，但没有返回图片结果。');
    return image;
  } finally {
    for (const fn of cleanups) { try { fn(); } catch (_) {} }
    await xunRestoreUnexpectedImageInsert(snapshot);
    setTimeout(() => xunRestoreUnexpectedImageInsert(snapshot), 280);
  }
}

