async function xunGeneratePostImages(postId, { limit = 0 } = {}) {
  let store = xunGetStore();
  const post = store.posts[xunText(postId)];
  if (!post) throw new Error('帖子不存在。');
  const cfg = xunGetConfig();
  const max = Math.max(1, Math.min(3, Number(limit) || Number(cfg.imageMaxPerPost) || 3));
  const prompts = xunImageContent(post).prompts.slice(0,max);
  if (!prompts.length) throw new Error('这条帖子没有可用的画图提示。');
  const result = [];
