async function xunRequiredWorldContext(task, user) {
  const ctx=xunSillyTavernContext(),character=ctx?.characters?.[ctx.characterId];
  const books=[],add=v=>{v=xunText(v);if(v&&!books.includes(v))books.push(v);};
  try{const bound=await getCharWorldbookNames('current');add(bound?.primary);xunArr(bound?.additional).forEach(add);}catch(_){}
  try{add(xunAccountBookFn('getChatWorldbookName')?.('current'));}catch(_){}
  const archive=xunAccountBookState();if(archive.scope===xunAccountBookScope())add(archive.name);
  add(character?.data?.extensions?.world);
  add(xunGetConfig().shiomiWorldbook);
  const entries=[];
  for(const book of books)entries.push(...await xunLoadWorldbookEntries(book,true));
  if(!xunLooksLikeShiomi(entries)){
    const embedded=character?.data?.character_book||character?.character_book;
    entries.push(...xunArr(embedded?.entries).map((e,i)=>({...e,$book:'当前角色卡',$index:i})));
  }
  if(!entries.length)throw new Error('未能读取当前角色卡世界书，本次生成已停止。请先确认角色卡已绑定世界书。');
  const stat=xunStatRoot(await xunMvuData()),corpus=xunSubstituteMacros(String(user||'').split('\n\n【账号索引】')[0]);
  const base=/^【(?:世界|时代|技术|经济|制度|社会|生活|文化|城市|汐见|地区|设备|视觉)卷】/;
  const related=/^【(?:地点|机构|产业|人物|角色|分阶段人设)卷?】|^【讯匣(?:人物|机构)档案】/;
  const seen=new Set(),parts=[];
  for(const entry of entries){
    if(!xunEntryEnabled(entry))continue;
    const title=xunWorldbookEntryTitle(entry),core=base.test(title);
    const label=title.replace(/^【[^】]+】/,'');
    const matched=related.test(title)&&(xunEntryMatches(entry,corpus)||(label&&corpus.includes(xunSubstituteMacros(label))));
    if(!core&&!matched)continue;
    const raw=String(entry.content||'');
    const content=xunSubstituteMacros(raw.includes('<%')?xunRenderEjsTemplate(raw,stat):raw).trim();
    if(!content){if(core&&raw.trim())throw new Error('世界观条目无法读取：'+title);continue;}
    if(seen.has(content))continue;seen.add(content);
    const escaped=JSON.stringify(content).slice(1,-1);
    if(corpus.includes(content)||corpus.includes(escaped))continue;
    parts.push(`【角色卡世界书：${entry.$book} / ${title}】\n${content}`);
  }
  return parts.length?parts.join('\n\n'):'';
}

async function xunGenerate(task, system, user, schema, { silentStatus = false, referenceContext = '' } = {}) {
  if(['FEED','THREAD','DM','ROOM','ACCOUNT','ACCOUNT_EXPAND'].includes(String(task).toUpperCase())){
    if(String(task).toUpperCase()==='FEED')system=system.split(XUN_ACCOUNT_GUIDE).join(XUN_FEED_ACCOUNT_GUIDE);
    if(!system.includes("【账号背后的人与公司】"))system += "\n\n"+(String(task).toUpperCase()==='FEED'?XUN_FEED_ACCOUNT_GUIDE:XUN_ACCOUNT_GUIDE);
    if(String(task).toUpperCase()==='ACCOUNT')system += '\n\n'+(await xunTaskPrompt('PORTRAIT')||XUN_PORTRAIT_FALLBACK);
    if(['THREAD','DM','ROOM','ACCOUNT','ACCOUNT_EXPAND'].includes(String(task).toUpperCase()))user += '\n\n【基础人设结构】\n'+JSON.stringify(await xunAccountFoundationStructure());
    const registry=Object.values(xunObj(xunGetStore().accounts)).map(a=>({id:a.id,handle:a.handle,displayName:a.displayName,kind:a.kind}));
    user += "\n\n【账号索引】\n"+JSON.stringify(registry);
  }
  const cfg=xunGetConfig();
  if(cfg.enabled===false)throw new Error('迅网额外请求已关闭');
  const taskName=String(task||'').toUpperCase();
  const taskFloor=({FEED:9000,THREAD:5000,DM:6000,ROOM:6500,ACCOUNT:6500,ACCOUNT_EXPAND:6500,NEWS:3600,SHOP:3500}[taskName]||1800);
  const requestMaxTokens=Math.max(taskFloor,Number(cfg.maxTokens??1800));
  const transport=xunTransportLabel(cfg),model=xunTransportModelLabel(cfg);
  const worldContext=await xunRequiredWorldContext(task,user);
  const messages=xunAssembleRequestMessages(task,system,user,schema,cfg,{worldbook:worldContext,accountTypes:referenceContext});
  if(!silentStatus)xunSetGenerationStatus({active:true,task:String(task),phase:'request',message:`正在通过${transport}请求 ${model}…`,transport,model,error:'',responsePreview:'',responseChars:0,extractPath:''});
  let text='',rawPreview='',extractPath='';
  try{
    const got=await xunRequestText(task,messages,schema,cfg,{maxTokens:requestMaxTokens});
    text=xunText(got?.text);
    rawPreview=xunText(got?.raw).slice(0,1800);
    extractPath=xunText(got?.extractPath);
    if(!silentStatus)xunSetGenerationStatus({active:true,task:String(task),phase:'parse',message:'模型已返回，正在解析内容…',transport,model,responseChars:text.length,extractPath,responsePreview:rawPreview});
    if(!text)throw new Error('模型已响应，但返回了空白正文。请重试或更换模型。');
    const parsed=xunNormalizeTaskPayload(task,xunParseJson(text));
    if(!silentStatus)xunSetGenerationStatus({active:true,task:String(task),phase:'parsed',message:'内容已解析，正在写入讯匣…',transport,model,responseChars:text.length,extractPath,responsePreview:text.slice(0,1800)});
    return parsed;
  }catch(err){
    const preview=xunText(err?.rawPreview||rawPreview||text).slice(0,1800);
    if(!silentStatus)xunSetGenerationStatus({active:false,task:String(task),phase:'error',message:'请求已结束，但内容处理失败。',transport,model,error:err?.message||String(err),responsePreview:preview,responseChars:text.length,extractPath});
    throw err;
  }
}

let xunMvuApiCache = null;
let xunMvuWarmupPromise = null;
function xunTryMvuApi() {
  if (xunMvuApiCache && typeof xunMvuApiCache.getMvuData === 'function') return xunMvuApiCache;
  try { if (typeof Mvu !== 'undefined' && Mvu && typeof Mvu.getMvuData === 'function') return (xunMvuApiCache = Mvu); } catch (_) {}
  try { if (window?.Mvu && typeof window.Mvu.getMvuData === 'function') return (xunMvuApiCache = window.Mvu); } catch (_) {}
  try { if (TavernHelper?.Mvu && typeof TavernHelper.Mvu.getMvuData === 'function') return (xunMvuApiCache = TavernHelper.Mvu); } catch (_) {}
  return null;
}
function xunWarmMvuApi() {
  const hit = xunTryMvuApi();
  if (hit) return Promise.resolve(hit);
  if (xunMvuWarmupPromise) return xunMvuWarmupPromise;
  if (typeof waitGlobalInitialized !== 'function') return Promise.resolve(null);
  xunMvuWarmupPromise = Promise.resolve()
    .then(() => waitGlobalInitialized('Mvu'))
    .then(api => {
      if (api && typeof api.getMvuData === 'function') xunMvuApiCache = api;
      return xunTryMvuApi() || (api && typeof api.getMvuData === 'function' ? api : null);
    })
    .catch(() => null)
    .finally(() => { xunMvuWarmupPromise = null; });
  return xunMvuWarmupPromise;
}
let xunLastStableMvu = null;

function xunHasMeaningfulMvu(value) {
  const data = xunObj(value);
  const stat = xunObj(data.stat_data || data);
  return !!(
    Object.keys(xunObj(stat.城市生活)).length ||
    Object.keys(xunObj(stat.人物关系)).length ||
    Object.keys(xunObj(stat.人物档案)).length ||
    Object.keys(xunObj(stat.警务事项)).length
  );
}
function xunRememberStableMvu(value) {
  const data = xunObj(value);
  if (!xunHasMeaningfulMvu(data)) return data;
  try { xunLastStableMvu = xunClone(data); }
  catch (_) { xunLastStableMvu = data; }
  return data;
}
function xunPriorMessageMvu(api) {
  if (!api || typeof api.getMvuData !== 'function') return {};
  let last = -1;
  try {
    const chat = xunSillyTavernContext()?.chat;
    if (Array.isArray(chat)) last = chat.length - 1;
  } catch (_) {}
  if (last < 0) return {};
  const floor = 0;
  for (let id = last - 1; id >= floor; id--) {
    try {
      const data = xunObj(api.getMvuData({ type:'message', message_id:id }));
      if (xunHasMeaningfulMvu(data)) return data;
    } catch (_) {}
  }
  return {};
}
function xunVariableStateFallback() {
  const attempts = [
    () => typeof getVariables === 'function' ? getVariables({ type: 'message', message_id: 'latest' }) : null,
    () => typeof getVariables === 'function' ? getVariables({ type: 'message', message_id: -1 }) : null,
    () => typeof getVariables === 'function' ? getVariables({ type: 'chat' }) : null
  ];
  for (const read of attempts) {
    try {
      const data = xunObj(read());
      if (xunHasMeaningfulMvu(data)) return xunRememberStableMvu(data);
    } catch (_) {}
  }
  return xunLastStableMvu ? xunClone(xunLastStableMvu) : {};
}
async function xunMvuData() {
  const api = xunTryMvuApi();
  if (api) {
    try {
      const latest = xunObj(api.getMvuData({ type: 'message', message_id: 'latest' }));
      if (xunHasMeaningfulMvu(latest)) return xunRememberStableMvu(latest);



      const prior = xunPriorMessageMvu(api);
      if (xunHasMeaningfulMvu(prior)) return xunRememberStableMvu(prior);
    } catch (_) {}
  }

  void xunWarmMvuApi();
  const fallback = xunVariableStateFallback();
  if (xunHasMeaningfulMvu(fallback)) return fallback;
  return xunLastStableMvu ? xunClone(xunLastStableMvu) : {};
}
async function xunRequireMvuApi(timeoutMs = 5000) {
  const hit = xunTryMvuApi();
  if (hit) return hit;
  if (typeof waitGlobalInitialized !== 'function') throw new Error('当前环境未提供 MVU 接口，无法写回变量。');
  const timeout = new Promise(resolve => setTimeout(() => resolve(null), Math.max(800, Number(timeoutMs) || 5000)));
  const waited = await Promise.race([xunWarmMvuApi(), timeout]);
  const api = (waited && typeof waited.getMvuData === 'function') ? waited : xunTryMvuApi();
  if (!api) throw new Error('MVU 尚未就绪；页面仍可浏览，但本次状态写回暂不可用。');
  return api;
}

function xunStatRoot(mvu) {
  const data = xunObj(mvu);
  return xunObj(data.stat_data || data);
}

const XUN_NEWS_GUIDE = `你负责汐见地区新闻。依据当前世界日期、时间、天气、已经公开的剧情事实与所附世界书设定，编写这一时点居民能够读到的地方报道。只返回规定的 JSON。
每轮 1～4 条，标题简洁，正文约 100～220 字，涉及交通、街区生活、商贸、文化、节庆、公共服务等不同主题，按材料取舍。优先报道已有剧情带来的公共变化；案件只使用公共信息中明确公开的内容，不能把警方内部进度、私人通讯或幕后真相当成新闻。
遵守汐见历法、季节、地理和设备设定。使用输入的世界日期，不使用现实日期。不把未来节日写成已举行；临近活动写预告，结束的活动只在有事实依据时写回顾。天气缺失时不虚构精确预报。每条 source_ids 必须引用至少一个输入来源 ID。
world: 来源只能支持日常地域风貌、季节生活和设定已有的惯例，可据此写生活专题；不得凭常识编造当日事故、停运、犯罪、灾害、行政新政、具体活动日期或官方统计。pub: 来源可支持已发生的公开事件及其影响；未确定的信息保留原不确定性。source 用居民能理解的来源名称，不能虚构采访、引语或机构背书。
近期新闻用于去重和延续：同一事实无新进展不换标题重复发布；有新进展写清变化，旧报道保留。输入材料不足时 articles 返回 []。这些新闻保存到讯匣，不自行新增 MVU 案件、关系或人物记录。`;
const XUN_NEWS_SCHEMA={type:'object',additionalProperties:false,required:['articles'],properties:{articles:{type:'array',maxItems:4,items:{type:'object',additionalProperties:false,required:['title','district','category','text','source','source_ids'],properties:{title:{type:'string'},district:{type:'string'},category:{enum:['地区动态','公共服务','交通','商贸','文化节庆','生活专题']},text:{type:'string'},source:{type:'string'},source_ids:{type:'array',items:{type:'string'},minItems:1,maxItems:5}}}}}};
let xunNewsBusy=false;
async function xunGenerateNews(){
  if(xunNewsBusy)throw new Error('正在编写地区新闻');xunNewsBusy=true;
  const chat=xunSillyTavernContext()?.chat,epoch=xunMvuEpoch,anchor=xunAnchor();
  try{
    const stat=xunStatRoot(await xunMvuData()),publicState=xunPublicState(stat),date=xunText(publicState.世界.日期);
    if(!date)throw new Error('剧情日期尚未登记，请先完成当前楼层的变量更新。');
    const entries=await xunShiomiEntries(),sources=[];
    for(const [name,value] of Object.entries(publicState.公共信息))sources.push({id:'pub:'+name,name,content:value});
    let used=0;
    for(const entry of entries){
      const name=xunText(entry.name||entry.comment);
      if(!xunSafeEntry(entry)||!/(?:地方媒体|历法|气候|季节|节日|节庆|节令|风俗|文化|交通|地理|街区|町|汐见市概况)/.test(name)||/(?:角色|案件|人设|声口|监修|运行|系统|警务)/.test(name))continue;
      const content=xunText(entry.content).slice(0,2400);if(!content||used+content.length>18000)continue;used+=content.length;
      sources.push({id:'world:'+name,name,content});
    }
    const before=xunGetStore(),recent=xunArr(before.news).slice(-20).map(n=>({title:n.title,date:n.date,text:n.text,source_ids:n.source_ids}));
    const prompt=await xunTaskPrompt('NEWS');
    const data=await xunGenerate('NEWS',prompt||XUN_NEWS_GUIDE,JSON.stringify({world:publicState.世界,sources,recent_news:recent},null,2),XUN_NEWS_SCHEMA);
    const currentDate=xunText(xunObj(xunObj(xunStatRoot(await xunMvuData()).城市生活).世界).日期);
    if(chat!==xunSillyTavernContext()?.chat||epoch!==xunMvuEpoch||!xunAnchorAlive(anchor)||currentDate!==date)throw new Error('剧情日期或分支已变化，请按当前日期重新生成新闻。');
    const latest=xunGetStore(),valid=new Set(sources.map(s=>s.id)),created=[];latest.news=xunArr(latest.news);
    const seen=new Set(latest.news.map(n=>JSON.stringify([n.date,n.title])));
    for(const row of xunArr(data.articles).slice(0,4)){
      const title=xunText(row.title).slice(0,100),text=xunText(row.text).slice(0,1800),ids=xunUnique(row.source_ids);
      if(!title||!text||!ids.length||ids.some(id=>!valid.has(id)))continue;
      const key=JSON.stringify([date,title]);if(seen.has(key)||latest.news.some(n=>n.date===date&&n.text===text))continue;seen.add(key);
      created.push({id:xunId('news'),title,text,date,time:xunText(publicState.世界.时间),district:xunText(row.district).slice(0,100),category:xunText(row.category),source:xunText(row.source).slice(0,200),source_ids:ids,anchor,createdAt:xunNow()});
    }
    latest.news=[...latest.news,...created].slice(-200);await xunSaveStore(latest);return created;
  }finally{xunNewsBusy=false;}
}

function xunPublicState(stat) {
  const life = xunObj(stat.城市生活);
  const publicInfo = xunObj(life.公共信息);
  const visible = {};
  for (const [name, itemRaw] of Object.entries(publicInfo)) {
    const item = xunObj(itemRaw);
    if (['已过时','已撤回'].includes(xunText(item.状态))) continue;
    visible[name] = item;
  }
  return { 世界: xunObj(life.世界), 公共信息: visible };
}

function xunPersonState(stat, name) {
  name = xunText(name);
  if (!name) return {};
  const life=xunObj(stat.城市生活),scene=xunObj(life.当前场景),pleasure=xunObj(scene.快感值),peoplePleasure=xunObj(pleasure.人物);
