  };
}

let xunShiomiWorldbookCache = '';
let xunWorldbookNameCache = [];
const xunWorldbookEntryCache = new Map();

function xunEntryEnabled(entry) {
  return !(entry?.enabled === false || entry?.disable === true || entry?.disabled === true);
}

async function xunWorldbookNames(force = false) {
  if (!force && xunWorldbookNameCache.length) return [...xunWorldbookNameCache];
  const names = [], add = value => {
    if (Array.isArray(value)) return value.forEach(add);
    const name = xunText(value);
    if (name && !names.some(x => x.toLowerCase() === name.toLowerCase())) names.push(name);
  };

  try { if (typeof getWorldbookNames === 'function') add(getWorldbookNames()); } catch (_) {}
  try {
    const ctx = SillyTavern?.getContext?.();
    if (typeof ctx?.getWorldInfoNames === 'function') add(await ctx.getWorldInfoNames());
  } catch (_) {}
  try {
    const bound = getCharWorldbookNames('current');
    add(bound?.primary); add(bound?.additional);
  } catch (_) {}
  try { add(getChatWorldbookName('current')); } catch (_) {}
  if (!names.length) {
    try {
      const doc = window?.parent?.document || document;
      for (const sel of ['#world_editor_select', '#world_info']) doc.querySelectorAll(`${sel} option`).forEach(o => add(o.textContent || o.label || o.value));
    } catch (_) {}
  }
  names.sort((a,b) => a.localeCompare(b, 'zh-CN'));
  xunWorldbookNameCache = names;
  return [...names];
}

async function xunLoadWorldbookEntries(name, force = false) {
  name = xunText(name);
  if (!name) return [];
  if (!force && xunWorldbookEntryCache.has(name)) return xunWorldbookEntryCache.get(name).map(x => ({ ...x }));
  let rows = [];
  try { rows = xunArr(await getWorldbook(name)); } catch (_) {}
  if (!rows.length) {
    try {
      const ctx = SillyTavern?.getContext?.();
      if (typeof ctx?.loadWorldInfo === 'function') {
        const data = await ctx.loadWorldInfo(name);
        if (Array.isArray(data)) rows = data;
        else if (Array.isArray(data?.entries)) rows = data.entries;
        else if (data?.entries && typeof data.entries === 'object') rows = Object.values(data.entries);
      }
    } catch (_) {}
  }
  const out = rows.map((entry, index) => ({ ...entry, $book: name, $index: index }));
  xunWorldbookEntryCache.set(name, out);
  return out.map(x => ({ ...x }));
}

function xunWorldbookEntryId(entry) {
  return xunText(entry?.uid ?? entry?.id ?? entry?.identifier ?? entry?.$index);
}
function xunWorldbookEntryTitle(entry) {
  return xunText(entry?.name || entry?.comment || entry?.title || entry?.uid || `条目 ${Number(entry?.$index || 0)+1}`);
}


function xunEntryContentForExtra(entry, stat) {
  let content = xunRenderEjsTemplate(entry?.content, stat);
  if (!content) content = xunText(entry?.content).replace(/^\s*@@private\s*/i, '');
  return content;
}

function xunLooksLikeShiomi(entries) {
  if (entries.some(e => xunText(e?.name || e?.comment) === SHIOMI_WORLD_MARKER_ENTRY || xunText(e?.content).includes(SHIOMI_WORLD_MARKER))) return true;
  const names = new Set(entries.map(e => xunText(e?.name || e?.comment)));
  return names.has('【设备卷】城域讯网') && names.has('【角色卷】水城澪') && names.has('[mvu_update]变量更新规则');
}

async function xunResolveShiomiWorldbook(force = false) {
  if (force) { xunShiomiWorldbookCache = ''; xunWorldbookNameCache = []; xunWorldbookEntryCache.clear(); }
  if (!force && xunShiomiWorldbookCache) return xunShiomiWorldbookCache;
  const cfg = xunGetConfig(), candidates = [];
  const add = v => { v = xunText(v); if (v && !candidates.includes(v)) candidates.push(v); };
  add(cfg.shiomiWorldbook);
  try { const bound = getCharWorldbookNames('current'); add(bound?.primary); xunArr(bound?.additional).forEach(add); } catch (_) {}
  try { add(getChatWorldbookName('current')); } catch (_) {}
  (await xunWorldbookNames(force)).forEach(add);
  for (const name of candidates) {
    const entries = await xunLoadWorldbookEntries(name, force);
    if (xunLooksLikeShiomi(entries)) { xunShiomiWorldbookCache = name; return name; }
  }
  return '';
}

async function xunShiomiEntries(force = false) {
  const name = await xunResolveShiomiWorldbook(force);
  return name ? xunLoadWorldbookEntries(name, force) : [];
}

async function xunTaskPrompt(task) {
  const wanted = SHIOMI_XUN_TASK_PROMPTS[String(task || '').toUpperCase()];
  if (!wanted) return '';
  const entries = await xunShiomiEntries();
  const row = entries.find(e => xunText(e?.name || e?.comment) === wanted);
  if (!row) return '';
  const stat = xunStatRoot(await xunMvuData());
  return xunRenderEjsTemplate(row.content, stat) || xunText(row.content);
}

function xunEntryKeys(entry) {
  const s = xunObj(entry?.strategy);
  const keys = xunArr(s.keys || entry?.keys || entry?.key);
  return keys.map(k => k instanceof RegExp ? k : xunText(k)).filter(Boolean);
}

function xunEntryMatches(entry, corpus) {
  const text = String(corpus || '');
  return xunEntryKeys(entry).some(key => {
    if (key instanceof RegExp) { try { return key.test(text); } catch (_) { return false; } }
    return key && text.includes(String(key));
  });
}

function xunSafeEntry(entry) {
  const name = xunText(entry?.name || entry?.comment);
  const content = xunText(entry?.content);
  if (!xunEntryEnabled(entry) || !content) return false;
  if (SHIOMI_XUN_SKIP_ENTRY.test(name)) return false;
  if (name === SHIOMI_WORLD_MARKER_ENTRY) return false;
  if (content.includes('<%')) return false;
  return true;
}

function xunContextEntryKey(entry) {
  return `${entry?.$book || ''}:${entry?.uid ?? entry?.$index ?? ''}:${entry?.name || entry?.comment || ''}`;
}

function xunAppendContextBlock(parts, seen, entry, maxChars, usedRef, { required = false } = {}) {
  const content = xunText(entry?.content);
  if (!content) return false;
  const key = xunContextEntryKey(entry);
  if (seen.has(key)) return false;
  const block = `【${xunText(entry.name || entry.comment || entry.$book)}】\n${content}`;

  if (!required && usedRef.value + block.length > maxChars) return false;
  seen.add(key); parts.push(block); usedRef.value += block.length;
  return true;
}

async function xunWorldContext(terms, { characterNames = [], maxChars = 15000, requireXunCore = true } = {}) {
  const shiomi = await xunShiomiEntries();
  const corpus = xunUnique(terms).join('\n');
  const wantedChars = new Set(xunUnique(characterNames));
  const parts = [], seen = new Set(), used = { value: 0 }, statForExtra = xunStatRoot(await xunMvuData());
  const safe = shiomi.filter(xunSafeEntry);
  const byName = new Map(safe.map(entry => [xunText(entry.name || entry.comment), entry]));


  if (requireXunCore) {
    for (const name of SHIOMI_XUN_TECH_ENTRIES) {
      const entry = byName.get(name);
      if (entry) xunAppendContextBlock(parts, seen, entry, maxChars, used, { required: true });
    }
  }


  for (const charName of wantedChars) {
    const entry = byName.get(`【角色卷】${charName}`);
    if (entry) xunAppendContextBlock(parts, seen, entry, maxChars, used);
  }


  for (const entry of safe) {
    const name = xunText(entry.name || entry.comment);
    if (SHIOMI_XUN_TECH_ENTRIES.has(name)) continue;
    if ([...wantedChars].some(charName => name === `【角色卷】${charName}`)) continue;
    if (xunEntryMatches(entry, corpus)) xunAppendContextBlock(parts, seen, entry, maxChars, used);
  }


  const remaining = Math.max(0, maxChars - used.value);
  if (remaining > 0) {
    for (const item of await xunWorldbookCloneContextRows('social', statForExtra, { maxChars: remaining })) {
      const copy = { $book:item.book, uid:item.id, name:item.title, content:item.content };
      xunAppendContextBlock(parts, seen, copy, maxChars, used);
    }
  }
  return parts.join('\n\n');
}

function xunGetStatPath(stat, path) {
  const parts = String(path || '').replace(/^stat_data\.?/, '').split('.').filter(Boolean);
  let cur = stat;
  for (const key of parts) {
    if (cur == null || typeof cur !== 'object' || !Object.prototype.hasOwnProperty.call(cur, key)) return undefined;
    cur = cur[key];
  }
  return cur;
}

function xunRenderEjsTemplate(template, stat) {
  let raw = String(template || '').replace(/^\s*@@private\s*/i, '');
  if (!raw.includes('<%')) return raw.trim();
  let code = `let __out = '';\n`, last = 0;
  const re = /<%([_=-]?)([\s\S]*?)%>/g;
  let m;
  while ((m = re.exec(raw))) {
    code += `__out += ${JSON.stringify(raw.slice(last, m.index))};\n`;
    const marker = String(m[1] || '');
    let js = String(m[2] || '');
    if (js.endsWith('_') || js.endsWith('-')) js = js.slice(0, -1);
    if (marker === '=' || marker === '-') code += `__out += String((${js.trim()}) ?? '');\n`;
    else code += `${js}\n`;
    last = re.lastIndex;
  }
  code += `__out += ${JSON.stringify(raw.slice(last))};\nreturn __out;`;
  try {
    const fn = new Function('getvar', 'SillyTavern', code);
    const rendered = fn(path => xunGetStatPath(stat, path), (() => { try { return SillyTavern; } catch (_) { return {}; } })());
    return xunText(rendered).replace(/\n{3,}/g, '\n\n');
  } catch (_) { return ''; }
}

async function xunCurrentPersonaContext(stat, characterNames, { maxChars = 10000 } = {}) {
  const entries = await xunShiomiEntries(), wanted = new Set(xunUnique(characterNames));
  const out = {}, used = { value: 0 };
  for (const name of wanted) {
    const entry = entries.find(e => xunText(e?.name || e?.comment) === `【分阶段人设】${name}`);
    if (!entry || !xunEntryEnabled(entry)) continue;
    const text = xunRenderEjsTemplate(entry.content, stat);
    if (!text || used.value + text.length > maxChars) continue;
    out[name] = text; used.value += text.length;
  }
  return out;
}

async function xunImageWorldContext(stat, terms = [], { maxChars = 14000 } = {}) {
  const parts=[],seen=new Set(),used={value:0};
  for(const item of await xunWorldbookCloneContextRows('image',stat,{maxChars})){
    const key=`${item.book}:${item.id}`;if(seen.has(key))continue;
    const block=`【画图资料：${item.book} / ${item.title}】\n${item.content}`;
    if(used.value+block.length>maxChars)continue;seen.add(key);parts.push(block);used.value+=block.length;
  }
  return parts.join('\n\n');
}

async function xunWorldbookStatus(force = false, requestedBook = '', mode = 'social') {
  mode=xunWorldbookCloneMode(mode);if(force){xunWorldbookNameCache=[];xunWorldbookEntryCache.clear();xunShiomiWorldbookCache='';}
  await xunMigrateLegacyWorldbookSelections();
  const names=await xunWorldbookNames(force),shiomi=await xunResolveShiomiWorldbook(force),selectedBook=xunText(requestedBook)||shiomi||names[0]||'';
  const state=xunLoadWorldbookClones(),row=xunWorldbookCloneBook(state,mode,selectedBook,false);
  const source=selectedBook?xunWorldbookCloneSourceRows(await xunLoadWorldbookEntries(selectedBook,force)):[];
  const entries=source.map(e=>({id:e.id,title:e.title,sourceEnabled:e.sourceEnabled,cloneEnabled:row?.initialized?row.entryStates[e.id]===true:!!e.sourceEnabled,constant:e.constant,keys:e.keys.slice(0,6),chars:e.content.length}));
  const books=names.map(name=>{
    const r=xunWorldbookCloneBook(state,mode,name,false),states=xunObj(r?.entryStates),total=Object.keys(states).length,selected=Object.values(states).filter(Boolean).length;
    return {name,configured:!!r?.initialized,enabled:!!r?.initialized&&r.enabled!==false,selectedCount:selected,totalCount:total,shiomi:name===shiomi};
  });
  return {names,books,shiomi,selectedBook,mode,cloned:!!row?.initialized,bookEnabled:!!row?.initialized&&row.enabled!==false,entries,stats:xunWorldbookCloneStats(state,mode)};
}

async function xunSetWorldbookEntrySelection(book, socialIds = [], imageIds = []) {
  book = xunText(book); if (!book) throw new Error('没有选择世界书。');
  const cfg = xunGetConfig();
  const social = xunNormalizeWorldbookEntryMap(cfg.socialWorldbookEntries), image = xunNormalizeWorldbookEntryMap(cfg.imageWorldbookEntries);
  const sids = xunUnique(socialIds), iids = xunUnique(imageIds);
  if (sids.length) social[book] = sids; else delete social[book];
  if (iids.length) image[book] = iids; else delete image[book];

  const next = await xunSetConfig({
    socialWorldbookEntries: social,
    imageWorldbookEntries: image,
    socialWorldbooks: xunUnique(cfg.socialWorldbooks).filter(x => x !== book),
    imageWorldbooks: xunUnique(cfg.imageWorldbooks).filter(x => x !== book)
  });
  return next;
}





const SHIOMI_XUN_WB_CLONE_KEY = 'SHIOMI_XUN_WORLD_BOOK_CLONES_V1';
let xunLegacyWorldbookCloneMigrated = false;
function xunWorldbookCloneMode(mode){ return mode==='image'?'image':'social'; }
function xunNormalizeWorldbookCloneState(raw){
  const src=xunObj(raw),out={social:{books:{}},image:{books:{}}};
  for(const mode of ['social','image']){
    const root=xunObj(src[mode]),books=xunObj(root.books);
    for(const [name,rv] of Object.entries(books)){
      const book=xunText(name),row=xunObj(rv);if(!book)continue;
      const entryStates={};
      for(const [id,on] of Object.entries(xunObj(row.entryStates)))entryStates[xunText(id)]=on===true;

      if(!Object.keys(entryStates).length){for(const id of Object.keys(xunObj(row.selected)))entryStates[xunText(id)]=true;}
      out[mode].books[book]={enabled:row.enabled!==false,initialized:row.initialized===true||Object.keys(entryStates).length>0,entryStates,updatedAt:Number(row.updatedAt)||0};
    }
  }
  return out;
}
function xunLoadWorldbookClones(){
  try{return xunNormalizeWorldbookCloneState(JSON.parse(localStorage.getItem(SHIOMI_XUN_WB_CLONE_KEY)||'{}'));}catch(_){return xunNormalizeWorldbookCloneState({});}
}
function xunSaveWorldbookClones(state){
  const next=xunNormalizeWorldbookCloneState(state);
  try{localStorage.setItem(SHIOMI_XUN_WB_CLONE_KEY,JSON.stringify(next));}
  catch(err){throw new Error('世界书选择保存失败；请清理旧讯匣缓存后重试。');}
  return next;
}
function xunWorldbookCloneBook(state,mode,book,create=false){
  mode=xunWorldbookCloneMode(mode);book=xunText(book);if(!book)return null;
  const root=state[mode]||(state[mode]={books:{}});root.books=xunObj(root.books);
  let row=root.books[book];
  if(!row&&create)row=root.books[book]={enabled:true,initialized:false,entryStates:{},updatedAt:0};
  if(row)row.entryStates=xunObj(row.entryStates);
  return row||null;
}
function xunWorldbookCloneSourceRows(entries){
  return xunArr(entries).map((entry,index)=>({
    id:xunWorldbookEntryId(entry)||`idx_${index}`,
    title:xunWorldbookEntryTitle(entry),
    content:String(entry?.content||''),
    sourceEnabled:xunEntryEnabled(entry),
    keys:xunEntryKeys(entry).map(String).slice(0,12),
    constant:entry?.constant===true||entry?.alwaysActive===true
  })).filter(e=>e.id&&e.content.trim());
}
function xunWorldbookCloneSyncRow(row,sourceRows,{initial=false,selectedIds=null,allOn=false}={}){
  const sourceMap=new Map(sourceRows.map(e=>[e.id,e]));
  if(initial)row.entryStates={};
  for(const id of Object.keys(xunObj(row.entryStates)))if(!sourceMap.has(id))delete row.entryStates[id];
  for(const e of sourceRows){
    let on;
    if(selectedIds instanceof Set)on=selectedIds.has('*')?!!e.sourceEnabled:selectedIds.has(e.id);
    else if(allOn)on=true;
    else if(initial||row.entryStates[e.id]===undefined)on=initial?!!e.sourceEnabled:false;
    else on=row.entryStates[e.id]===true;
    row.entryStates[e.id]=!!on;
  }
  row.initialized=true;row.enabled=row.enabled!==false;row.updatedAt=Date.now();
}
async function xunMigrateLegacyWorldbookSelections(){
  if(xunLegacyWorldbookCloneMigrated)return;xunLegacyWorldbookCloneMigrated=true;
  const cfg=xunGetConfig(),state=xunLoadWorldbookClones();let changed=false,hadLegacy=false;
  for(const mode of ['social','image']){
    const legacy=mode==='image'?xunObj(cfg.imageWorldbookEntries):xunObj(cfg.socialWorldbookEntries);
    if(Object.keys(legacy).length)hadLegacy=true;
    for(const [book,idsRaw] of Object.entries(legacy)){
