async function xunModelList(patch = {}) {
  const cfg=xunNormalizeConfig({...xunGetConfig(),...xunObj(patch)});
  if(cfg.connectionMode==='tavern_current'){
    throw new Error('“酒馆当前 API”直接跟随酒馆当前模型配置，不需要在讯匣里读取或选择模型。');
  }
  cfg.connectionMode==='tavern'
    ? xunRequireOwnConnection(cfg,'酒馆助手')
    : xunRequireOwnConnection(cfg,cfg.connectionMode==='tavern_proxy'?'酒馆代理':'前端直连');
  if(cfg.connectionMode==='tavern'){
    const helper=xunStrictTavernHelperModelList();
    if(!helper)throw new Error('当前没有找到酒馆助手 TavernHelper.getModelList；可以手动填写模型名称。');
    const rows=await xunWithTimeout(helper.call({apiurl:xunText(cfg.apiurl),key:xunText(cfg.key)||undefined}),Math.min(cfg.requestTimeoutMs,60000),'模型列表请求');
    return xunUnique(xunArr(rows).map(v=>typeof v==='string'?v:(v?.id||v?.name||v?.model)));
  }


  const headers={'Accept':'application/json'};
  if(xunText(cfg.key))headers.Authorization='Bearer '+xunText(cfg.key);
  const r=await xunDirectFetch(xunModelsEndpoint(cfg.apiurl),{headers});
  const raw=await r.text().catch(()=> '');
  if(!r.ok)throw new Error(raw.slice(0,500)||`HTTP ${r.status}`);
  let data={};try{data=JSON.parse(raw);}catch(_){throw new Error('模型列表返回的不是 JSON。');}
  const rows=Array.isArray(data?.data)?data.data:Array.isArray(data?.models)?data.models:Array.isArray(data)?data:[];
  const result=xunUnique(rows.map(v=>typeof v==='string'?v:(v?.id||v?.name||v?.model)));
  if(!result.length)throw new Error('接口已连接，但没有返回可识别的模型列表；可以手动填写模型名称。');
  return result;
}
