async function xunBootstrapAccounts() {
  const bootstrapChat=xunSillyTavernContext()?.chat,bootstrapEpoch=xunMvuEpoch;
  const store = xunGetStore();
  let changed = false;
  const userName = xunCurrentUserName();
  const nextUser = xunNormalizeAccount({ ...store.accounts.user, id: 'user', kind: 'user', displayName: userName, handle: '@me', avatar: store.accounts?.user?.avatar || '' }, 'user');
  if (!xunAccountEqual(store.accounts.user, nextUser)) { store.accounts.user = nextUser; changed = true; }

  const legacyUserIds = Object.entries(xunObj(store.accounts))
    .filter(([id,a]) => id !== 'user' && (xunIsUserMacro(a?.displayName) || xunIsUserMacro(a?.characterName) || /^char:\{\{user\}\}$/i.test(id)))
    .map(([id]) => id);
  for (const id of legacyUserIds) {
    delete store.accounts[id]; changed = true;
    if (xunObj(store.chats)[`dm:${id}`]) { delete store.chats[`dm:${id}`]; changed = true; }
    for (const room of Object.values(xunObj(store.rooms))) {
      if (room && Array.isArray(room.participantIds) && room.participantIds.includes(id)) { room.participantIds = room.participantIds.filter(x => x !== id); changed = true; }
    }
  }

  const entries = await xunShiomiEntries();
  if(bootstrapChat!==xunSillyTavernContext()?.chat||bootstrapEpoch!==xunMvuEpoch)throw new Error('聊天已切换，账户资料未写入。');
  const sources={};
  for(const entry of entries){
    const title=xunText(entry?.name||entry?.comment),match=/^【(?:角色卷|分阶段人设)】(.+)$/.exec(title);
    if(!match||!xunEntryEnabled(entry)||xunIsUserMacro(match[1]))continue;
    const name=xunText(xunSubstituteMacros(match[1]));(sources[name]||(sources[name]=[])).push({title,content:xunText(entry.content)});
  }
  if(JSON.stringify(store.narrativePersonaSources||{})!==JSON.stringify(sources)){store.narrativePersonaSources=sources;changed=true;}
  for (const entry of entries) {
    const name = xunText(entry?.name || entry?.comment);
    const mm = /^【角色卷】(.+)$/.exec(name);
    if (!mm) continue;
    const rawCharName = xunText(mm[1]);
    if (xunIsUserMacro(rawCharName)) continue;
    const charName = xunText(xunSubstituteMacros(rawCharName));
    if (!charName || charName === userName) continue;
    const id = `char:${charName}`;
    if (!store.accounts[id]) { store.accounts[id] = xunNormalizeAccount({ id, kind: 'character', displayName: charName, characterName: charName }, id); changed = true; }
  }


  if(xunRepairNarrativeContacts(store))changed=true;
  if(xunRecoverAgreements(store))changed=true;
  if(!xunGetChatVariables()[XUN_NARRATIVE_STORE_KEY])changed=true;
  if(changed)return xunSaveStore(store);
  await xunSyncAccountWorldbook();
  return store;
}

