function xunAccountMvuName(account,stat,store=xunGetStore()){
  const pools=[xunObj(stat.人物关系),xunObj(stat.人物档案),xunObj(xunObj(stat.城市生活).人物)];
  const identities=a=>xunUnique([a.mvuName,a.characterName,a.id,a.handle,a.displayName,a.person?.realName,...xunText(a.identityAliases).split(/[\n,，、;；]/),...xunArr(a.profileHistory).flatMap(h=>xunArr(h.changes).filter(c=>['displayName','handle'].includes(c.field)).map(c=>c.before))]);
  // Exact, unique identities only. A manual binding is explicit and may precede first contact.
  for(const name of xunUnique([account.mvuName,account.characterName])){
    if(Object.values(xunObj(store.accounts)).some(a=>a.id!==account.id&&(a.mvuName===name||a.characterName===name)))continue;
