      const api=Object.fromEntries(['getWorldbookNames','getWorldbook','createWorldbook','updateWorldbookWith','getChatWorldbookName','rebindChatWorldbook'].map(n=>[n,xunAccountBookFn(n)]));
      if(Object.values(api).some(fn=>!fn))throw new Error('酒馆助手缺少世界书写入或聊天绑定接口；账户已保存在讯匣，可导出世界书 JSON 后手动导入。');
