        await xunAccountBookSaveState(state,chat,epoch);guard();
        await api.createWorldbook(name,[xunAccountBookMarker(owner,scope)]);guard();
      }
      const entries=await api.getWorldbook(state.name);guard();
      if(!entries.some(e=>e.extra?.shiomi_account_worldbook?.format===XUN_ACCOUNT_BOOK_FORMAT&&e.extra.shiomi_account_worldbook.owner===state.owner))
