      const merged=xunAccountBookMerge(entries,rows,state.owner,scope);
      if(JSON.stringify(merged)!==JSON.stringify(entries)) {
        await api.updateWorldbookWith(state.name,current=>{
          guard();
          if(!current.some(e=>e.extra?.shiomi_account_worldbook?.owner===state.owner))throw new Error('世界书管理标识已变化，未写入。');
          return xunAccountBookMerge(current,rows,state.owner,scope);
