    } catch(error) {
      if(chat===xunSillyTavernContext()?.chat&&epoch===xunMvuEpoch){
        state={...state,scope,error:error?.message||String(error)};
        xunAccountBookPlans.delete(scope+'\n'+xunText(state.name));
        try{await xunAccountBookSaveState(state,chat,epoch);}catch(_){}
      }
