    if(byId&&xunHandleKey(byId.handle)!==xunHandleKey(a.handle))throw new Error('账号号码与已有身份不符，原资料已保留。');
    if(byHandle&&byHandle.id!==a.id)throw new Error('该号码已有档案，请沿用原账号。');
    const old=byId||byHandle;
    if(!old&&a.entityType==='person'&&Object.values(store.accounts).some(p=>p.kind==='character'&&p.characterName&&p.characterName===a.person.realName))throw new Error('此人已有世界书身份，请从原人物账户补全档案。');
