    const expandExisting=profileMode==='expand'&&!!old&&old.entityType==='person'&&xunProfileDetailMissing(old).length>0;
    if(expandExisting)for(const key of ['realName','age'])if(xunKnownIdentity(old.person?.[key])&&a.person[key]!==old.person[key])throw new Error('补足扩展改变了原姓名或年龄，原档案已保留。');
