function xunResolveAccountId(store, value) {
  const raw=xunText(value); if(!raw)return '';
  if(store.accounts?.[raw])return raw;
  const norm=v=>xunText(v).replace(/[（(].*?[）)]/g,'').replace(/^@/,'').replace(/\s+/g,'').toLowerCase();
  const tokens=xunUnique([
    raw,
    ...raw.split(/[｜|丨／/·•]/),
    ...((raw.match(/@[A-Za-z0-9_.\-\u3040-\u30ff\u3400-\u9fff]+/g)||[])),
    raw.replace(/[（(].*?[）)]/g,'')
  ]).map(x=>xunText(x)).filter(Boolean);
  const wanted=new Set(tokens.flatMap(t=>[t,norm(t)]).filter(Boolean));
  for(const [id,a0] of Object.entries(xunObj(store.accounts))){
    const a=xunObj(a0),hits=[id,a.id,a.displayName,a.characterName,a.handle,xunText(a.handle).replace(/^@/,'')].filter(Boolean);
    for(const h of hits)if(wanted.has(xunText(h))||wanted.has(norm(h)))return id;
  }
  return '';
}
