function xunCollectAccountIds(store, value, out = new Set(), depth = 0) {
  if (depth > 8 || value == null) return out;
  if (typeof value === 'string') {
    if (store.accounts[value]) out.add(value);
    return out;
  }
  if (Array.isArray(value)) {
    for (const item of value) xunCollectAccountIds(store, item, out, depth + 1);
    return out;
  }
  if (typeof value === 'object') {
    for (const item of Object.values(value)) xunCollectAccountIds(store, item, out, depth + 1);
  }
  return out;
}

function xunInteractionAccounts(store, stat, interaction) {
  return [...xunCollectAccountIds(store, interaction)].map(id => {
    const account = store.accounts[id];
    const characterName = account?.kind === 'character' ? xunText(account.characterName) : '';
    return {
      account: xunAccountSummary(store, [id])[0],
      state: characterName ? xunPersonState(stat, characterName) : undefined
    };
  });
}

function xunExchangeCharacterNames(kind, interaction, store, stat={}) {
  const ids = new Set();
  const addIfCharacter = id => {
    const account = store.accounts[xunText(id)];
    const name=account?(xunAccountMvuName(account,stat,store)||xunText(account.displayName)):'';
    if(name&&(account?.kind==='character'||account?.mvuName||xunRecordHas(stat.人物档案,name)||xunRecordHas(stat.人物关系,name)))ids.add(account.id);
  };
  if (kind === 'DM') {
    const accountId = xunText(interaction?.accountId);
    const messages = xunArr(interaction?.messages);
    const userSpoke = messages.some(m => xunText(m?.from) === 'user');
    const otherSpoke = messages.some(m => xunText(m?.from) === accountId);
    if (userSpoke && otherSpoke) addIfCharacter(accountId);
  } else if (kind === 'THREAD') {
    const comments = xunArr(interaction?.comments);
    if (interaction?.post?.authorId==='user'||comments.some(c => xunText(c?.authorId) === 'user')) {
      for (const c of comments) if (xunText(c?.authorId) !== 'user') addIfCharacter(c?.authorId);
    }
  } else if (kind === 'ROOM') {
    const messages = xunArr(interaction?.messages);
    if (messages.some(m => xunText(m?.authorId) === 'user')) {
      for (const m of messages) if (xunText(m?.authorId) !== 'user') addIfCharacter(m?.authorId);
    }
  }
  const names = new Set();
  for (const id of ids) {
    const name=xunAccountMvuName(store.accounts[id],stat,store)||xunText(store.accounts[id]?.displayName);
    if (name) names.add(name);
  }
  return names;
}

function xunHasBidirectionalExchange(kind, interaction) {
  kind=xunText(kind);
  if(kind==='DM'){
    const accountId=xunText(interaction?.accountId),messages=xunArr(interaction?.messages);
    return !!accountId && messages.some(m=>xunText(m?.from)==='user') && messages.some(m=>xunText(m?.from)===accountId);
  }
  if(kind==='THREAD'){
    const comments=xunArr(interaction?.comments);
    return (interaction?.post?.authorId==='user'||comments.some(c=>xunText(c?.authorId)==='user')) && comments.some(c=>xunText(c?.authorId)!=='user');
  }
  if(kind==='ROOM'){
    const messages=xunArr(interaction?.messages);
    return messages.some(m=>xunText(m?.authorId)==='user') && messages.some(m=>xunText(m?.authorId)!=='user');
  }
  return false;
}

const XUN_INITIAL_RELATION = Object.freeze({
  好感度: 100, 信任度: 100, 熟悉度: 0, 友情值: 0, 爱情值: 0, 关系状态: '初识'
});

function xunDecodePointer(token) { return String(token).replace(/~1/g, '/').replace(/~0/g, '~'); }
function xunEncodePointer(token) { return String(token).replace(/~/g, '~0').replace(/\//g, '~1'); }
function xunPointerParts(path) { return String(path || '').split('/').slice(1).map(xunDecodePointer).filter(Boolean); }
function xunAllowedStatePath(path, op) {
  const p = String(path || '');
  if (/^\/城市生活\/(?:日程|人物)(?:\/|$)/.test(p)) return true;
  if (/^\/人物关系\/[^/]+(?:\/(?:好感度|信任度|熟悉度|友情值|爱情值|关系状态))?$/.test(p)) return true;
  if (/^\/警务事项\/[^/]+\/当前案情\/人物说法(?:\/|$)/.test(p)) return true;
  return false;
}

function xunApplyPatch(stat, patch) {
  const op = xunText(patch.op), parts = xunPointerParts(patch.path);
  if (!parts.length || parts.some(k=>['__proto__','constructor','prototype'].includes(k)) || !xunAllowedStatePath(patch.path, op)) return false;
  if(!['insert','replace','delta','remove'].includes(op))return false;
  let parent = stat;
  for (let i = 0; i < parts.length - 1; i++) {
    const key = parts[i];
    if (!xunRecordHas(parent,key)) {
      if (op !== 'insert') return false;
      parent[key] = {};
    }
    if(!parent[key]||typeof parent[key]!=='object'||Array.isArray(parent[key]))return false;
    parent = parent[key];
  }
  const key = parts[parts.length - 1];
  const exists = Object.prototype.hasOwnProperty.call(parent, key);
  if (op === 'remove') { if (!exists) return false; delete parent[key]; return true; }
  if (op === 'delta') {
    if (!exists || typeof parent[key] !== 'number') return false;
    const delta = patch.value; if (!Number.isFinite(delta)||!Number.isFinite(parent[key])||delta===0) return false;
    parent[key] += delta;
    if (parts[0] === '人物关系' && ['好感度','信任度','熟悉度','友情值','爱情值'].includes(key)) parent[key] = Math.max(0, Math.min(200, parent[key]));
    return true;
  }
  if (op === 'insert') {
    if (exists) return false;
    parent[key] = xunClone(patch.value); return true;
  }
  if (op === 'replace') {
    if (!exists||JSON.stringify(parent[key])===JSON.stringify(patch.value)) return false;
    parent[key] = xunClone(patch.value); return true;
  }
  return false;
}

let xunMvuBusy = false;
let xunMvuQueue = [];
let xunMvuFlushBusy = false;
let xunMvuEpoch = 0;

function xunStateInteractionAlive(kind,interaction){
  const store=xunGetStore();
  const owner=kind==='DM'?store.chats?.[`dm:${interaction?.accountId}`]:kind==='ROOM'?store.rooms?.[interaction?.roomId]:store.posts?.[interaction?.post?.id];
  if(!owner)return false;
  const rows=xunArr(kind==='THREAD'?owner.comments:owner.messages),ids=new Set(rows.map(m=>m?.id));
  return xunArr(interaction?.messages||interaction?.comments).every(m=>m?.id&&ids.has(m.id));
}
function xunStateJobAlive(job) {
  return job.epoch===xunMvuEpoch && job.chat===xunSillyTavernContext()?.chat && xunAnchorAlive(job.anchor) && (job.kind==='SHOP'||job.kind==='ACCOUNT_EDIT'&&!!xunGetStore().accounts[job.accountId]||xunStateInteractionAlive(job.kind,job.interaction));
}
function xunStateReceipt(kind,interaction) {
  const ids=xunArr(interaction?.messages||interaction?.comments).map(m=>xunText(m?.id)).filter(Boolean).sort();
  if(!ids.length)throw new Error('本轮缺少消息标识，未写入MVU。');
  return JSON.stringify([kind,interaction?.accountId||interaction?.roomId||interaction?.post?.id||'',ids]);
}
function xunCoalesceStateEvents(events){
  const out=[],seen=new Set(),relations=new Map();
  for(const event of xunArr(events).slice(0,6)){
    const data=xunParseStateEventData(event),key=JSON.stringify([event?.type,Object.entries(data).sort(([a],[b])=>a.localeCompare(b))]);
    if(seen.has(key))continue;seen.add(key);
    if(event?.type!=='relationship'){out.push(event);continue;}
    const name=xunText(data.character);if(!name)continue;
    let target=relations.get(name);
    if(!target){target={character:name};relations.set(name,target);out.push({type:'relationship',data:target});}
    for(const field of ['goodwill','trust','familiarity','friendship','love'])if(Number.isFinite(data[field]))target[field]=(target[field]||0)+data[field];
    if(data.first_contact===true)target.first_contact=true;
    if(xunText(data.state))target.state=xunText(data.state);
  }
  return out.map(e=>e.data?{type:e.type,data_json:JSON.stringify(e.data)}:e);
}
function xunWriteStateEvents(job) {
  return new Promise((resolve,reject)=>{
    xunMvuQueue.push({...job,resolve,reject});
    void xunFlushMvuQueue();
  });
}
async function xunFlushMvuQueue() {
  if(xunMvuBusy||xunMvuFlushBusy||!xunMvuQueue.length)return;
  xunMvuFlushBusy=true;
  try {
    const api=await xunRequireMvuApi(5000);
    while(!xunMvuBusy&&xunMvuQueue.length){
      const job=xunMvuQueue.shift();
      try {
        if(!xunStateJobAlive(job))throw new Error('原通讯已回退或已切换聊天，未写入MVU。');
        const target=xunChatRows().length-1;
        if(target<0)throw new Error('没有可写入的聊天楼层。');
        const scope={type:'message',message_id:target};
        const current=xunObj(api.getMvuData(scope));

        if(!xunHasMeaningfulMvu(current))throw new Error('当前楼层的MVU尚未继承完成，请完成变量处理后重试本轮同步。');
        const next=xunClone(current),stat=xunStatRoot(next);
        const receipts=xunObj(xunObj(stat.系统记录).讯匣同步);
        if(receipts[job.receipt]===true){job.resolve({patches:[],duplicate:true});continue;}
        const patches=[];
        if(['SHOP','ACCOUNT_EDIT'].includes(job.kind)){if(typeof job.apply!=='function')throw new Error('购物结算任务缺少处理器');job.apply(stat);}
        const exchangeCharacters=['SHOP','ACCOUNT_EDIT'].includes(job.kind)?new Set():xunExchangeCharacterNames(job.kind,job.interaction,xunGetStore(),stat);
        for(const event of xunCoalesceStateEvents(job.events)){
          for(const patch of xunStateEventToPatches(event,{kind:job.kind,stat,exchangeCharacters}))if(xunApplyPatch(stat,patch))patches.push(patch);
        }

        stat.系统记录={...xunObj(stat.系统记录),讯匣同步:{...receipts,[job.receipt]:true}};
        if(!xunStateJobAlive(job)||xunMvuBusy||target!==xunChatRows().length-1)throw new Error('写入前分支或变量状态已变化，本轮未写入。');
        await api.replaceMvuData(next,scope);
        if(xunStateJobAlive(job))xunRememberStableMvu(next);
        job.resolve({patches,duplicate:false});
      }catch(err){job.reject(err);}
    }
  }catch(err){
    for(const job of xunMvuQueue.splice(0))job.reject(err);
  }finally{xunMvuFlushBusy=false;}
}

function xunParseStateEventData(raw) {
  const text=xunText(raw?.data_json);
  if(!text)return {};
  try { return xunObj(JSON.parse(text)); } catch (_) { return {}; }
}
function xunStateSource(kind){
  return xunText(kind)==='DM'?'讯匣私讯':xunText(kind)==='ROOM'?'讯匣群聊':'城域讯网公开讨论';
}
function xunRecordHas(obj,key){return Object.prototype.hasOwnProperty.call(xunObj(obj),key);}
function xunUniqueRecordKey(record,base){
  record=xunObj(record);base=xunText(base).slice(0,80);if(!base)return '';
  if(!xunRecordHas(record,base))return base;
  for(let i=2;i<20;i++){const k=`${base}·${i}`;if(!xunRecordHas(record,k))return k;}
  return `${base}·${Date.now().toString(36)}`;
}
function xunDelta6(v){const n=v;return Number.isFinite(n)?Math.max(-6,Math.min(6,Math.round(n))):0;}

function xunStateEventToPatches(raw,{kind,stat,exchangeCharacters}){
  const type=xunText(raw?.type),data=xunParseStateEventData(raw),source=xunStateSource(kind),patches=[];
  const life=xunObj(stat.城市生活),enc=xunEncodePointer;
  const set=(parent,key,path,value)=>{
    if(!xunRecordHas(parent,key))patches.push({op:'insert',path,value});
    else if(JSON.stringify(parent[key])!==JSON.stringify(value))patches.push({op:'replace',path,value});
  };
  if(type==='schedule'||type==='agreement'){
    const name=xunText(data.name).slice(0,80);if(!name)return [];
    const record=xunObj(life.日程),exists=xunRecordHas(record,name),old=xunObj(record[name]),path=`/城市生活/日程/${enc(name)}`;
    const value={};
    for(const [src,dst,max] of [['domain','领域',20],['time','时间',120],['place','地点',160],['content','内容',800],['status','状态',30]]){
      if(!xunRecordHas(data,src))continue;
      const v=xunText(data[src]).slice(0,max);if(!v)continue;
      if(src==='domain'&&!['工作','私人'].includes(v))return [];
      if(src==='status'&&!['待发生','进行中','已完成','已取消','已错过'].includes(v))return [];
      value[dst]=v;
    }
    if(Array.isArray(data.characters))value.人物=xunUnique(data.characters).filter(n=>exchangeCharacters.has(n)||xunArr(old.人物).includes(n)||xunRecordHas(stat.人物档案,n)||xunRecordHas(stat.人物关系,n)||['我','{{user}}'].includes(n)).slice(0,8);
    if(!exists){
      if(!value.领域||!value.时间||!value.内容)return [];
      return [{op:'insert',path,value:{人物:[],状态:'待发生',来源:source,...value}}];
    }

    for(const [key,v] of Object.entries(value))set(old,key,`${path}/${enc(key)}`,v);
    return patches;
  }
  if(type==='person_state'){
    const character=xunText(data.character),field=xunText(data.field);
    if(!character||!exchangeCharacters.has(character)||!['工作状态','身体状态','司法状态','联络状态','最后所知位置'].includes(field))return [];
    const current=xunObj(xunObj(life.人物)[character]),path=`/城市生活/人物/${enc(character)}/${enc(field)}`;
    if(field==='最后所知位置'){
      const place=xunText(data.place).slice(0,160),basis=xunText(data.basis).slice(0,300),time=xunText(data.time).slice(0,120);
      if(!place||!basis)return [];
      const value={...xunObj(current[field]),地点:place,依据:basis};
      if(time)value.时间=time;
      else if(place!==xunText(xunObj(current[field]).地点))delete value.时间;  
      set(current,field,path,value);
    }else{const value=xunText(data.value).slice(0,500);if(value)set(current,field,path,value);}
    return patches;
  }
  if(type==='contact'){
    const character=xunText(data.character);if(!character||!exchangeCharacters.has(character)||typeof data.obtained!=='boolean')return [];
    const method=xunText(data.method).slice(0,120),basis=xunText(data.source).slice(0,300),obtained=data.obtained;
    if(!basis||(obtained&&!method))return [];
    const current=xunObj(xunObj(life.人物)[character]),old=xunObj(current.联系方式);
    if(!obtained&&!xunRecordHas(current,'联系方式'))return [];
    if(!obtained&&method&&method!==xunText(old.方式))return [];  
    const value={...old,已取得:obtained,方式:method||xunText(old.方式),来源:obtained?basis:xunText(old.来源)};
    if(obtained)delete value.失效依据;else value.失效依据=basis;
    set(current,'联系方式',`/城市生活/人物/${enc(character)}/联系方式`,value);return patches;
  }
  if(type==='relationship'){
    const character=xunText(data.character);if(!character||!exchangeCharacters.has(character))return [];
    const relations=xunObj(stat.人物关系),existing=xunObj(relations[character]);
    const fields=[['goodwill','好感度'],['trust','信任度'],['familiarity','熟悉度'],['friendship','友情值'],['love','爱情值']];
    if(!xunRecordHas(relations,character)){
      if(data.first_contact!==true)return [];
      const value=xunClone(XUN_INITIAL_RELATION);
      for(const [src,dst] of fields)value[dst]=Math.max(0,Math.min(200,value[dst]+xunDelta6(data[src])));
      const state=xunText(data.state).slice(0,80);if(state)value.关系状态=state;
      return [{op:'insert',path:`/人物关系/${enc(character)}`,value}];
    }
    for(const [src,dst] of fields){const delta=xunDelta6(data[src]);if(delta){if(!Number.isFinite(existing[dst]))throw new Error(`${character}的${dst}缺少有效旧值，未擅自重置。`);patches.push({op:'delta',path:`/人物关系/${enc(character)}/${enc(dst)}`,value:delta});}}
    const state=xunText(data.state).slice(0,80);if(state)set(existing,'关系状态',`/人物关系/${enc(character)}/关系状态`,state);
    return patches;
  }
  if(type==='police_statement'){
    const caseName=xunText(data.case),character=xunText(data.character),topic=xunText(data.topic).slice(0,100),statement=xunText(data.statement).slice(0,1200);
    const police=xunObj(stat.警务事项),current=xunObj(xunObj(police[caseName]).当前案情);
    if(!xunRecordHas(police,caseName)||!exchangeCharacters.has(character)||!xunRecordHas(xunObj(current.人物),character)||!topic||!statement)return [];
    const sayings=xunObj(xunObj(current.人物说法)[character]),time=xunText(data.time)||[life.世界?.日期,life.世界?.时间].filter(Boolean).join(' '),scene=xunText(data.scene)||source;
    const nature=xunText(data.nature)||'初次陈述',corresponds=xunText(data.corresponds);
    if(!['初次陈述','补充','更正','撤回','拒绝说明'].includes(nature))return [];
    if(corresponds&&!xunRecordHas(sayings,corresponds))throw new Error('证言对应的旧记录不存在，未写入更正。');
    if(['更正','撤回'].includes(nature)&&!corresponds)throw new Error('更正或撤回证言需要对应的旧记录名。');
    const value={时间:time,场景:scene,主题:topic,内容:statement,性质:nature};if(corresponds)value.对应=corresponds;
    if(Object.values(sayings).some(v=>JSON.stringify(v)===JSON.stringify(value)))return [];
    return [{op:'insert',path:`/警务事项/${enc(caseName)}/当前案情/人物说法/${enc(character)}/${enc(xunUniqueRecordKey(sayings,topic))}`,value}];
  }
  return [];
}

async function xunApplyGeneratedSideEffects({kind,data,interaction,anchor,epoch=xunMvuEpoch}){
  kind=xunText(kind);if(!['DM','THREAD','ROOM'].includes(kind)||!xunHasBidirectionalExchange(kind,interaction))return {patches:[],memories:[]};
  if(!xunArr(data?.state_events).length&&!xunArr(data?.memories).length)return {patches:[],memories:[]};
  const receipt=xunStateReceipt(kind,interaction),job={kind,interaction,anchor:anchor||xunAnchor(),epoch,chat:xunSillyTavernContext()?.chat,receipt,events:xunArr(data?.state_events)};
  if(!xunStateJobAlive(job))throw new Error('原通讯已回退，未同步变量。');
  const result=await xunWriteStateEvents(job);
  if(!xunStateJobAlive(job))return {patches:result.patches,memories:[]};
  const store=xunGetStore(),stat=xunStatRoot(await xunMvuData()),saved=[];
  if(!xunStateJobAlive(job))return {patches:result.patches,memories:[]};
  if(xunGetConfig().memoryEnabled!==false){
    const accounts=xunInteractionAccounts(store,stat,interaction),allowedChars=xunExchangeCharacterNames(kind,interaction,store,stat);
    const participants=xunUnique(accounts.map(r=>r?.account?.displayName||r?.account?.handle)).slice(0,10),world=xunObj(xunObj(stat.城市生活).世界);
    for(const [i,mem] of xunArr(data?.memories).slice(0,2).entries()){
      const summary=xunText(mem?.summary).slice(0,1200);if(!summary)continue;
      if(xunArr(store.memories).some(m=>m.syncReceipt===receipt&&m.syncIndex===i))continue;
      saved.push({id:xunId('memory'),kind,summary,characters:xunUnique(mem?.characters).filter(n=>allowedChars.has(n)).slice(0,8),participants,topics:xunUnique(mem?.topics).slice(0,8),worldTime:[world.日期,world.时间].filter(Boolean).join(' '),createdAt:xunNow(),anchor:job.anchor,syncReceipt:receipt,syncIndex:i});
    }
  }
  const latest=xunGetStore();latest.memories=[...xunArr(latest.memories),...saved.filter(row=>!xunArr(latest.memories).some(m=>m.syncReceipt===row.syncReceipt&&m.syncIndex===row.syncIndex))].slice(-300);latest.meta=xunObj(latest.meta);latest.meta.lastStateSyncAt=xunNow();
  if(saved.length)latest.meta.lastMemoryAt=xunNow();
  if(latest.stateSyncPending)delete latest.stateSyncPending[receipt];
  await xunSaveStore(latest);
  return {patches:result.patches,memories:saved};
}
async function xunRunStateSync(args){
  const epoch=args.epoch??xunMvuEpoch;
  try{return await xunApplyGeneratedSideEffects({...args,epoch});}
  catch(err){
    if(epoch===xunMvuEpoch&&xunAnchorAlive(args.anchor)){
      const store=xunGetStore(),receipt=xunStateReceipt(args.kind,args.interaction);
      store.stateSyncPending={...xunObj(store.stateSyncPending),[receipt]:{...xunClone(args),epoch:undefined,error:err?.message||String(err)}};
      await xunSaveStore(store);
      try{toastr?.error?.('讯匣内容已保留，MVU同步失败：'+(err?.message||err)+'。可在设置中重试同步。');}catch(_){}
    }
    throw err;
  }
}
function xunApplyGeneratedSideEffectsAsync(args){
  void xunRunStateSync({...args,epoch:xunMvuEpoch}).catch(err=>console.warn('[ShiomiXun] 本轮事实同步失败',err));
}
async function xunRetryStateSync(){
  const pending=Object.values(xunObj(xunGetStore().stateSyncPending));let done=0;
  for(const args of pending){if(!xunAnchorAlive(args.anchor))continue;await xunRunStateSync({...args,epoch:xunMvuEpoch});done++;}
  return done;
}

function xunPushNotification(store, { type = 'notice', title = '', text = '', accountId = '', postId = '', roomId = '', anchor = null } = {}) {
