async function xunMarkNotificationsRead({ id = '', type = '', accountId = '', postId = '', roomId = '', all = false } = {}) {
  const store = xunGetStore();
  let changed = false;
  for (const n of xunArr(store.notifications)) {
    const hit = all || (id && n.id === id) || (type && n.type === type) || (accountId && n.accountId === accountId) || (postId && n.postId === postId) || (roomId && n.roomId === roomId);
    if (hit && n.read !== true) { n.read = true; changed = true; }
  }
  if (changed) await xunSaveStore(store);
  return changed;
}

async function xunMarkConversationRead(kind, id) {
  const store = xunGetStore(); id = xunText(id); let changed = false;
  if (kind === 'dm') {
    const dm = store.chats[`dm:${id}`]; if (dm && Number(dm.unread || 0) !== 0) { dm.unread = 0; changed = true; }
    for (const n of xunArr(store.notifications)) if (n.accountId === id && n.read !== true) { n.read = true; changed = true; }
  } else if (kind === 'room') {
    const room = store.rooms[id]; if (room && Number(room.unread || 0) !== 0) { room.unread = 0; changed = true; }
    for (const n of xunArr(store.notifications)) if (n.roomId === id && n.read !== true) { n.read = true; changed = true; }
  }
  if (changed) await xunSaveStore(store);
  return changed;
}

async function xunRepostPost(postId, { text = '', board = '' } = {}) {
  const store = await xunBootstrapAccounts();
  const source = store.posts[xunText(postId)];
