  const id = xunId('post'), anchor = xunAnchor();
  const sourceAccount=xunObj(store.accounts[source.authorId]);
  const post = {
    id, authorId: 'user', board: xunText(board || source.board || '汐见地方板'), text: xunText(text).slice(0, 2400),
    repostOf: source.id,
    repostSnapshot:{authorId:source.authorId,displayName:xunText(sourceAccount.displayName),handle:xunText(sourceAccount.handle),text:xunText(source.text).slice(0,5000),board:xunText(source.board),category:xunText(source.category),topics:xunUnique(source.topics).slice(0,8)},
    topics: xunUnique(source.topics).slice(0, 8), media: [], comments: [], createdAt: xunNow(), anchor, origin: 'user-repost'
  };
  store.posts[id] = post; store.postOrder.push(id); store.postOrder = store.postOrder.slice(-600);
