function xunNarrativeMessageBlocks(body) {
  const out = [];
  const re = /<xun_message\b([^>]*)>\s*([\s\S]*?)\s*<\/xun_message>/gi;
  let match;
  while ((match = re.exec(String(body || ''))) !== null) {
    const attrs = {}, attrRe = /([A-Za-z_][\w:-]*)\s*=\s*"([^"]*)"/g;
    let attr;
    while ((attr = attrRe.exec(match[1] || '')) !== null) attrs[attr[1]] = xunText(attr[2]);
    const text = xunText(match[2]).slice(0, 1600);
    const type = xunText(attrs.type).toLowerCase();
    if (!text || !['dm','room'].includes(type)) continue;
    out.push({ ...attrs, type, text });
    if (out.length >= 40) break;
  }
  return out;
}

function xunNarrativeRowAnchor(row, messageId) {
  const swipeId = xunRowSwipeId(row), body = xunRowBody(row, swipeId);
  return {
    messageId,
    swipeId,
    fingerprint: xunHash(body),
    sendDate: xunRowSendDate(row),
    at: xunNow()
  };
}

function xunNarrativeSourceKey(anchor, index, message) {
  const a = xunNormalizeAnchor(anchor);
  let payload = '';
  try { payload = JSON.stringify(message); } catch (_) { payload = String(message || ''); }
  return `xmsg:${xunHash([a.fingerprint,a.swipeId,a.sendDate,index,xunHash(payload)].join('|'))}`;
}

function xunNarrativeKnownSourceKeys(store) {
  const keys = new Set(Object.keys(xunObj(store?.deletedNarrativeMessages)));
  for (const chat of Object.values(xunObj(store?.chats))) for (const m of xunArr(chat?.messages)) if (m?.sourceKey) keys.add(xunText(m.sourceKey));
  for (const room of Object.values(xunObj(store?.rooms))) for (const m of xunArr(room?.messages)) if (m?.sourceKey) keys.add(xunText(m.sourceKey));
  return keys;
}

function xunNarrativeName(raw) {
  const name = xunText(xunSubstituteMacros(raw));
  if (!name) return '';
  if (/^(?:user|我|本人)$/i.test(name) || xunIsUserMacro(raw) || name === xunCurrentUserName()) return 'user';
  return name;
}

// Resolve public account identifiers before creating a private narrative contact.
function xunNarrativeIdentityKey(value){return xunText(value).normalize('NFKC').replace(/^@/,'').replace(/\s+/g,'').toLowerCase();}
function xunNarrativePlaceholder(account){return !!account?.id?.startsWith('contact:')&&account.privateOnly===true&&!xunText(account.handle);}
function xunCanonicalNarrativeAccountId(store,id){
  id=xunText(id);const seen=new Set();
  while(store?.narrativeAccountRedirects?.[id]&&!seen.has(id)){seen.add(id);id=store.narrativeAccountRedirects[id];}
  return id;
}
function xunFindNarrativeAccount(store,value,{excludeId='',canonicalOnly=false}={}){
  const raw=xunText(value);if(!raw)return {id:'',ambiguous:false};
  const direct=xunCanonicalNarrativeAccountId(store,raw);
  if(direct!==excludeId&&store.accounts?.[direct]&&(!canonicalOnly||!xunNarrativePlaceholder(store.accounts[direct])))return {id:direct,ambiguous:false};
  const tokens=xunUnique([raw,...raw.split(/[｜|丨／/·•]/),...(raw.match(/@[A-Za-z0-9_.\-\u3040-\u30ff\u3400-\u9fff]+/g)||[]),raw.replace(/[（(][^）)]*[）)]/g,'')]);
  const wanted=new Set(tokens.map(xunNarrativeIdentityKey).filter(Boolean));
  const accounts=Object.values(xunObj(store.accounts)).filter(a=>a?.id&&a.id!=='user'&&a.id!==excludeId);
  const canonical=accounts.filter(a=>!xunNarrativePlaceholder(a));
  const match=pool=>{
    // A unique explicit account number outranks a nickname collision.
    let hits=pool.filter(a=>a.handle&&wanted.has(xunNarrativeIdentityKey(a.handle)));
    if(!hits.length)hits=pool.filter(a=>[a.displayName,a.characterName,...xunArr(a.profileHistory).flatMap(h=>xunArr(h.changes).filter(c=>['displayName','handle'].includes(c.field)).map(c=>c.before))].some(n=>n&&wanted.has(xunNarrativeIdentityKey(n))));
    return {id:hits.length===1?hits[0].id:'',ambiguous:hits.length>1};
  };
  const found=match(canonical);
  if(found.id||found.ambiguous||canonicalOnly)return found;
  return match(accounts.filter(xunNarrativePlaceholder));
}
function xunRebindNarrativeReferences(value,redirects){
  if(!value||typeof value!=='object')return;
  const fields=new Set(['accountId','authorId','from','to','ownerId','profileId','contactId','targetAccountId','sourceAccountId']);
  const arrays=new Set(['participantIds','accountIds','allowedAccountIds']);
  for(const [key,item] of Object.entries(value)){
    if(fields.has(key)&&typeof item==='string'&&redirects[item])value[key]=redirects[item];
    else if(arrays.has(key)&&Array.isArray(item))value[key]=xunUnique(item.map(id=>redirects[id]||id));
    else if(item&&typeof item==='object')xunRebindNarrativeReferences(item,redirects);
  }
}
function xunMergeNarrativeDmMaps(chats,redirects){
  for(const [from,to] of Object.entries(redirects)){
    const old=chats?.['dm:'+from];if(!old)continue;
    const current=chats['dm:'+to]||{id:'dm:'+to,type:'dm',accountId:to,messages:[],unread:0,updatedAt:''};
    const seenIds=new Set(),seenSources=new Set(),messages=[];
    for(const message of [...xunArr(current.messages),...xunArr(old.messages)]){
      if(message.id&&seenIds.has(message.id)||message.sourceKey&&seenSources.has(message.sourceKey))continue;
      if(message.id)seenIds.add(message.id);if(message.sourceKey)seenSources.add(message.sourceKey);messages.push(message);
    }
    messages.sort((a,b)=>{const left=Date.parse(a.createdAt),right=Date.parse(b.createdAt);return Number.isFinite(left)&&Number.isFinite(right)?left-right:0;});
    chats['dm:'+to]={...old,...current,id:'dm:'+to,type:'dm',accountId:to,messages,
      unread:Math.min(messages.length,Math.max(0,Number(old.unread)||0)+Math.max(0,Number(current.unread)||0)),
      updatedAt:[old.updatedAt,current.updatedAt].filter(Boolean).sort().at(-1)||''};
    delete chats['dm:'+from];
  }
}
function xunRepairNarrativeContacts(store){
  const redirects={};
  for(const account of Object.values(xunObj(store.accounts))){
    if(!xunNarrativePlaceholder(account))continue;
    const found=xunFindNarrativeAccount(store,account.characterName||account.displayName,{excludeId:account.id,canonicalOnly:true});
    if(found.id)redirects[account.id]=found.id;
  }
  if(!Object.keys(redirects).length)return false;
  // Decode before any mutation. An unreadable archive must never be overwritten.
  const archives=xunArr(store.archives).map(row=>({row,data:xunUnpack(row.data)}));
  for(const data of [store,...archives.map(a=>a.data)]){
    xunRebindNarrativeReferences(data,redirects);
    xunMergeNarrativeDmMaps(data.chats,redirects);
    const follows=data.signals?.follows;
    if(follows)for(const [from,to]of Object.entries(redirects))if(Object.hasOwn(follows,from)){if(!Object.hasOwn(follows,to))follows[to]=follows[from];delete follows[from];}
    if(data.agreementReceipts){
      for(const [key,id]of Object.entries(data.agreementReceipts))try{
        const receipt=JSON.parse(key);if(Array.isArray(receipt)&&redirects[receipt[1]]){receipt[1]=redirects[receipt[1]];const next=JSON.stringify(receipt);if(!data.agreementReceipts[next])data.agreementReceipts[next]=id;delete data.agreementReceipts[key];}
      }catch(_){}
    }
  }
  store.narrativeAccountRedirects={...xunObj(store.narrativeAccountRedirects),...redirects};
  store.narrativeMergedContacts=xunObj(store.narrativeMergedContacts);
  for(const [from,to]of Object.entries(redirects)){
    store.narrativeMergedContacts[from]={account:xunClone(store.accounts[from]),accountId:to};
    delete store.accounts[from];
  }
  for(const archive of archives)archive.row.data=xunPack(archive.data);
  return true;
}

function xunNarrativeAccount(store, rawName, anchor) {
  const name = xunNarrativeName(rawName);
  if (!name) return '';
  if (name === 'user') return 'user';
  const found=xunFindNarrativeAccount(store,name);
  if(found.id)return found.id;
  if(found.ambiguous)return '';
  const id = `contact:${xunHash(name)}`;
  if (!store.accounts[id]) store.accounts[id] = xunNormalizeAccount({id,kind:'character',displayName:name,characterName:name,handle:'',privateOnly:true,anchor},id);
  return id;
}

function xunNarrativeCreatedAt(row) {
  const raw = xunRowSendDate(row);
  if (raw) {
    const ms = Date.parse(raw);
    if (Number.isFinite(ms)) return new Date(ms).toISOString();
  }
  return xunNow();
}

function xunNarrativeRoom(store, roomName, participantIds, anchor) {
  const name = xunText(roomName) || '聊天室';
  const ids = xunUnique(['user', ...xunArr(participantIds)]).filter(id => store.accounts[id] || id === 'user');
  const same = Object.values(xunObj(store.rooms)).find(r => {
    if (xunText(r?.name) !== name) return false;
    const a = xunUnique(r?.participantIds).slice().sort(), b = ids.slice().sort();
    return JSON.stringify(a) === JSON.stringify(b);
  });
  if (same?.id) return same;
  const id = `room:narrative:${xunHash(`${name}|${ids.slice().sort().join('|')}`)}`;
  if (!store.rooms[id]) store.rooms[id] = { id, name, participantIds: ids, messages: [], unread: 0, updatedAt: '', anchor };
  return store.rooms[id];
}

async function xunImportNarrativeMessages() {
  const rows = xunChatRows();
  if (!rows.length) return 0;
  const store = await xunBootstrapAccounts();
  const known = xunNarrativeKnownSourceKeys(store);
  let imported = 0, changed = false;

  for (let messageId = 0; messageId < rows.length; messageId++) {
    const row = rows[messageId];
    if (!row || row.is_user === true || xunText(row.role).toLowerCase() === 'user') continue;
    const swipeId = xunRowSwipeId(row), body = xunRowBody(row, swipeId);
    if (!body || !body.includes('<xun_message')) continue;
    const messages = xunNarrativeMessageBlocks(body);
    if (!messages.length) continue;
    const anchor = xunNarrativeRowAnchor(row, messageId), createdAt = xunNarrativeCreatedAt(row);

    for (let i = 0; i < messages.length; i++) {
      const ev = xunObj(messages[i]), sourceKey = xunNarrativeSourceKey(anchor, i, ev);
      if (known.has(sourceKey)) continue;
      const payload=xunImagePayload(ev),type = xunText(ev.type).toLowerCase(), text = payload.text, worldTime=xunText(ev.time).slice(0,80);
      if (!text&&!payload.imageWanted) continue;

      if (type === 'dm') {
        const fromName = xunNarrativeName(ev.from), toName = xunNarrativeName(ev.to);
        if (!fromName || !toName || (fromName !== 'user' && toName !== 'user') || (fromName === 'user' && toName === 'user')) continue;
        const otherName = fromName === 'user' ? toName : fromName;
        const accountId = xunNarrativeAccount(store, otherName, anchor);
        if (!accountId || accountId === 'user') continue;

        if (fromName === 'user') {
          const stat=xunStatRoot(await xunMvuData());
          if (!xunPrivateContactState(store,stat,accountId).allowed) continue;
        }
        const dm = xunEnsureDm(store, accountId);
        const message = {
          id: xunId('msg'),
          from: fromName === 'user' ? 'user' : accountId,
          ...payload,
          createdAt,
          worldTime,
          anchor,
          origin: 'narrative',
          sourceKey
        };
        dm.messages.push(message);  dm.updatedAt = createdAt;
        if (fromName !== 'user') {
          dm.unread = Math.max(0, Number(dm.unread) || 0) + 1;
          const a = store.accounts[accountId];
          xunPushNotification(store, { type:'dm', title:`${a?.displayName || '联系人'}发来讯息`, text, accountId, anchor });
        }
        known.add(sourceKey); imported++; changed = true; continue;
      }

      if (type === 'room') {
        const fromName = xunNarrativeName(ev.from);
        if (!fromName) continue;
        const listed = xunText(ev.participants).split(/[|｜,，]/).map(xunNarrativeName).filter(Boolean);
        const rawParticipants = xunUnique(['user', ...listed, fromName]).filter(Boolean);
        const participantIds = rawParticipants.map(name => xunNarrativeAccount(store, name, anchor)).filter(Boolean);
        const authorId = xunNarrativeAccount(store, fromName, anchor);
        if (!authorId) continue;
        const room = xunNarrativeRoom(store, ev.room || ev.name, participantIds, anchor);
        room.participantIds = xunUnique([...xunArr(room.participantIds), ...participantIds, 'user']);
        const message = { id:xunId('msg'), authorId, ...payload, createdAt, worldTime, anchor, origin:'narrative', sourceKey };
        room.messages.push(message);  room.updatedAt = createdAt;
        if (authorId !== 'user') {
          room.unread = Math.max(0, Number(room.unread) || 0) + 1;
          const a = store.accounts[authorId];
          xunPushNotification(store, { type:'room', title:`${room.name || '聊天室'}有新讯息`, text:`${a?.displayName ? a.displayName + '：' : ''}${text}`, accountId:authorId, roomId:room.id, anchor });
        }
        known.add(sourceKey); imported++; changed = true;
      }
    }
  }

  if (changed) await xunSaveStore(store);
  return imported;
}

let xunNarrativeSyncChain = Promise.resolve();
function xunSyncNarrativeNow(){
  const chat=xunSillyTavernContext()?.chat,epoch=xunMvuEpoch;
  const guard=()=>{if(chat!==xunSillyTavernContext()?.chat||epoch!==xunMvuEpoch)throw new Error('聊天已切换，正文通讯同步已停止。');};
  xunNarrativeSyncChain=xunNarrativeSyncChain.catch(()=>{}).then(async()=>{
    guard();await xunReconcileStore();guard();await xunImportNarrativeMessages();guard();await xunReconcileStore();guard();await xunSyncAccountWorldbook();
  });return xunNarrativeSyncChain;
}
function xunQueueNarrativeSync(delay=60){
  const chat=xunSillyTavernContext()?.chat,epoch=xunMvuEpoch;
  setTimeout(()=>{if(chat!==xunSillyTavernContext()?.chat||epoch!==xunMvuEpoch)return;
    void xunSyncNarrativeNow().catch(err=>console.warn('[ShiomiXun] 正文通讯同步失败',err));
  },delay);
}

function xunReconcileAnchorOn(row) {
  if (!row || !row.anchor) return { alive: true, moved: false };
  const resolved = xunResolveAnchor(row.anchor);
  if (!resolved.alive) return resolved;
  if (resolved.anchor && JSON.stringify(xunNormalizeAnchor(row.anchor)) !== JSON.stringify(resolved.anchor)) row.anchor = resolved.anchor;
  return resolved;
}

async function xunReconcileStore() {
  const store = xunGetStore();
  let changed = false;
  if(xunReconcileProfiles(store))changed=true;
  const cacheRefsToDelete = [];
  for(const [key,row] of Object.entries(xunObj(store.deletedNarrativeMessages)))if(!xunReconcileAnchorOn(row).alive){delete store.deletedNarrativeMessages[key];changed=true;}
  const news=xunArr(store.news),keptNews=news.filter(n=>xunReconcileAnchorOn(n).alive);
  if(keptNews.length!==news.length){store.news=keptNews;changed=true;}

  for (const id of [...store.postOrder]) {
    const p = store.posts[id];
    if (!p) { changed = true; continue; }
    const state = xunReconcileAnchorOn(p);
    if (!state.alive) { delete store.posts[id]; changed = true; }
    else if (state.moved) changed = true;
  }
  store.postOrder = store.postOrder.filter(id => store.posts[id]);

  for (const [accountId, chat] of Object.entries(store.chats)) {
    const before = xunArr(chat.messages).length;
    const kept = [];
    for (const m of xunArr(chat.messages)) {
      const state = xunReconcileAnchorOn(m);
      if (state.alive) { kept.push(m); if (state.moved) changed = true; }
    }
    chat.messages = kept;
    if (kept.length !== before) changed = true;
    if (!store.accounts[accountId] && !kept.length) { delete store.chats[accountId]; changed = true; }
  }

  for (const [roomId, room] of Object.entries(store.rooms)) {
    const roomState = xunReconcileAnchorOn(room);
    if (room.anchor && !roomState.alive) { delete store.rooms[roomId]; changed = true; continue; }
    if (roomState.moved) changed = true;
    const before = xunArr(room.messages).length;
    const kept = [];
    for (const m of xunArr(room.messages)) {
      const state = xunReconcileAnchorOn(m);
      if (state.alive) { kept.push(m); if (state.moved) changed = true; }
    }
    room.messages = kept;
    if (kept.length !== before) changed = true;
  }

  const keptMemories = [];
  for (const m of xunArr(store.memories)) {
    const state = xunReconcileAnchorOn(m);
    if (state.alive) { keptMemories.push(m); if (state.moved) changed = true; }
    else changed = true;
  }
  store.memories = keptMemories;

  const keptNotices = [];
  for (const n of xunArr(store.notifications)) {
    const state = xunReconcileAnchorOn(n);
    if (state.alive) { keptNotices.push(n); if (state.moved) changed = true; }
    else changed = true;
  }
  store.notifications = keptNotices;

  const referencedAccounts = new Set(['user']);
  for (const p of Object.values(store.posts)) {
    if (p?.authorId) referencedAccounts.add(xunText(p.authorId));
    for (const c of xunArr(p?.comments)) if (c?.authorId) referencedAccounts.add(xunText(c.authorId));
  }
  for (const [accountId, chat] of Object.entries(store.chats)) {
    referencedAccounts.add(xunText(accountId));
    for (const m of xunArr(chat?.messages)) if (m?.from) referencedAccounts.add(xunText(m.from));
  }
  for (const room of Object.values(store.rooms)) {
    for (const id of xunArr(room?.participantIds)) referencedAccounts.add(xunText(id));
    for (const m of xunArr(room?.messages)) if (m?.authorId) referencedAccounts.add(xunText(m.authorId));
  }
  for (const n of store.notifications) if (n?.accountId) referencedAccounts.add(xunText(n.accountId));

  for (const [id, account] of Object.entries(store.accounts)) {
    if (id === 'user') continue;
    if (account?.kind === 'character' && account?.privateOnly !== true) continue;
    const state = xunReconcileAnchorOn(account);
    if (state.moved) changed = true;
    if (account?.anchor && !state.alive && !referencedAccounts.has(id)) { delete store.accounts[id]; changed = true; }
  }

  for(const [id,job] of Object.entries(xunObj(store.stateSyncPending)))if(!xunAnchorAlive(job.anchor)||!xunStateInteractionAlive(job.kind,job.interaction)){delete store.stateSyncPending[id];changed=true;}
  const referencedMedia = new Set();
  for (const r of xunMediaOwners(store)) for (const mid of xunArr(r?.media)) if (typeof mid === 'string') referencedMedia.add(mid);
  for (const [mid, media] of Object.entries(store.media)) {
    const state = xunReconcileAnchorOn(media);
    if (state.moved) changed = true;
    if (!referencedMedia.has(mid) || (media?.anchor && !state.alive)) {
      if (media?.cacheRef) cacheRefsToDelete.push(xunText(media.cacheRef));
      delete store.media[mid]; changed = true;
    }
  }

  for (const id of Object.keys(xunObj(store.signals.likes))) if (!store.posts[id]) { delete store.signals.likes[id]; changed = true; }
  for (const id of Object.keys(xunObj(store.signals.hiddenPosts))) if (!store.posts[id]) { delete store.signals.hiddenPosts[id]; changed = true; }
  for (const id of Object.keys(xunObj(store.signals.follows))) if (!store.accounts[id]) { delete store.signals.follows[id]; changed = true; }

  if (changed) await xunSaveStore(store);
  for (const ref of cacheRefsToDelete) if (ref) void xunImageDbDelete(ref);
  return changed;
}

