function boxDecorateActionIcons(root){
  if(!root) return;
  root.querySelectorAll('.xb-btn[data-action]').forEach(btn=>{
    if(btn.querySelector(':scope > .xb-btn-svg')) return;
    const ico=boxActionIcons[btn.dataset.action]||'';
    if(!ico) return;
    btn.insertAdjacentHTML('afterbegin',boxSvg(ico,'xb-btn-svg'));
    btn.classList.add('has-svg');
  });
}


