function boxImageContent(row){return boxApi()?.imageContent?.(row)||{text:boxText(row?.text),mediaNote:boxText(row?.mediaNote),prompts:[]};}

function boxAccountText(value){
  const text=String(value??''),re=/(?<![A-Za-z0-9_@＠\/.:\-])[＠@][A-Za-z0-9_\-\u3040-\u30ff\u3400-\u9fff](?:[A-Za-z0-9_.\-\u3040-\u30ff\u3400-\u9fff]{0,78}[A-Za-z0-9_\-\u3040-\u30ff\u3400-\u9fff])?(?![A-Za-z0-9_\-\u3040-\u30ff\u3400-\u9fff])/gu;
  let html='',cursor=0;
  for(const m of text.matchAll(re)){
    html+=boxEsc(text.slice(cursor,m.index));
    const handle=m[0].replace(/^＠/,'@');
    html+=`<button class="xb-link" data-action="open-handle" data-handle="${boxEsc(handle)}" data-reference="${boxEsc(text.slice(Math.max(0,m.index-600),m.index+800))}" style="font:inherit;overflow-wrap:anywhere">${boxEsc(m[0])}</button>`;
    cursor=m.index+m[0].length;
  }
  return html+boxEsc(text.slice(cursor));
}

function boxRecordBody(s,record,kind,ownerId){
  const parsed=boxImageContent(record),media=boxMediaHtml(s,record.media);
  const key=JSON.stringify([kind,ownerId,record.id]);
  const buttons=parsed.prompts.map((p,i)=>{
    const busy=boxImageBusyMatch(key,i),generated=boxMediaItems(s,record.media).some(m=>m.source==='tavern-image-plugin'&&Number(m.slot||0)===i);
    return `<div class="xb-actions"><button class="xb-btn ${busy?'busy':''}" data-action="record-image-generate" data-kind="${boxEsc(kind)}" data-owner-id="${boxEsc(ownerId)}" data-message-id="${boxEsc(record.id)}" data-image-index="${i}" ${busy?'disabled':''}>${busy?'生成中…':generated?'重新生成':'生成配图'}${parsed.prompts.length>1?' '+(i+1):''}</button></div>`;
  }).join('');
  return `${boxAccountText(parsed.text)}${media}${parsed.mediaNote?`<div class="xb-muted" style="margin-top:5px">图像：${boxAccountText(parsed.mediaNote)}</div>`:''}${buttons?`<details class="xb-message-menu"><summary>配图操作</summary>${buttons}</details>`:''}`;
}

function boxMediaItems(s, refs){
  const store=boxObj(s.store), media=boxObj(store.media), out=[];
  for(const ref of boxArr(refs)){
