  const canvas=boxDoc.createElement('canvas'); canvas.width=size; canvas.height=size;
  const ctx=canvas.getContext('2d',{alpha:false}); if(!ctx) throw new Error('当前浏览器无法处理头像。');
  ctx.drawImage(img,sx,sy,side,side,0,0,size,size);
  let out='';
  try{out=canvas.toDataURL('image/webp',.82);}catch(_){}
  if(!out||out==='data:,'||!/^data:image\/webp/i.test(out)) out=canvas.toDataURL('image/jpeg',.84);
  if(!out||out==='data:,') throw new Error('头像压缩失败。');
