  const nationalSerial=new Set(national.map(e=>boxCalSerial(e.year,e.month,e.day)));
  const occupied=new Set(nationalSerial);
  [...nationalSerial].sort((a,b)=>a-b).forEach(serial=>{
    if(nationalSerial.has(serial+2)&&!nationalSerial.has(serial+1)){
      const dt=boxCalFromSerial(serial+1,y);
