function boxRecommendationScore(s,p){
  const c=boxObj(s.config),store=boxObj(s.store),sig=boxObj(store.signals),a=boxObj(store.accounts?.[p.authorId]),cat=xunCategoryLabel(p.category),weight=xunFeedPostWeight(c,p,store);
  if(weight<=0)return -Infinity;
  let n=Math.min(30,weight*100);
  n+=(Number(c[a.kind==='character'?'prefFamiliar':'prefStrangers'])||0)*3;
  if(a.kind==='anonymous')n+=(Number(c.prefAnonymous)||0)*2;
  if(boxArr(p.media).length||p.imageWanted)n+=(Number(c.prefImages)||0)*2;
  if(sig.follows?.[p.authorId])n+=9;
  const signals=boxObj(s.recommendation);let behavior=0;
  for(const r of boxArr(signals.category_signals))if(xunCategoryLabel(r.name)===cat)behavior+=Number(r.score||0)*.3;
  for(const r of boxArr(signals.topic_signals))if(boxArr(p.topics).includes(r.name))behavior+=Number(r.score||0)*.3;
  for(const r of boxArr(signals.account_signals))if(r.name===p.authorId)behavior+=Number(r.score||0)*.3;
  n+=Math.max(-10,Math.min(10,behavior));
  const kw=boxText(c.prefKeywords).split(/[,，、;；\s]+/).filter(Boolean),corpus=`${p.text||''} ${boxArr(p.topics).join(' ')}`;
  if(kw.some(k=>corpus.includes(k)))n+=5;
  const order=boxArr(store.postOrder),index=order.indexOf(p.id);n+=index<0?0:12*index/Math.max(1,order.length-1);
  return n;
}
function boxDiversifyFeed(s,posts){
  const remaining=posts.map((p,i)=>({p,i,score:boxRecommendationScore(s,p)})),out=[],authors={},cats={};
  while(remaining.length){
    const score=r=>r.score-(authors[r.p.authorId]||0)*13-(cats[xunCategoryLabel(r.p.category)]||0)*4-(out[out.length-1]?.authorId===r.p.authorId?18:0)-(xunCategoryLabel(out[out.length-1]?.category)===xunCategoryLabel(r.p.category)?8:0);
    remaining.sort((a,b)=>score(b)-score(a)||a.i-b.i);const p=remaining.shift().p;out.push(p);authors[p.authorId]=(authors[p.authorId]||0)+1;const k=xunCategoryLabel(p.category);cats[k]=(cats[k]||0)+1;
  }
  return out;
}
function boxRecommendationReason(s,p){
  if(s.store?.signals?.follows?.[p.authorId])return '你关注的账号';
  if(p.recommendationChannel){const c=XUN_ACCOUNT_CHANNELS.find(c=>c.id===p.recommendationChannel);if(c)return (c.entityType==='person'?'个人 · ':'企业 · ')+c.label;}
  if(boxArr(s.recommendation?.topic_signals).some(r=>Number(r.score)>0&&boxArr(p.topics).includes(r.name)))return '与你喜欢的话题相关';
  return '地方新动态 · 发现不同声音';
}

