const boxRenderers={shop:boxShop,accounts:boxAccountDatabase,dossier:boxAccountDossier,home:boxHome,feed:boxFeed,thread:boxThread,comms:boxComms,dm:boxDm,room:boxRoom,profile:boxProfile,calendar:boxCalendar,work:boxWork,police:boxPolice,private:boxPrivate,people:boxPeople,person:boxPerson,news:boxNews,life:boxLife,search:boxSearch,settings:boxSettings};

async function boxLoadSnapshot(){
  const api=boxApi(); if(!api) return {store:{},stat:{},config:{},error:'讯匣核心尚未就绪。整合版会自动重试；页面外壳与 App 仍应可见。'};
  try{
    const uiOpts={page:boxState.page,postId:boxState.postId,profileId:boxState.profileId,chatId:boxState.chatId,roomId:boxState.roomId,postLimit:220};
    const needFeed=boxState.page==='feed';
    const [mvu,worldbooks,store,feedMeta]=await Promise.all([
      api.readMvu(),
      boxState.page==='settings'&&api.worldbookStatus?api.worldbookStatus(false,boxState.worldbookName||'',boxState.worldbookMode||'social'):Promise.resolve({}),
      api.getStoreForUi?api.getStoreForUi(uiOpts):Promise.resolve(api.getStore()),
      needFeed&&api.feedRecommendationState?Promise.resolve(api.feedRecommendationState()):Promise.resolve({signals:{},plan:{}})
    ]);
    for(const key of ['chatId','profileId'])boxState[key]=store.narrativeAccountRedirects?.[boxState[key]]||boxState[key];
    return {store,stat:boxStatRoot(mvu),config:api.getConfig(),worldbooks,accountWorldbook:api.accountWorldbookStatus?.()||{},generation:api.generationStatus?.()||{},connectionStorage:api.connectionStorageStatus?.()||{},recommendation:boxObj(feedMeta).signals||{},recommendationPlan:boxObj(feedMeta).plan||{}};
  }catch(e){return {store:{},stat:{},config:{},error:e?.message||String(e)};}
}
function boxApplyTheme(root,config){
  root.dataset.theme=['brass','night','paper'].includes(config?.uiTheme)?config.uiTheme:'brass';
  root.dataset.view=boxState.page;
  const active=['dm','room'].includes(boxState.page)?'comms':['thread','profile'].includes(boxState.page)?'feed':boxState.page;
  root.querySelectorAll('.xb-foot [data-page]').forEach(button=>{if(button.dataset.page===active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});
}
async function boxRender(){
  if(boxDestroyed) return;
  if(boxRendering){ boxRenderAgain=true; return; }
  boxRendering=true;
  try {
  if(boxDestroyed) return;
  const token=++boxState.renderToken, root=boxRoot(); if(!root) return;
  const body=root.querySelector('.xb-screen'); if(!body) return;
  const renderView={page:boxState.page,postId:boxState.postId,top:Number(body.scrollTop)||0,left:Number(body.scrollLeft)||0};
  const restoreView=()=>{
    if(boxState.page!==renderView.page)return;
    if(renderView.page==='thread'&&boxState.postId!==renderView.postId)return;
    if(renderView.page==='home')return;
    try{body.scrollTop=renderView.top;body.scrollLeft=renderView.left;}catch(_){}
  };
  const api=boxApi();
  const coreLamp=root.querySelector('.xb-core'); if(coreLamp) coreLamp.textContent=api?'LINK':'OFF';


  const preview=boxState.snap&&typeof boxState.snap==='object'?boxState.snap:{store:{},stat:{},config:{}};
  boxApplyTheme(root,preview.config);
  const previewLife=boxObj(boxObj(preview.stat).城市生活),previewWorld=boxObj(previewLife.世界),previewScene=boxObj(previewLife.当前场景);
  root.querySelector('.xb-clock').textContent=previewWorld.时间||'--:--';
  root.querySelector('.xb-title-main').textContent=boxTitles[boxState.page]||'讯匣';
  const titleMark=root.querySelector('.xb-title-mark'); if(titleMark) titleMark.innerHTML=boxSvg(boxPageIcons[boxState.page]||'terminal','xb-title-svg');
  root.querySelector('.xb-title-sub').textContent=[previewWorld.日期,previewScene.地点].filter(Boolean).join(' · ')||'SHIOMI ELECTRO-MECHANICAL TERMINAL';
  root.querySelector('.xb-back').style.visibility=boxState.page==='home'?'hidden':'visible';
  const shouldPrepaint=!body.childElementCount||boxState.lastRenderedPage!==boxState.page;
  if(shouldPrepaint){const preFn=boxRenderers[boxState.page]||boxHome;body.innerHTML=preFn(preview);boxDecorateActionIcons(body);boxHydrateLazyMedia(root);boxSyncBusyOverlay(root);if(boxState.page==='home')boxResetScreenScroll(true);else restoreView();}

  const snap=await boxLoadSnapshot(); if(token!==boxState.renderToken) return; boxState.snap=snap;
  boxApplyTheme(root,snap.config);
  const life=boxObj(snap.stat.城市生活), world=boxObj(life.世界), scene=boxObj(life.当前场景);
  root.querySelector('.xb-clock').textContent=world.时间||'--:--';
  root.querySelector('.xb-title-main').textContent=boxTitles[boxState.page]||'讯匣';
  const titleMark2=root.querySelector('.xb-title-mark'); if(titleMark2) titleMark2.innerHTML=boxSvg(boxPageIcons[boxState.page]||'terminal','xb-title-svg');
  root.querySelector('.xb-title-sub').textContent=[world.日期,scene.地点].filter(Boolean).join(' · ')||'SHIOMI ELECTRO-MECHANICAL TERMINAL';
  root.querySelector('.xb-back').style.visibility=boxState.page==='home'?'hidden':'visible';
  const coreLamp2=root.querySelector('.xb-core'); if(coreLamp2) coreLamp2.textContent=boxApi()?'LINK':'OFF';
  if(snap.error) body.innerHTML=`<div class="xb-error">${boxEsc(snap.error)}</div>`;
  else { const fn=boxRenderers[boxState.page]||boxHome; body.innerHTML=fn(snap); }
  boxDecorateActionIcons(body);
  boxHydrateLazyMedia(root);
  boxSyncBusyOverlay(root);
  if(boxState.page==='home') boxResetScreenScroll(true); else restoreView();
  boxState.lastRenderedPage=boxState.page;
  } finally {
    boxRendering=false;
    if(boxRenderAgain && !boxDestroyed){
      boxRenderAgain=false;
      (boxWin.setTimeout||setTimeout)(()=>{ if(!boxDestroyed) void boxRender(); },0);
    }
  }
}
function boxResetScreenScroll(force=false){
  const root=boxRoot(), body=root?.querySelector('.xb-screen'); if(!body) return;
  if(force || boxState.page==='home'){
    try{body.scrollTop=0; body.scrollLeft=0;}catch(_){}
    try{boxWin.requestAnimationFrame(()=>{try{body.scrollTop=0; body.scrollLeft=0;}catch(_){}});}catch(_){}
    setTimeout(()=>{try{body.scrollTop=0; body.scrollLeft=0;}catch(_){}},0);
  }
}

function boxImageBusyMatch(postId,index,mode='one'){
  const job=boxObj(boxState.imageBusy);
  if(!job.postId||boxText(job.postId)!==boxText(postId)||boxText(job.mode||'one')!==boxText(mode))return false;
  return mode==='all'||Number(job.index)===Number(index);
}
function boxInlineImageBusy(button,on=true){
  if(!button||!button.isConnected)return;
  try{
    button.classList.toggle('busy',!!on);button.disabled=!!on;
    const old=button.querySelector('[data-xb-inline-image-busy]');
    if(on&&!old)button.insertAdjacentHTML('afterbegin','<span class="xb-inline-spinner" data-xb-inline-image-busy></span>');
    if(!on&&old)old.remove();
  }catch(_){}
}
async function boxDoImage(button,{postId='',index=0,mode='one'}={},fn,ok='配图已生成'){
  if(boxState.imageBusy){boxToast('已有配图任务正在进行','warning');return;}
  const root=boxRoot(),body=root?.querySelector?.('.xb-screen');
  const view={page:boxState.page,postId:boxState.postId,chatId:boxState.chatId,roomId:boxState.roomId,top:Number(body?.scrollTop)||0,left:Number(body?.scrollLeft)||0};
  boxState.imageBusy={postId:boxText(postId),index:Number(index)||0,mode:mode==='all'?'all':'one'};
  boxInlineImageBusy(button,true);
  try{await fn();boxToast(ok,'success');}
  catch(e){boxToast(e?.message||String(e),'error');}
  finally{
    boxState.imageBusy=null;boxInlineImageBusy(button,false);
    if(boxState.page===view.page&&(view.page!=='thread'||boxState.postId===view.postId)&&(view.page!=='dm'||boxState.chatId===view.chatId)&&(view.page!=='room'||boxState.roomId===view.roomId)){
      await boxRender();
      const now=boxRoot()?.querySelector?.('.xb-screen');
      try{if(now){now.scrollTop=view.top;now.scrollLeft=view.left;}}catch(_){}
    }
  }
}
function boxBusyButtonMatches(button){
  const ref=boxState.busyButton;
  return ref&&ref.page===boxState.page&&Object.entries(ref.data).every(([key,value])=>button.dataset[key]===value);
}
function boxSyncBusyOverlay(root=boxRoot()){
  if(!root)return;root.classList.toggle('busy',false);root.classList.toggle('busy-image',false);
  for(const button of root.querySelectorAll('button[data-action]')){
    const active=boxState.busy&&boxBusyButtonMatches(button);
    if(active){
      if(!button.hasAttribute('data-xb-busy-disabled'))button.setAttribute('data-xb-busy-disabled',String(button.disabled));
      button.disabled=true;button.setAttribute('aria-busy','true');
      if(!button.querySelector('.xb-inline-spinner')){const spin=boxDoc.createElement('span');spin.className='xb-inline-spinner';spin.setAttribute('data-xb-task-spinner','');spin.setAttribute('aria-hidden','true');button.prepend(spin);}
    }else if(button.hasAttribute('data-xb-busy-disabled')){
      button.disabled=button.getAttribute('data-xb-busy-disabled')==='true';button.removeAttribute('data-xb-busy-disabled');button.removeAttribute('aria-busy');button.querySelector('[data-xb-task-spinner]')?.remove();
    }
  }
  let status=root.querySelector('.xb-task-progress');
  if(!boxState.busy){status?.remove();return;}
  if(!status){status=boxDoc.createElement('div');status.className='xb-task-progress';status.setAttribute('role','status');status.setAttribute('aria-live','polite');const spin=boxDoc.createElement('span');spin.className='xb-inline-spinner';spin.setAttribute('aria-hidden','true');const label=boxDoc.createElement('span');label.setAttribute('data-xb-task-label','');status.append(spin,label);root.querySelector('.xb-screen')?.prepend(status);}
  status.querySelector('[data-xb-task-label]').textContent=boxState.busyText||'处理中…';
}
function boxSetBusy(v,text='处理中…',kind=''){boxState.busy=!!v;boxState.busyText=boxText(text)||'处理中…';boxState.busyKind=boxText(kind);boxSyncBusyOverlay();if(typeof boxRender==='function')boxRender();}
async function boxSendConversation(root,api,kind,button){
  const id=kind==='dm'?boxState.chatId:boxState.roomId,draft=boxConversationDraft(kind,id),text=boxText(root.querySelector(`[data-field="${kind}-text"]`)?.value||draft.text);
  if(!text)return boxToast('先输入讯息','warning');
  const quoteId=draft.quoteId;draft.text=text;
  const options={quoteId,onSaved:()=>{draft.text='';draft.quoteId='';}};
  return boxDo(async()=>{
    if(kind==='dm')await api.sendDm(id,text,options);else await api.sendRoom(id,text,options);
    await api.markConversationRead?.(kind,id);
  },'回复已收到','正在等待回复…','network',button);
}
async function boxDo(fn,ok='完成',pending='处理中…',kind='',button=null){
  if(boxState.busy)return;
  boxState.busyButton=button?{page:boxState.page,data:{...button.dataset}}:null;
  boxSetBusy(true,pending,kind);
  try{await fn();boxToast(ok,'success');}catch(e){boxToast(e?.message||String(e),'error');}
  finally{boxState.busy=false;boxState.busyText='处理中…';boxState.busyKind='';boxSyncBusyOverlay();boxState.busyButton=null;await boxRender();}
}
function boxDoWithButton(button,fn,ok,pending,kind){return boxDo(fn,ok,pending,kind,button);}

function boxChooseAccountPortrait(button,api){
  if(boxState.busy)return;
  const ctx=xunSillyTavernContext(),id=button.dataset.accountId;
  const guard={expectedChat:ctx?.chat,expectedEpoch:xunMvuEpoch,expectedAvatar:ctx?.characters?.[ctx.characterId]?.avatar,expectedAccount:JSON.stringify(xunGetStore().accounts[id])};
  const input=boxDoc.createElement('input');input.type='file';input.accept='image/png,.png';
  input.onchange=()=>{const file=input.files?.[0];if(!file)return;
    void boxDoWithButton(button,async()=>{
      const src=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(new Error('无法读取图片，请重新选择。'));reader.onabort=()=>reject(new Error('读取图片已取消。'));reader.readAsDataURL(file);});
      await api.importAccountPortrait(id,src,guard);
    },'处理后立绘已导入并设为本卡共用','正在导入处理后立绘…','image');
  };input.click();
}

function boxGo(page){boxState.page=page; if(page!=='thread')boxState.postId=page==='feed'?'':boxState.postId; if(page!=='dm')boxState.chatId=page==='comms'?'':boxState.chatId; if(page!=='room')boxState.roomId=page==='comms'?'':boxState.roomId; boxResetScreenScroll(true); boxRender();}
function boxBack(){
  if(boxState.page==='dossier')return boxGo('accounts');
  if(boxState.page==='thread') return boxGo('feed'); if(boxState.page==='dm'||boxState.page==='room') return boxGo('comms'); if(boxState.page==='profile') return boxGo('feed'); if(boxState.page==='person') return boxGo('people'); return boxGo('home');
}

function boxEventMatch(event, selector){
  try{for(const node of event.composedPath?.()||[]){if(node&&typeof node.matches==='function'&&node.matches(selector))return node;}}catch(_){}
  const t=event.target;return t?.closest?.(selector)||null;
}

function boxCollectConfig(root){
  const patch={};
  root.querySelectorAll('[data-cfg]').forEach(el=>{const k=el.dataset.cfg;patch[k]=el.type==='number'?Number(el.value):el.value;});
  root.querySelectorAll('[data-cfg-bool]').forEach(el=>{patch[el.dataset.cfgBool]=!!el.checked;});
  const promptGroups={head:[],tail:[]};
  root.querySelectorAll('[data-prompt-entry]').forEach((row,index)=>{
    const position=row.dataset.promptPosition==='tail'?'tail':'head';
    promptGroups[position].push({
      id:boxText(row.dataset.promptEntry)||`${position}_${index+1}`,
      enabled:!!row.querySelector('[data-prompt-enabled]')?.checked,
      role:boxText(row.querySelector('[data-prompt-role]')?.value)||'system',
      content:String(row.querySelector('[data-prompt-content]')?.value||'')
    });
  });
  if(root.querySelector('[data-prompt-entry]')||(boxState.page==='settings'&&boxState.settingsTab==='prompt')){
    patch.customPromptHeadEntries=promptGroups.head;
    patch.customPromptTailEntries=promptGroups.tail;

    patch.customPromptHead='';
  }
  return patch;
}
