    const px=name=>Math.max(0,parseFloat(cs?.getPropertyValue(name))||0);
    return (boxSafeInsetsCache={left:px('--xb-safe-left'),right:px('--xb-safe-right'),top:px('--xb-safe-top'),bottom:px('--xb-safe-bottom')});
  }catch(_){return (boxSafeInsetsCache={left:0,right:0,top:0,bottom:0});}
}
function boxViewportBounds(){
  const vv=boxWin.visualViewport;
  const left=Number(vv?.offsetLeft)||0,top=Number(vv?.offsetTop)||0,width=Math.max(1,Number(vv?.width)||boxWin.innerWidth||1),height=Math.max(1,Number(vv?.height)||boxWin.innerHeight||1),safe=boxSafeInsets();
