function boxClampDevice(device,left,top){const r=device.getBoundingClientRect(),b=boxViewportBounds(),pad=8;return {left:Math.max(b.left+pad,Math.min(left,b.right-r.width-pad)),top:Math.max(b.top+pad,Math.min(top,b.bottom-r.height-pad))};}
