  const device=root.querySelector('.xb-device'), handles=[root.querySelector('.xb-status')].filter(Boolean); let drag=null, captureHandle=null;
  try{const saved=JSON.parse(boxWin.localStorage.getItem(SHIOMI_BOX_POS_KEY)||'null');if(saved&&Number.isFinite(saved.left)&&Number.isFinite(saved.top)){device.style.left=`${saved.left}px`;device.style.top=`${saved.top}px`;device.style.right='auto';device.style.bottom='auto';}}catch(_){}
  const down=(handle,e)=>{if(e.target.closest('button,input,textarea,select,a'))return;if(e.button!=null&&e.button!==0)return;const r=device.getBoundingClientRect();drag={id:e.pointerId,left:r.left,top:r.top,x:e.clientX,y:e.clientY};captureHandle=handle;try{handle.setPointerCapture(e.pointerId)}catch(_){}e.preventDefault();};
  const move=e=>{if(!drag||e.pointerId!==drag.id)return;const p=boxClampDevice(device,drag.left+e.clientX-drag.x,drag.top+e.clientY-drag.y);device.style.left=`${Math.round(p.left)}px`;device.style.top=`${Math.round(p.top)}px`;device.style.right='auto';device.style.bottom='auto';e.preventDefault();};
