function spParseJson(text) {
  let s = spText(text).replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');
  try { return JSON.parse(s); } catch (_) {}
  const start = s.indexOf('{');
  if (start < 0) throw new Error('模型没有返回JSON对象');
  let depth = 0, inString = false, esc = false;
  for (let i = start; i < s.length; i++) {
    const ch = s[i];
    if (inString) {
      if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') inString = false;
      continue;
    }
    if (ch === '"') { inString = true; continue; }
    if (ch === '{') depth++;
    else if (ch === '}') {
      depth--;
      if (depth === 0) return JSON.parse(s.slice(start, i + 1));
