function spValidatePayload(payload) {
  const p = spObj(payload), pm = spObj(p.police_matter), data = spObj(pm.data);
  const name = spText(pm.name);
  if (!name) throw new Error('缺少 police_matter.name');
  if (!Object.keys(data).length) throw new Error('缺少 police_matter.data');
  const base = spObj(data.基础), current = spObj(data.当前案情), back = spObj(data.后台);
  if (!spText(base.性质) || !spText(base.状态)) throw new Error('基础信息不完整');
  if (!spText(current.事件)) throw new Error('当前案情.事件为空');
  if (spText(base.案件来源) !== '自动生成') throw new Error('自动建档事项必须标记案件来源=自动生成');
  if (spText(base.阶段) !== '初动') throw new Error('自动建档事项初始阶段必须为初动');
  const clues = spObj(current.调查线索), clueNames = Object.keys(clues);
  if (clueNames.length < 1 || clueNames.length > 4) throw new Error('自动案件调查线索必须固定为1~4条');
  for (const clueName of clueNames) {
    const clue = spObj(clues[clueName]);
    if (!spText(clueName) || /^线索\s*\d+$/i.test(spText(clueName))) throw new Error('调查线索必须使用有语义的名称');
    if (!spText(clue.问题) || !spNonEmptyArray(clue.依据)) throw new Error(`调查线索“${clueName}”缺少问题或当前依据`);
    if (spText(clue.状态) !== '未调查') throw new Error(`调查线索“${clueName}”初始状态必须为未调查`);
    if (!Array.isArray(clue.调查结果) || clue.调查结果.length) throw new Error(`调查线索“${clueName}”初始调查结果必须为空数组`);
  }
  if (Object.keys(spObj(current.正式结论)).length) throw new Error('正式结论初始必须为空对象');

  const truth = spObj(back.真实情况);
  if (!spText(truth.概要) || !spNonEmptyArray(truth.因果链)) throw new Error('真实情况缺少完整因果');

  const facts = spObj(back.客观事实), traces = spObj(back.客观痕迹), cognition = spObj(back.人物认知);
  const factSet = new Set(Object.keys(facts));
  const traceSet = new Set(Object.keys(traces));
  const personSet = new Set(Object.keys(cognition));

  const clueMap = spObj(back.线索对应), mappedNames = Object.keys(clueMap);
  if (mappedNames.length !== clueNames.length || clueNames.some(name => !Object.prototype.hasOwnProperty.call(clueMap, name))) {
    throw new Error('后台.线索对应必须与当前案情.调查线索一一同名');
  }
  const mappedFactSet = new Set(), mappedTraceSet = new Set();
  for (const clueName of clueNames) {
    const link = spObj(clueMap[clueName]);
    const factRefs = spArr(link.客观事实).map(spText).filter(Boolean);
    const traceRefs = spArr(link.客观痕迹).map(spText).filter(Boolean);
    const personRefs = spArr(link.人物认知).map(spText).filter(Boolean);
    if (!(factRefs.length || traceRefs.length)) throw new Error(`线索对应“${clueName}”至少需要一项客观事实或客观痕迹，不能只靠人物认知`);
    if (factRefs.some(x => !factSet.has(x))) throw new Error(`线索对应“${clueName}”引用了不存在的客观事实`);
    if (traceRefs.some(x => !traceSet.has(x))) throw new Error(`线索对应“${clueName}”引用了不存在的客观痕迹`);
    if (personRefs.some(x => !personSet.has(x))) throw new Error(`线索对应“${clueName}”引用了不存在的人物认知`);
    factRefs.forEach(x => mappedFactSet.add(x));
    traceRefs.forEach(x => mappedTraceSet.add(x));
  }
  for (const factName of factSet) {
    if (!mappedFactSet.has(factName)) throw new Error(`客观事实“${factName}”没有接入任何固定调查方向`);
  }
  for (const traceName of traceSet) {
    if (!mappedTraceSet.has(traceName)) throw new Error(`客观痕迹“${traceName}”没有接入任何固定调查方向`);
  }


  const boundary = spObj(back.结论边界);
  if (!Object.keys(boundary).length) throw new Error('缺少后台.结论边界');
  const coreQuestions = spArr(boundary.核心问题).map(spText).filter(Boolean);
  if (!coreQuestions.length) throw new Error('结论边界.核心问题为空');
  if (coreQuestions.length > 3) throw new Error('自动案件结论边界最多保留3个核心问题，请缩小事项复杂度');
  const proofs = spObj(boundary.关键证明), proofNames = Object.keys(proofs);
  if (!proofNames.length) throw new Error('结论边界.关键证明为空');
  if (proofNames.length > 4) throw new Error('自动案件关键证明最多保留4项，请合并近义证明或缩小事项');
  for (const [topic, raw] of Object.entries(proofs)) {
    const row = spObj(raw);
    const factRefs = spArr(row.客观事实).map(spText).filter(Boolean);
    const traceRefs = spArr(row.客观痕迹).map(spText).filter(Boolean);
    if (!spText(topic) || !spText(row.结论)) throw new Error('结论边界存在无名称或无结论的关键证明');
    if (!(factRefs.length || traceRefs.length)) throw new Error(`关键证明“${topic}”没有现实证明节点`);
    if (factRefs.some(x => !factSet.has(x))) throw new Error(`关键证明“${topic}”引用了不存在的客观事实`);
    if (traceRefs.some(x => !traceSet.has(x))) throw new Error(`关键证明“${topic}”引用了不存在的客观痕迹`);
    if (factRefs.some(x => !mappedFactSet.has(x)) || traceRefs.some(x => !mappedTraceSet.has(x))) {
      throw new Error(`关键证明“${topic}”引用了没有调查入口的事实或痕迹`);
    }
  }

  for (const [factName, raw] of Object.entries(facts)) {
    const row = spObj(raw);
    if (!spText(row.内容) || !spText(row.来源基础)) throw new Error(`客观事实“${factName}”缺少内容或来源基础`);
  }
  const allowedTraceGates = new Set(['直接可见','针对检查','程序结果']);
  const factsWithTraceSupport = new Set();
  for (const [traceName, raw] of Object.entries(traces)) {
    const row = spObj(raw);
    const supportRefs = spArr(row.支持事实).map(spText).filter(Boolean);
    const gate = spText(row.接触门槛);
    if (!spText(row.内容) || !spText(row.形成原因) || !spText(row.当前所在) || !spNonEmptyArray(row.取得条件) || !supportRefs.length) {
      throw new Error(`客观痕迹“${traceName}”缺少形成、取得或证明信息`);
    }
    if (!allowedTraceGates.has(gate)) throw new Error(`客观痕迹“${traceName}”的接触门槛必须是直接可见/针对检查/程序结果之一`);
    if (supportRefs.some(x => !factSet.has(x))) throw new Error(`客观痕迹“${traceName}”引用了不存在的支持事实`);
    supportRefs.forEach(x => factsWithTraceSupport.add(x));
  }
  for (const [topic, raw] of Object.entries(proofs)) {
    const factRefs = spArr(spObj(raw).客观事实).map(spText).filter(Boolean);
    if (factRefs.some(x => !factsWithTraceSupport.has(x))) {
      throw new Error(`关键证明“${topic}”引用了没有任何现实痕迹载体直接支持的客观事实`);
    }
  }

  for (const [personName, raw] of Object.entries(cognition)) {
    const row = spObj(raw);
    if (!spText(personName) || !spText(row.事件位置)) throw new Error(`人物认知“${personName}”缺少事件位置`);
    for (const key of ['亲历事实','已知事实','误解','隐瞒事实','当前顾虑']) {
      if (!Array.isArray(row[key])) throw new Error(`人物认知“${personName}.${key}”必须为数组`);
    }
  }

  const profiles = spObj(p.new_profiles);
  for (const [person, profileRaw] of Object.entries(profiles)) {
    const profile = spObj(profileRaw);
    if (!person || profile.年龄 == null || !spText(profile.性别) || !spText(spObj(profile.身份).职业) || !spText(profile.外貌) || !spText(profile.生活与关系)) {
