async function spWriteMatter(messageId, anchor, parsed, request, key, priorInfo = null) {
  if (!spAnchorAlive(anchor)) throw new Error('当前回复已经发生变化');
  const rows = spChatRows();
  if (Number(messageId) !== rows.length - 1) throw new Error('当前对话已经继续，请在新的当前分支建立事项');

  const requests = spParseRequests(spRowBody(rows[messageId]));
  const before = priorInfo || await spReadPriorMvu(messageId);
  let sourceData = await spReadMvu(messageId);
  const guarded = await spGuardPoliceRegistry(messageId, anchor, requests, sourceData, before);
  sourceData = guarded.data;
  const next = spClone(sourceData) || {}, stat = next.stat_data ? next.stat_data : next;
  stat.警务事项 = spObj(stat.警务事项);

  const priorStat = before.available ? spStat(before.data) : null;
  const priorMatched = priorStat ? spFindExistingMatter(priorStat, request, parsed.name) : null;
  if (priorMatched) {
    if (!Object.prototype.hasOwnProperty.call(stat.警务事项, priorMatched.name)) {
      stat.警务事项[priorMatched.name] = spClone(priorMatched.raw);
      const api = await spMvu();
      if (typeof api.replaceMvuData !== 'function') throw new Error('MVU写入接口不可用');
      await api.replaceMvuData(next, { type:'message', message_id:messageId });
    }
    return { name:priorMatched.name, created:false, reason:priorMatched.reason || '本轮之前已经存在' };
  }

  if (!before.available) {
    const fallbackMatched = spFindExistingMatter(stat, request, parsed.name);
    if (fallbackMatched) return { name:fallbackMatched.name, created:false, reason:fallbackMatched.reason || '已有事项匹配' };
  }
  if (Object.prototype.hasOwnProperty.call(stat.警务事项, parsed.name)) {
    throw new Error('模型生成的事项名称与已有不同事项重名，请重试');
  }

  stat.人物档案 = spObj(stat.人物档案);
  const fixed = await spFixedCharacterNames();
  for (const [name, profile] of Object.entries(parsed.profiles)) {
    if (fixed.has(name) || Object.prototype.hasOwnProperty.call(stat.人物档案, name)) continue;
    stat.人物档案[name] = spClone(profile);
  }
  stat.警务事项[parsed.name] = spClone(parsed.data);

  await spSetMeta(key, { status:'committing', anchor, request, matterName:parsed.name, matchReason:'警务脚本正在写入', error:'' });
  spRenderCards();
  const api = await spMvu();
  if (typeof api.replaceMvuData !== 'function') throw new Error('MVU写入接口不可用');
  await api.replaceMvuData(next, { type:'message', message_id:messageId });
  return { name:parsed.name, created:true, reason:'警务脚本新建事项' };
}

async function spBuildFromCard(card) {
  const key = card?.dataset?.sourceKey, messageId = Number(card?.dataset?.messageId), index = Number(card?.dataset?.requestIndex);
  if (!key || !Number.isInteger(messageId) || !Number.isInteger(index)) return;
  const rows = spChatRows(), row = rows[messageId];
  if (!row) return;
  const anchor = spAnchor(row, messageId), requests = spParseRequests(spRowBody(row));
  const request = requests[index];
  if (!request || spSourceKey(anchor, index, request) !== key) return;
  if (messageId !== rows.length - 1) { await spSetMeta(key,{status:'stale',anchor,request}); spRenderCards(); return; }

  const existingMeta = spObj(spMeta()[key]);
  if (existingMeta.status === 'building' || existingMeta.status === 'checking') return;
  await spSetMeta(key, { status:'checking', anchor, request, error:'' }); spRenderCards();

  try {
    const priorInfo = await spReadPriorMvu(messageId);
    let sourceMvu = await spReadMvu(messageId);
    const guarded = await spGuardPoliceRegistry(messageId, anchor, requests, sourceMvu, priorInfo);
    sourceMvu = guarded.data;
    const stat = spStat(sourceMvu), priorStat = priorInfo.available ? spStat(priorInfo.data) : null;
    if (!spAnchorAlive(anchor)) throw new Error('当前回复已经发生变化');

    const metaMatterName = spText(existingMeta.matterName);
    if (existingMeta.status === 'ready' && metaMatterName &&
        Object.prototype.hasOwnProperty.call(spObj(stat.警务事项), metaMatterName)) {
      await spSetMeta(key, { status:'ready', anchor, request, matterName:metaMatterName, error:'' });
      spRenderCards();
      return;
    }

    const existingMatch = priorStat
      ? spFindExistingMatter(priorStat, request, metaMatterName)
      : spFindExistingMatter(stat, request, metaMatterName);
    if (existingMatch) {
      await spSetMeta(key, { status:'linked', anchor, request, matterName:existingMatch.name, matchReason:`本轮之前已存在 · ${existingMatch.reason || '事项匹配'}`, error:'' });
      try { if (typeof toastr !== 'undefined' && toastr?.info) toastr.info(`已有警务事项：${existingMatch.name}`); } catch (_) {}
      spRenderCards();
      return;
    }

    await spSetMeta(key, { status:'building', anchor, request, matterName:'', matchReason:'', error:'' }); spRenderCards();
    const trigger = spStripNarrative(spRowBody(row)), recent = spRecentContext(messageId, 8);
    const corpus = [request.subject, request.nature, request.source, trigger, recent, JSON.stringify(spGeneratorState(stat))].join('\n');
    const [prompt, world] = await Promise.all([spGeneratorPrompt(), spRelevantWorldContext(corpus)]);
    if (!spAnchorAlive(anchor)) throw new Error('当前回复已经发生变化');
    const userInput = spGenerationInput({ request, trigger, recent, stat, world });
    if (typeof generateRaw !== 'function') throw new Error('当前酒馆助手没有提供 generateRaw，请更新酒馆助手后重试');
    const checked = await spGenerateCheckedPayload(prompt, userInput, anchor);
    const writeResult = await spWriteMatter(messageId, anchor, checked, request, key, priorInfo);
    const status = writeResult.created ? 'ready' : 'linked';
    await spSetMeta(key, { status, anchor, request, matterName:writeResult.name, matchReason:writeResult.reason, createdBy:writeResult.created ? 'police-agent' : '', error:'' });
    try {
      if (typeof toastr !== 'undefined') {
        if (writeResult.created && toastr?.success) toastr.success(`警务事项已建立：${writeResult.name}`);
        else if (!writeResult.created && toastr?.info) toastr.info(`已关联已有警务事项：${writeResult.name}`);
      }
    } catch (_) {}
  } catch (err) {
    await spSetMeta(key, { status:'error', anchor, request, error:spText(err?.message || err).slice(0,240) });
    try { if (typeof toastr !== 'undefined' && toastr?.error) toastr.error(`警务事项整理失败：${spText(err?.message || err).slice(0,160)}`); } catch (_) {}
    console.warn('[ShiomiPolice] 建立警务事项失败', err);
  }
  spRenderCards();
}


let spReconcileBusy = false;
async function spReconcileLatestRequest() {
  if (spReconcileBusy) return;
  const rows = spChatRows(), messageId = rows.length - 1, row = rows[messageId];
  if (!row || row.is_user || row.is_system) return;
  const requests = spParseRequests(spRowBody(row));
  spReconcileBusy = true;
  try {
    const anchor = spAnchor(row, messageId), priorInfo = await spReadPriorMvu(messageId);
    let sourceMvu = await spReadMvu(messageId);
    const guarded = await spGuardPoliceRegistry(messageId, anchor, requests, sourceMvu, priorInfo);
    sourceMvu = guarded.data;
    const stat = spStat(sourceMvu), priorStat = priorInfo.available ? spStat(priorInfo.data) : null;
    if (!spAnchorAlive(anchor)) return;
    if (!requests.length) return;

    const all = spMeta(); let changed = false;
    requests.forEach((request, index) => {
      const key = spSourceKey(anchor, index, request), prev = spObj(all[key]);
      if (prev.status === 'building' || prev.status === 'checking' || prev.status === 'committing') return;
      const named = spText(prev.matterName);

      if (prev.status === 'ready' && named && Object.prototype.hasOwnProperty.call(spObj(stat.警务事项), named)) return;

      const matched = priorStat
        ? spFindExistingMatter(priorStat, request, named)
        : spFindExistingMatter(stat, request, named);
      if (matched) {
        all[key] = { ...prev, status:'linked', anchor, request, matterName:matched.name, matchReason:`本轮之前已存在 · ${matched.reason || '事项匹配'}`, error:'', updatedAt:spNow() };
        changed = true;
      } else if (prev.status === 'linked' || (prev.status === 'ready' && named)) {
        all[key] = { ...prev, status:'pending', anchor, request, matterName:'', matchReason:'', createdBy:'', error:'', updatedAt:spNow() };
        changed = true;
      }
    });
    if (changed) await spSaveMeta(all);
  } catch (err) {
    console.warn('[ShiomiPolice] 自动核对警务事项失败', err);
  } finally {
    spReconcileBusy = false;
    spRenderCards();
  }
}

