  background:linear-gradient(90deg,rgba(4,8,11,.28) 0%,transparent 13%,transparent 72%,rgba(4,8,11,.18) 100%),linear-gradient(180deg,rgba(4,8,11,.20) 0%,transparent 16%,transparent 73%,rgba(4,8,11,.32) 100%);
  mix-blend-mode:multiply;opacity:1
}
.map-tint{background:radial-gradient(circle at 50% 44%,transparent 48%,rgba(8,13,16,.13) 100%),linear-gradient(115deg,rgba(255,248,232,.035),transparent 42%,rgba(4,9,12,.08));}
