  class SafeVnInteractionLayer {
    constructor() {
      this.host = null;
      this.root = null;
      this.shell = null;
      this.panel = null;
      this.rail = null;
      this.handle = null;
      this.filter = 'all';
      this.dragStartY = null;
      this.cleanup = [];
      this.mounted = false;
      this.destroyed = false;
      this.mountTimer = 0;
    }
    listen(target,type,handler,options) {
      if (!target?.addEventListener) return;
      target.addEventListener(type,handler,options);
      this.cleanup.push(() => { try { target.removeEventListener(type,handler,options); } catch (_) {} });
    }
    findUi() {
      this.host = hostDoc.getElementById('shiomi-map-host');
      this.root = this.host?.shadowRoot || this.host || null;
      this.shell = this.root?.querySelector?.('.shiomi-map-shell') || null;
      this.panel = this.root?.querySelector?.('.shiomi-map-panel') || null;
      return !!(this.root && this.shell && this.panel);
    }
    syncSeason() {
      try { if (this.shell) this.shell.dataset.season = getSeasonKey(); } catch (_) {}
    }
    installRail() {
      if (!this.root) return;
      const existing = this.root.querySelector('.shiomi-map-guide-rail');
      if (existing) { this.rail = existing; return; }
      const rail = hostDoc.createElement('nav');
      rail.className = 'shiomi-map-guide-rail';
      rail.setAttribute('aria-label','地点类别导览');
      const defs = [
        ['all','全部'],['transit','交通'],['civic','公共'],['education','教育'],['life','生活'],['culture','文化'],['industry','港湾'],['case','案件']
      ];
      defs.forEach(([key,label]) => {
        const button = hostDoc.createElement('button');
        button.type = 'button';
        button.className = `shiomi-map-guide${key === 'all' ? ' active' : ''}`;
        button.dataset.filter = key;
        button.textContent = label;
        this.listen(button,'click',() => this.applyFilter(key));
        rail.appendChild(button);
      });
      const hint = hostDoc.createElement('span');
      hint.className = 'shiomi-map-guide-hint';
      hint.textContent = '一次选中 · 再次聚焦';
      rail.appendChild(hint);
      this.root.appendChild(rail);
      this.rail = rail;
    }
    filterFamilies(key) {
      if (key === 'life') return ['commerce','hospitality','residence','leisure'];
      if (key === 'culture') return ['culture','nature'];
      return [key];
    }
    applyFilter(key = this.filter) {
      try {
        if (!this.root) return;
        this.filter = key || 'all';
        this.rail?.querySelectorAll('.shiomi-map-guide').forEach(button =>
          button.classList.toggle('active',button.dataset.filter === this.filter));
        const families = this.filterFamilies(this.filter);
        const mapApi = hostWin.ShiomiMap || localWin.ShiomiMap;
        if (this.filter === 'case') { try { mapApi?.setLayers?.({cases:true}); } catch (_) {} }
        else if (this.filter !== 'all') { try { mapApi?.setLayers?.({locations:true}); } catch (_) {} }
        this.root.querySelectorAll('.pin.svg-marker[data-id]').forEach(pin => {
          let show = true;
          if (!pin.classList.contains('selected')) {
            if (this.filter === 'case') show = pin.classList.contains('case') || pin.classList.contains('marker-family-case');
            else if (this.filter !== 'all') show = families.some(f => pin.classList.contains(`marker-family-${f}`));
          }
          pin.classList.toggle('shiomi-filter-hidden',!show);
          const id = pin.dataset.id;
          if (!id) return;
          this.root.querySelectorAll('.map-label[data-id]').forEach(label => {
            if (label.dataset.id === id) label.classList.toggle('shiomi-filter-hidden',!show);
          });
        });
      } catch (error) {
        console.warn(LOG,'地点类别筛选已降级，不影响基础地图。',error);
      }
    }
    installHandle() {
      if (!this.panel) return;
      const existing = this.panel.querySelector('.shiomi-panel-handle');
      if (existing) { this.handle = existing; return; }
      const handle = hostDoc.createElement('button');
      handle.type = 'button';
      handle.className = 'shiomi-panel-handle';
      handle.setAttribute('aria-label','展开或收起地点资料');
      handle.setAttribute('aria-expanded','false');
      this.panel.prepend(handle);
      this.handle = handle;
      this.listen(handle,'click',() => {
        if (!this.panel?.classList.contains('open')) return;
        const expanded = this.panel.classList.toggle('expanded');
        handle.setAttribute('aria-expanded',String(expanded));
      });
      this.listen(handle,'pointerdown',event => {
        this.dragStartY = Number(event.clientY);
        try { handle.setPointerCapture?.(event.pointerId); } catch (_) {}
      });
      this.listen(handle,'pointerup',event => {
        if (this.dragStartY == null || !this.panel) return;
        const delta = Number(event.clientY) - this.dragStartY;
        this.dragStartY = null;
        if (delta > 58) {
          this.panel.classList.remove('expanded');
          handle.setAttribute('aria-expanded','false');
          this.panel.querySelector('[data-action="panel-close"]')?.click();
        } else if (delta < -48) {
          this.panel.classList.add('expanded');
          handle.setAttribute('aria-expanded','true');
        }
      });
      this.listen(this.root,'click',event => {
        const action = event.target?.closest?.('[data-action]')?.dataset?.action;
        if (action === 'panel-close') {
          this.panel?.classList.remove('expanded');
          this.handle?.setAttribute('aria-expanded','false');
        }
      },true);
    }
    mount() {
      if (this.destroyed || this.mounted) return this.mounted;
      try {
        if (!this.findUi()) return false;
        this.syncSeason();
        this.installRail();
        this.installHandle();
        this.applyFilter(this.filter);
        this.mounted = true;
        return true;
      } catch (error) {
        console.warn(LOG,'VN 地图交互层挂载失败，已自动降级为基础地图。',error);
        return false;
      }
    }
    mountAfterOpen() {
      if (this.destroyed || this.mounted) return;
      const delays = [0,60,160,360,700,1200];
      let index = 0;
      const attempt = () => {
        if (this.destroyed || this.mounted) return;
        if (this.mount()) return;
        index += 1;
        if (index < delays.length) this.mountTimer = hostWin.setTimeout(attempt,delays[index]);
      };
      this.mountTimer = hostWin.setTimeout(attempt,delays[index]);
    }
    onOpen() {
      if (this.destroyed) return;
      if (this.mounted) {
        this.findUi();
        this.syncSeason();
        this.applyFilter(this.filter);
        return;
      }
      this.mountAfterOpen();
    }
    destroy() {
      if (this.destroyed) return;
      this.destroyed = true;
      if (this.mountTimer) try { hostWin.clearTimeout(this.mountTimer); } catch (_) {}
      this.cleanup.splice(0).forEach(fn => { try { fn(); } catch (_) {} });
      try { this.rail?.remove(); } catch (_) {}
      try { this.handle?.remove(); } catch (_) {}
      this.host = this.root = this.shell = this.panel = this.rail = this.handle = null;
      this.mounted = false;
    }
  }

  const vnInteraction = new SafeVnInteractionLayer();
  hostWin.__SHIOMI_MAP_VN_UI__ = vnInteraction;
  if (localWin !== hostWin) localWin.__SHIOMI_MAP_VN_UI__ = vnInteraction;

  class SceneCarousel {
    constructor() {
      this.host = null;
      this.root = null;
      this.panel = null;
      this.content = null;
      this.contentObserver = null;
      this.panelObserver = null;
      this.hostObserver = null;
      this.style = null;
      this.section = null;
      this.currentKey = '';
      this.currentIndex = 0;
      this.currentRecord = null;
      this.currentImg = null;
      this.spinner = null;
      this.captionZh = null;
      this.captionJa = null;
      this.dots = null;
      this.touchStartX = null;
      this.destroyed = false;
      this.renderQueued = false;
    }

    findUi() {
      this.host = hostDoc.getElementById('shiomi-map-host');
      this.root = this.host?.shadowRoot || this.host || null;
      this.panel = this.root?.querySelector?.('.shiomi-map-panel') || null;
      this.content = this.root?.querySelector?.('.shiomi-map-panel-content') || null;
      return !!(this.host && this.root && this.panel && this.content);
    }

    installStyle() {
      if (!this.root) return;
      this.root.querySelector('#shiomi-scene-carousel-style')?.remove();
      const el = hostDoc.createElement('style');
      el.id = 'shiomi-scene-carousel-style';
      el.textContent = `
        .shiomi-scene-carousel{margin:14px 0 0;padding:13px 0 0;border-top:1px solid rgba(255,255,255,.09)}
        .shiomi-scene-carousel-head{display:flex;align-items:center;gap:8px;margin:0 0 8px;color:rgba(247,241,231,.82)}
        .shiomi-scene-carousel-head::before{content:"";width:18px;height:1px;background:var(--vn-accent)}
        .shiomi-scene-carousel-head strong{font:500 11px/1.2 "Songti SC","STSong","Noto Serif CJK SC",serif;letter-spacing:.08em}
        .shiomi-scene-carousel-head small{color:var(--vn-accent);font:700 7px/1.2 ui-monospace,"SFMono-Regular",monospace;letter-spacing:.16em}
        .shiomi-scene-carousel-media{position:relative;width:100%;aspect-ratio:16/9;overflow:hidden;border:1px solid rgba(255,255,255,.13);background:rgba(0,0,0,.22);box-shadow:0 9px 26px rgba(0,0,0,.18);touch-action:pan-y;user-select:none;-webkit-user-select:none}
        .shiomi-scene-carousel-media::after{content:"";position:absolute;inset:0;border:1px solid rgba(255,255,255,.04);box-shadow:inset 0 -50px 70px rgba(0,0,0,.17);pointer-events:none;z-index:3}
        .shiomi-scene-carousel-media img{display:block;width:100%;height:100%;object-fit:cover;background:#161b1d;opacity:0;transition:opacity .18s;filter:saturate(.88) contrast(.97) brightness(.92)}
        .shiomi-scene-carousel-media img.ready{opacity:1}
        .shiomi-scene-carousel-spinner{position:absolute;left:50%;top:50%;width:22px;height:22px;margin:-11px 0 0 -11px;border:1px solid rgba(255,255,255,.16);border-top-color:var(--vn-accent);border-radius:50%;animation:shiomiSceneSpin .72s linear infinite;z-index:2}
        .shiomi-scene-carousel-spinner[hidden]{display:none}@keyframes shiomiSceneSpin{to{transform:rotate(360deg)}}
        .shiomi-scene-carousel-error{position:absolute;inset:0;display:none;place-items:center;padding:18px;text-align:center;color:rgba(247,241,231,.42);font:500 9px/1.6 "Noto Sans CJK SC",sans-serif}.shiomi-scene-carousel-error.show{display:grid}
        .shiomi-scene-carousel-caption{display:grid;grid-template-columns:1fr auto;gap:4px 10px;padding:7px 0 0;color:rgba(247,241,231,.68)}
        .shiomi-scene-carousel-caption span{display:block;font:500 10.5px/1.4 "Songti SC","STSong","Noto Serif CJK SC",serif;letter-spacing:.035em}.shiomi-scene-carousel-caption small{display:block;color:rgba(247,241,231,.35);font:500 8.5px/1.4 "Noto Sans CJK JP","Yu Gothic",sans-serif;text-align:right}
        .shiomi-scene-carousel-dots{display:flex;align-items:center;justify-content:flex-start;gap:4px;padding:7px 0 0}.shiomi-scene-carousel-dot{width:16px;height:2px;border:0;padding:0;background:rgba(255,255,255,.16);cursor:pointer;transition:width .14s,background .14s}.shiomi-scene-carousel-dot.active{width:28px;background:var(--vn-accent)}.shiomi-scene-carousel-dot:focus-visible{outline:1px solid var(--vn-accent);outline-offset:4px}
        @media(max-width:900px){.shiomi-scene-carousel-caption{grid-template-columns:1fr}.shiomi-scene-carousel-caption small{text-align:left}}
        @media(prefers-reduced-motion:reduce){.shiomi-scene-carousel-media img,.shiomi-scene-carousel-dot{transition:none}.shiomi-scene-carousel-spinner{animation:none}}
      `;
      this.root.appendChild(el);
      this.style = el;
    }

    cleanupSection() {
      this.section?.remove();
      this.section = null;
      this.currentKey = '';
      this.currentRecord = null;
      this.currentImg = null;
      this.spinner = null;
      this.captionZh = null;
      this.captionJa = null;
      this.dots = null;
      this.touchStartX = null;
    }

    schedule() {
      if (this.destroyed || this.renderQueued) return;
      this.renderQueued = true;
      queueMicrotask(() => {
        this.renderQueued = false;
        this.render();
      });
    }

    updateDots() {
      if (!this.dots) return;
      [...this.dots.children].forEach((dot,index) => {
        dot.classList.toggle('active', index === this.currentIndex);
        dot.setAttribute('aria-current', index === this.currentIndex ? 'true' : 'false');
      });
    }

    showIndex(index) {
      const record = this.currentRecord;
      if (!record?.gallery?.length || !this.currentImg) return;
      const total = record.gallery.length;
      this.currentIndex = ((index % total) + total) % total;
      const item = record.gallery[this.currentIndex];
      const error = this.section?.querySelector('.shiomi-scene-carousel-error');

      this.currentImg.classList.remove('ready');
      this.currentImg.removeAttribute('src');
      this.currentImg.dataset.retry = '0';
      this.currentImg.dataset.fallback = item.fallback;
      this.currentImg.alt = `${record.nameZh} · ${item.labelZh}`;
      if (error) error.classList.remove('show');
      if (this.spinner) this.spinner.hidden = false;
      if (this.captionZh) this.captionZh.textContent = item.labelZh;
      if (this.captionJa) this.captionJa.textContent = item.labelJa;
      this.updateDots();

      const img = this.currentImg;
      img.onload = () => {
        if (img !== this.currentImg) return;
        img.classList.add('ready');
        if (this.spinner) this.spinner.hidden = true;
      };
      img.onerror = () => {
        if (img !== this.currentImg) return;
        if (img.dataset.retry === '0' && img.dataset.fallback) {
          img.dataset.retry = '1';
          img.src = img.dataset.fallback;
          return;
        }
        if (this.spinner) this.spinner.hidden = true;
        if (error) error.classList.add('show');
      };
      img.src = item.url;
    }

    render() {
      if (this.destroyed || !this.content || !this.panel?.classList.contains('open')) {
        this.cleanupSection();
        return;
      }

      const title = text(this.content.querySelector('h2')?.textContent);
      const record = directIndex.get(norm(title));
      if (!record) {
        this.cleanupSection();
        return;
      }

      const key = `${record.kind}:${record.id}`;
      if (this.section?.isConnected && this.currentKey === key) return;

      this.cleanupSection();
      this.currentKey = key;
      this.currentRecord = record;
      this.currentIndex = 0;

      const section = hostDoc.createElement('section');
      section.className = 'shiomi-scene-carousel';

      const head = hostDoc.createElement('div');
      head.className = 'shiomi-scene-carousel-head';
      const zh = hostDoc.createElement('strong'); zh.textContent = '场景图';
      const en = hostDoc.createElement('small'); en.textContent = 'SCENE CG';
      head.append(zh,en);

      const media = hostDoc.createElement('div');
      media.className = 'shiomi-scene-carousel-media';

      const img = hostDoc.createElement('img');
      img.decoding = 'async';
      try { img.fetchPriority = 'high'; } catch (_) {}

      const spinner = hostDoc.createElement('div');
      spinner.className = 'shiomi-scene-carousel-spinner';
      spinner.setAttribute('aria-label','图片加载中');

      const error = hostDoc.createElement('div');
      error.className = 'shiomi-scene-carousel-error';
      error.textContent = '图片暂时无法载入 / 画像を読み込めませんでした';

      media.append(img,spinner,error);

      const caption = hostDoc.createElement('div');
      caption.className = 'shiomi-scene-carousel-caption';
      const czh = hostDoc.createElement('span');
      const cja = hostDoc.createElement('small');
      caption.append(czh,cja);

      const dots = hostDoc.createElement('div');
      dots.className = 'shiomi-scene-carousel-dots';
      record.gallery.forEach((_,index) => {
        const dot = hostDoc.createElement('button');
        dot.type = 'button';
        dot.className = 'shiomi-scene-carousel-dot';
        dot.setAttribute('aria-label',`查看第 ${index + 1} 张场景图`);
        dot.addEventListener('click',() => this.showIndex(index));
        dots.appendChild(dot);
      });


      media.addEventListener('touchstart', event => {
        const touch = event.touches?.[0];
        this.touchStartX = touch ? touch.clientX : null;
      }, {passive:true});
      media.addEventListener('touchend', event => {
        if (this.touchStartX == null) return;
        const touch = event.changedTouches?.[0];
        if (!touch) return;
        const delta = touch.clientX - this.touchStartX;
        this.touchStartX = null;
        if (Math.abs(delta) < 38 || record.gallery.length < 2) return;
        this.showIndex(this.currentIndex + (delta < 0 ? 1 : -1));
      }, {passive:true});

      section.append(head,media,caption);
      if (record.gallery.length > 1) section.appendChild(dots);

      const actions = this.content.querySelector('.shiomi-map-actions');
      if (actions) this.content.insertBefore(section, actions);
      else this.content.appendChild(section);

      this.section = section;
      this.currentImg = img;
      this.spinner = spinner;
      this.captionZh = czh;
      this.captionJa = cja;
      this.dots = dots;
      this.showIndex(0);
    }

    attach() {
      if (this.destroyed || !this.findUi()) return false;
      this.installStyle();

      this.contentObserver = new hostWin.MutationObserver(() => this.schedule());
      this.contentObserver.observe(this.content,{childList:true,subtree:false});

      this.panelObserver = new hostWin.MutationObserver(() => {
        if (!this.panel?.classList.contains('open')) this.cleanupSection();
        else this.schedule();
      });
      this.panelObserver.observe(this.panel,{attributes:true,attributeFilter:['class','aria-hidden']});

      this.schedule();
      console.info(LOG, '当前地点场景轮播已挂载。');
      return true;
    }

    start() {
      if (this.attach()) return this;
      this.hostObserver = new hostWin.MutationObserver(() => {
        if (this.attach()) {
          try { this.hostObserver?.disconnect(); } catch (_) {}
          this.hostObserver = null;
        }
      });
      this.hostObserver.observe(hostDoc.documentElement || hostDoc,{childList:true,subtree:true});
      return this;
    }

    destroy() {
      if (this.destroyed) return;
      this.destroyed = true;
      try { this.contentObserver?.disconnect(); } catch (_) {}
      try { this.panelObserver?.disconnect(); } catch (_) {}
      try { this.hostObserver?.disconnect(); } catch (_) {}
      this.contentObserver = this.panelObserver = this.hostObserver = null;
      this.cleanupSection();
      this.style?.remove();
      this.style = null;
      if (hostWin.__SHIOMI_SCENE_CAROUSEL__ === this) try { delete hostWin.__SHIOMI_SCENE_CAROUSEL__; } catch (_) {}
