(async () => {
  'use strict';

  const VERSION = '0.6.3';
  const ENTRY_TITLE = '【映像卷】角色CG注册表';
  const BASE_KEY = 'shiomi_cg_album_v2';
  const ROOT_ID = 'shiomi-character-album-host';
  const LOG = '[ShiomiCharacterAlbum]';

  const CHARACTER_ORDER = ['mizuki_mio','fujisaki_ayano','hoshino_miyu','mochizuki_chizuru','mikage_shiraha'];
  const CHARACTER_ROMAJI = {
    mizuki_mio:'MIZUKI MIO', fujisaki_ayano:'FUJISAKI AYANO', hoshino_miyu:'HOSHINO MIYU',
    mochizuki_chizuru:'MOCHIZUKI CHIZURU', mikage_shiraha:'MIKAGE SHIRAHA'
  };
  const CHARACTER_KEY_ART = {"mizuki_mio":"https://cdn.jsdelivr.net/gh/dongyue233/shiomi@main/card-assets/v1.33.27/media-002.webp","fujisaki_ayano":"https://cdn.jsdelivr.net/gh/dongyue233/shiomi@main/card-assets/v1.33.27/media-003.webp","hoshino_miyu":"https://cdn.jsdelivr.net/gh/dongyue233/shiomi@main/card-assets/v1.33.27/media-004.webp","mochizuki_chizuru":"https://cdn.jsdelivr.net/gh/dongyue233/shiomi@main/card-assets/v1.33.27/media-005.webp","mikage_shiraha":"https://cdn.jsdelivr.net/gh/dongyue233/shiomi@main/card-assets/v1.33.27/media-006.webp"};
  const keyArtAsset = (id, char) => CHARACTER_KEY_ART[id] || char?.cover || char?.reference || '';

  const localWin = window;
  const hostWin = (() => {
    try { if (window.parent && window.parent.document) return window.parent; } catch (_) {}
    return window;
  })();
  const hostDoc = hostWin.document;

  const text = v => String(v == null ? '' : v).trim();
  const escapeHtml = value => String(value ?? '').replace(/[&<>\"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[ch]));
  const obj = v => v && typeof v === 'object' && !Array.isArray(v) ? v : {};
  const list = v => Array.isArray(v) ? v : [];
  const norm = v => text(v).toLocaleLowerCase('zh-CN')
    .replace(/[\s\u3000·・,，。.!！?？:：;；'"“”‘’()（）\[\]【】<>《》〈〉—_\-/\\]+/g,'');


  function cardScope() {
    try {
      const ctx = hostWin.SillyTavern?.getContext?.() || localWin.SillyTavern?.getContext?.() || {};
      const raw = [ctx.characterId, ctx.character_id, ctx.this_chid, ctx.name, ctx.characterName, ctx.chatId, ctx.chat_id]
        .map(text).filter(Boolean).join('|');
      return raw ? raw.toLocaleLowerCase('zh-CN').replace(/[^\w\u4e00-\u9fff|.-]+/g,'_') : 'unknown-card';
    } catch (_) { return 'unknown-card'; }
  }
  const storageKey = () => `${BASE_KEY}:${cardScope()}`;

  async function worldbookNames() {
    const names = [];
    const add = value => {
      if (Array.isArray(value)) return value.forEach(add);
      const name = text(value);
      if (name && !names.some(x => x.toLowerCase() === name.toLowerCase())) names.push(name);
    };
    try {
      if (typeof getCharWorldbookNames === 'function') {
        const bound = getCharWorldbookNames('current');
        add(bound?.primary); add(bound?.additional);
      }
    } catch (_) {}
    try { if (typeof getChatWorldbookName === 'function') add(getChatWorldbookName('current')); } catch (_) {}
    try { if (typeof getWorldbookNames === 'function') add(await getWorldbookNames()); } catch (_) {}
    try {
      const context = hostWin.SillyTavern?.getContext?.() || localWin.SillyTavern?.getContext?.();
      if (typeof context?.getWorldInfoNames === 'function') add(await context.getWorldInfoNames());
    } catch (_) {}
    return names;
  }

  async function worldbookEntries(name) {
    let rows = [];
    try { if (typeof getWorldbook === 'function') rows = await getWorldbook(name); } catch (_) {}
    if (!Array.isArray(rows) || !rows.length) {
      try {
        const context = hostWin.SillyTavern?.getContext?.() || localWin.SillyTavern?.getContext?.();
        if (typeof context?.loadWorldInfo === 'function') {
          const raw = await context.loadWorldInfo(name);
          if (Array.isArray(raw)) rows = raw;
          else if (Array.isArray(raw?.entries)) rows = raw.entries;
          else if (raw?.entries && typeof raw.entries === 'object') rows = Object.values(raw.entries);
        }
      } catch (_) {}
    }
    return Array.isArray(rows) ? rows : [];
  }

  const entryTitle = entry => text(entry?.name || entry?.comment || entry?.title || entry?.uid || entry?.id);

  function stripJsonWrapper(source) {
    let value = text(source).replace(/^\uFEFF/, '');
    const fenced = value.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
    if (fenced) value = fenced[1].trim();
    const tagged = value.match(/^<json>\s*([\s\S]*?)\s*<\/json>$/i);
    if (tagged) value = tagged[1].trim();
    return value;
  }

  function absoluteUrl(value, base) {
    const raw = text(value);
    if (!raw) return '';
    if (/^(?:data:|blob:|https?:\/\/)/i.test(raw)) return raw;
    try { return new URL(raw, base).href; }
    catch (_) { return raw; }
  }

  function unique(values) {
    const out = [];
    for (const value of values) {
      const row = text(value);
      if (row && !out.includes(row)) out.push(row);
    }
    return out;
  }

  async function fetchJson(url, timeoutMs = 6500) {
    if (!url) throw new Error('empty url');
    const controller = typeof AbortController === 'function' ? new AbortController() : null;
    const timer = controller ? hostWin.setTimeout(() => controller.abort(), timeoutMs) : 0;
    try {
      const response = await fetch(url, {cache:'no-store', mode:'cors', signal:controller?.signal});
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      return await response.json();
    } finally {
      if (timer) hostWin.clearTimeout(timer);
    }
  }

  function makeAsset(relativePath, manifestUrls, objectPosition = '') {
    const urls = unique(list(manifestUrls).map(url => absoluteUrl(relativePath, url)).filter(Boolean));
    return {url:urls[0] || '', fallbacks:urls.slice(1), objectPosition:text(objectPosition)};
  }

  function normalizeCharacterManifest(id, globalRow, rawManifest, manifestUrls, fallbackMeta) {
    const cm = obj(rawManifest);
    const labels = obj(cm.category_labels);
    const order = obj(cm.category_order);
    const rows = list(cm.images);
    const referenceRow = rows.find(row => norm(row?.rating) === 'reference') || null;
    const defaultCondition = cgId => ({all_tags:[cgId]});
    const gallery = rows.filter(row => row?.id && ['sfw','nsfw'].includes(norm(row?.rating))).map(row => {
      const rating = norm(row.rating) === 'nsfw' ? 'nsfw' : 'sfw';
      const category = text(row.category || 'other') || 'other';
      const legacyCondition = Object.keys(obj(row.condition)).length ? obj(row.condition) : defaultCondition(text(row.id));
      const unlock = Object.keys(obj(row.unlock)).length ? obj(row.unlock) : legacyCondition;
      return {
        id:text(row.id),
        titleZh:text(row.title || row.category_label || labels[category] || row.id),
        rating,
        category,
        categoryLabel:text(row.category_label || labels[category] || category),
        asset:makeAsset(row.original, manifestUrls),
        thumb:makeAsset(row.thumb || row.original, manifestUrls),
        condition:legacyCondition,
        unlock,
        unlockMode:text(row.unlockMode || row.unlock_mode || 'manual_tag'),
        priority:Number(row.priority || 0),
        sourceGroup:text(row.sourceGroup || row.source_group || ''),
        sceneGroup:text(row.sceneGroup || row.scene_group || ''),
        tags:list(row.tags)
      };
    });
    const coverRel = text(cm.cover || '');
    const cover = coverRel ? makeAsset(coverRel, manifestUrls, fallbackMeta?.cover?.objectPosition) : fallbackMeta?.cover;
    const reference = referenceRow?.original ? makeAsset(referenceRow.original, manifestUrls, fallbackMeta?.reference?.objectPosition) : fallbackMeta?.reference;
    return {
      ...obj(fallbackMeta),
      id,
      nameZh:text(cm.character_name || globalRow?.name || fallbackMeta?.nameZh || id),
      aliases:list(fallbackMeta?.aliases),
      cover:cover || fallbackMeta?.cover || reference,
      reference:reference || fallbackMeta?.reference || cover,
      gallery,
      categoryOrder:order,
      categoryLabels:labels,
      manifestVersion:text(cm.schema_version || cm.version || ''),
      manifestUrl:text(manifestUrls?.[0] || '')
    };
  }

  async function loadRegistry() {
    const names = await worldbookNames();
    let embedded = null;
    for (const name of names) {
      const rows = await worldbookEntries(name);
      const entry = rows.find(row => entryTitle(row) === ENTRY_TITLE);
      if (!entry) continue;
      embedded = JSON.parse(stripJsonWrapper(entry.content));
      break;
    }
    if (!embedded) throw new Error(`未找到关闭状态世界书条目「${ENTRY_TITLE}」。`);
    if (embedded.schema !== 'shiomi_character_cg_loader_v2') throw new Error('角色CG注册表 schema 不正确。');

    const remotes = unique([text(embedded.remoteManifest), ...list(embedded.remoteManifestFallbacks).map(text)]);
    const registry = {
      schema:'shiomi_character_cg_runtime_v2',
      version:text(embedded.version || '0.4.0'),
      characters:JSON.parse(JSON.stringify(obj(embedded.characters)))
    };

    let globalManifest = null;
    let loadedGlobalUrl = '';
    for (const url of remotes) {
      try {
        const remote = await fetchJson(url);
        if (String(remote?.schema_version || '') === '2.0' && Array.isArray(remote?.characters)) {
          globalManifest = remote;
          loadedGlobalUrl = url;
          console.info(LOG, '已载入 CG Manifest v2 总索引。', url);
          break;
        }
      } catch (error) {
        console.warn(LOG, 'CG Manifest v2 总索引读取失败。', url, error);
      }
    }
    if (!globalManifest) return registry;

    const globalBases = unique([loadedGlobalUrl, ...remotes]);
    for (const row of list(globalManifest.characters)) {
      const id = text(row?.id);
      if (!id) continue;
      const fallbackMeta = obj(registry.characters[id]);
      const relManifest = text(row?.manifest || `${id}/manifest.json`);
      const candidates = unique(globalBases.map(base => absoluteUrl(relManifest, base)));
      let cm = null;
      let loadedManifestUrl = '';
      for (const url of candidates) {
        try {
          const fetched = await fetchJson(url);
          if (String(fetched?.schema_version || '') === '2.0' && text(fetched?.character_id || id) === id) {
            cm = fetched;
            loadedManifestUrl = url;
            break;
          }
        } catch (error) {
          console.warn(LOG, '角色 CG manifest 读取失败。', id, url, error);
        }
      }
      if (!cm) continue;
      const orderedUrls = unique([loadedManifestUrl, ...candidates]);
      registry.characters[id] = normalizeCharacterManifest(id, row, cm, orderedUrls, fallbackMeta);
    }
    return registry;
  }

  function defaultState() {
    return {
      version: 2,
      scope: cardScope(),
      unlocked: {},
      unlockedAt: {},
      unread: {},
      current: null,
      lastScene: null
    };
  }

  function normalizeState(saved) {
    const base = defaultState();
    if (!saved || typeof saved !== 'object') return base;
    return {
      ...base,
      ...saved,
      scope: cardScope(),
      unlocked: obj(saved.unlocked),
      unlockedAt: obj(saved.unlockedAt),
      unread: obj(saved.unread),
      current: saved.current && typeof saved.current === 'object' ? saved.current : null,
      lastScene: saved.lastScene && typeof saved.lastScene === 'object' ? saved.lastScene : null
    };
  }

  function loadState() {
    try {
      if (typeof getVariables === 'function') {
        const vars = getVariables({type:'chat'}) || {};
        return normalizeState(vars[storageKey()]);
      }
    } catch (error) { console.warn(LOG, '读取聊天相册变量失败。', error); }
    return defaultState();
  }

  function saveState(state) {
    try {
      if (typeof insertOrAssignVariables === 'function') {
        state.scope = cardScope();
        insertOrAssignVariables({[storageKey()]: state}, {type:'chat'});
        return true;
      }
    } catch (error) { console.warn(LOG, '写入聊天相册变量失败。', error); }
    return false;
  }

  function unreadCount(state) {
    let count = 0;
    for (const ids of Object.values(obj(state?.unread))) count += new Set(list(ids)).size;
    return count;
  }

  function unreadFor(state, characterId) {
    return new Set(list(obj(state?.unread)[characterId]));
  }

  function tagSet(scene) {
    return new Set(list(scene?.scene_tags).map(norm).filter(Boolean));
  }

  function includesName(char, value) {
    const q = norm(value);
    if (!q) return false;
    return [char?.nameZh, char?.nameJa, ...list(char?.aliases)].some(name => norm(name) === q);
  }

  function characterPresent(char, scene) {
    return list(scene?.present_characters).some(name => includesName(char,name));
  }

  function resolveFocus(registry, scene) {
    const characters = obj(registry?.characters);
    const explicit = text(scene?.focus_character);
    if (explicit) {
      for (const [id, char] of Object.entries(characters)) {
        if (includesName(char, explicit) && characterPresent(char,scene)) return {id, char};
      }
      return null;
    }
    const present = list(scene?.present_characters).map(text).filter(Boolean);
    const hits = [];
    for (const [id, char] of Object.entries(characters)) {
      if (present.some(name => includesName(char, name))) hits.push({id,char});
    }
    return hits.length === 1 ? hits[0] : null;
  }

  function unlockRule(item) {
    const rule = obj(item?.unlock);
    return Object.keys(rule).length ? rule : obj(item?.condition);
  }

  function locationMatches(rule, scene) {
    const raw = rule?.locations ?? rule?.location;
    const wanted = Array.isArray(raw) ? raw.map(norm).filter(Boolean) : (text(raw) ? [norm(raw)] : []);
    if (!wanted.length) return true;
    const actual = norm(scene?.location);
    if (!actual) return false;
    return wanted.some(loc => actual === loc || actual.includes(loc) || loc.includes(actual));
  }

  function strictMatchScore(char, item, scene) {
    if (!characterPresent(char,scene)) return null;
    const rule = unlockRule(item);
    const expectedId = text(rule.character_id);
    if (expectedId && expectedId !== text(char.id)) return null;
    const required = text(rule.required_present_character || rule.required_character);
    if (required && !list(scene?.present_characters).some(name => norm(name) === norm(required))) return null;
    if (!locationMatches(rule,scene)) return null;
    const tags = tagSet(scene);
    const allTags = list(rule.all_tags).map(norm).filter(Boolean);
    const anyTags = list(rule.any_tags).map(norm).filter(Boolean);
    const noneTags = list(rule.none_tags).map(norm).filter(Boolean);
    if (!allTags.length) return null;
    if (allTags.some(tag => !tags.has(tag))) return null;
    if (anyTags.length && !anyTags.some(tag => tags.has(tag))) return null;
    if (noneTags.some(tag => tags.has(tag))) return null;
    let score = Number(item?.priority || 0) + allTags.length * 2;
    if (required) score += 3;
    if (expectedId) score += 3;
    if (anyTags.some(tag => tags.has(tag))) score += 1;
    return score;
  }

  function matchesForScene(char, scene) {
    const hits = [];
    for (const item of list(char?.gallery)) {
      if (!item?.id) continue;
      const score = strictMatchScore(char,item,scene);
      if (score == null) continue;
      hits.push({item,score});
    }
    hits.sort((a,b) => b.score - a.score || String(a.item.id).localeCompare(String(b.item.id)));
    if (!hits.length) return [];
    const group = text(hits[0].item.sceneGroup || hits[0].item.scene_group);
    return group ? hits.filter(hit => text(hit.item.sceneGroup || hit.item.scene_group) === group).map(hit => hit.item)
                 : hits.map(hit => hit.item);
  }

  function resolveAsset(asset) {
    if (!asset) return {url:'', fallbacks:[], objectPosition:''};
    if (typeof asset === 'string') return {url:text(asset), fallbacks:[], objectPosition:''};
    return {
      url:text(asset.url),
      fallbacks:list(asset.fallbacks).map(text).filter(Boolean),
      objectPosition:text(asset.objectPosition)
    };
  }

  function loadImageWithFallback(img, asset, spinner, errorNode, onDone) {
    const {url, fallbacks, objectPosition} = resolveAsset(asset);
    const queue = [url, ...fallbacks].filter(Boolean);
    let index = 0;
    img.classList.remove('ready');
    img.removeAttribute('src');
    if (objectPosition) img.style.objectPosition = objectPosition;
    if (spinner) spinner.hidden = false;
    if (errorNode) errorNode.hidden = true;
    const tryNext = () => {
      if (index >= queue.length) {
        if (spinner) spinner.hidden = true;
        if (errorNode) errorNode.hidden = false;
        onDone?.(false);
        return;
      }
      const next = queue[index++];
      img.onload = () => {
        img.classList.add('ready');
        if (spinner) spinner.hidden = true;
        if (errorNode) errorNode.hidden = true;
        onDone?.(true);
      };
      img.onerror = tryNext;
      img.src = next;
    };
