</style>
        <div class="sa-root">
          <button class="sa-launch" type="button" aria-label="打开汐见相册" aria-hidden="true" tabindex="-1" style="display:none!important">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="4" y="5" width="16" height="14" rx="2"/><path d="m7 15 3-3 2 2 2-2 3 3"/><circle cx="15.5" cy="9" r="1.4"/></svg><span>相册</span><span class="sa-launch-new" hidden></span>
          </button>
          <section class="sa-shell" aria-hidden="true"><div class="sa-panel"><header class="sa-head"><div class="sa-title">汐见相册<small>ALBUM</small></div><button class="sa-close" type="button" aria-label="关闭">×</button></header><main class="sa-body"></main></div></section>
          <div class="sa-viewer" aria-hidden="true"><button class="sa-viewer-close" type="button" aria-label="关闭 CG">×</button><button class="sa-viewer-nav sa-viewer-prev" type="button" aria-label="上一张">‹</button><div class="sa-viewer-frame"><img alt=""><div class="sa-spinner"></div><div class="sa-error" hidden>图片暂时无法载入</div></div><button class="sa-viewer-nav sa-viewer-next" type="button" aria-label="下一张">‹</button><div class="sa-viewer-info"><strong></strong><span></span></div></div>
        </div>`;
      (hostDoc.body || hostDoc.documentElement).appendChild(this.host);
      this.launch = this.root.querySelector('.sa-launch');
      this.modal = this.root.querySelector('.sa-shell');
      this.body = this.root.querySelector('.sa-body');
      this.launch.addEventListener('click', () => this.open());
      this.root.querySelector('.sa-close').addEventListener('click', () => this.close());
      this.modal.addEventListener('pointerdown', event => { if (event.target === this.modal) this.close(); });
      const viewer = this.root.querySelector('.sa-viewer');
      viewer.querySelector('.sa-viewer-close').addEventListener('click', () => this.closeViewer());
      viewer.querySelector('.sa-viewer-prev').addEventListener('click', event => { event.stopPropagation(); this.stepViewer(-1); });
      viewer.querySelector('.sa-viewer-next').addEventListener('click', event => { event.stopPropagation(); this.stepViewer(1); });
      viewer.addEventListener('pointerdown', event => { if (event.target === viewer) this.closeViewer(); });
