      viewerFrame.addEventListener('touchstart', event => { this.viewerTouchX = event.touches?.[0]?.clientX ?? null; }, {passive:true});
      viewerFrame.addEventListener('touchend', event => {
        const endX = event.changedTouches?.[0]?.clientX;
        if (this.viewerTouchX == null || endX == null) return;
        const dx = endX - this.viewerTouchX; this.viewerTouchX = null;
        if (Math.abs(dx) > 44) this.stepViewer(dx < 0 ? 1 : -1);
      }, {passive:true});
      this.updateNotice();
      this.renderHome();
