    makeImage(asset, className, fallbackText = '', lazy = false) {
      const wrap = hostDoc.createElement('div');
      if (className) wrap.className = className;
      let fallback = null;
      if (fallbackText) {
        fallback = hostDoc.createElement('div');
        fallback.className = 'sa-cover-fallback';
        fallback.textContent = fallbackText;
        wrap.appendChild(fallback);
      }
      const img = hostDoc.createElement('img'); img.decoding = 'async'; img.loading = 'lazy';
      const spinner = hostDoc.createElement('div'); spinner.className = 'sa-spinner'; spinner.hidden = !!lazy;
      const error = hostDoc.createElement('div'); error.className = 'sa-error'; error.hidden = true; error.textContent = '图片暂时无法载入';
      wrap.append(img,spinner,error);
      let started = false;
      const startLoad = () => {
        if (started) return;
        started = true;
        loadImageWithFallback(img,asset,spinner,error,ok => {
          if (fallback) fallback.hidden = !!ok;
          if (!ok && fallbackText) {
            error.hidden = true;
            spinner.hidden = true;
            fallback.hidden = false;
          }
        });
      };
      if (lazy && typeof hostWin.IntersectionObserver === 'function') {
        const io = new hostWin.IntersectionObserver(entries => {
          if (entries.some(entry => entry.isIntersecting || entry.intersectionRatio > 0)) {
            try { io.disconnect(); } catch (_) {}
            startLoad();
          }
        }, {rootMargin:'180px 0px'});
        io.observe(wrap);
      } else {
        startLoad();
      }
      return {wrap,img,spinner,error,startLoad};
    }

    characterById(id) { return obj(this.registry.characters?.[id]); }
    galleryItem(characterId, cgId) { return list(this.characterById(characterId)?.gallery).find(item => item?.id === cgId) || null; }

    currentItems() {
      const current = obj(this.state.current);
      const cid = text(current.characterId);
      if (!cid) return [];
      const unlocked = new Set(list(this.state.unlocked[cid]));
      return list(current.cgIds).map(id => this.galleryItem(cid,id)).filter(item => item && unlocked.has(item.id));
    }

    renderHero() {
      const items = this.currentItems();
      if (!items.length) return null;
      this.heroIndex = Math.min(this.heroIndex, items.length - 1);
      const section = hostDoc.createElement('section'); section.className = 'sa-hero';
      const media = hostDoc.createElement('div'); media.className = 'sa-hero-media';
      const img = hostDoc.createElement('img'); img.decoding = 'async';
      const spin = hostDoc.createElement('div'); spin.className = 'sa-spinner';
      const err = hostDoc.createElement('div'); err.className = 'sa-error'; err.hidden = true; err.textContent = '图片暂时无法载入';
      media.append(img,spin,err); section.appendChild(media);
      let dots = null;
      if (items.length > 1) {
        dots = hostDoc.createElement('div'); dots.className = 'sa-hero-dots';
        items.forEach((_,index) => {
          const dot = hostDoc.createElement('button'); dot.type = 'button'; dot.className = 'sa-dot'; dot.setAttribute('aria-label',`查看第 ${index+1} 张`);
          dot.addEventListener('click',() => show(index)); dots.appendChild(dot);
        });
        section.appendChild(dots);
      }
      const show = index => {
        this.heroIndex = ((index % items.length) + items.length) % items.length;
        const token = ++this.heroToken;
        dots && [...dots.children].forEach((dot,i)=>dot.classList.toggle('active',i===this.heroIndex));
        loadImageWithFallback(img,items[this.heroIndex].asset,spin,err,()=>{ if (token !== this.heroToken) return; });
      };
      let startX = null;
      media.addEventListener('touchstart',e=>{startX=e.touches?.[0]?.clientX ?? null;},{passive:true});
      media.addEventListener('touchend',e=>{const end=e.changedTouches?.[0]?.clientX;if(startX==null||end==null)return;const dx=end-startX;startX=null;if(items.length>1&&Math.abs(dx)>38)show(this.heroIndex+(dx<0?1:-1));},{passive:true});
      show(this.heroIndex);
      return section;
    }

    renderHome() {
      if (!this.body) return;
      this.state = loadState();
      this.body.replaceChildren();
      const entries = CHARACTER_ORDER.map(id => [id,this.characterById(id)]).filter(([,char]) => char && Object.keys(char).length);
      if (!entries.length) return;
      if (!entries.some(([id]) => id === this.homeCharacterId)) this.homeCharacterId = entries.find(([id]) => unreadFor(this.state,id).size)?.[0] || entries[0][0];

      const stage = hostDoc.createElement('section'); stage.className = 'sa-character-stage';
      const copy = hostDoc.createElement('div'); copy.className = 'sa-stage-copy';
