        const media = this.makeImage(keyArtAsset(id,char),'sa-cover',char.nameZh || id,true);
        const name = hostDoc.createElement('div'); name.className = 'sa-name';
        name.innerHTML = `${escapeHtml(char.nameZh || id)}<small>${escapeHtml(CHARACTER_ROMAJI[id] || id.toUpperCase())}</small>`;
        const unread = unreadFor(this.state,id).size;
        if (unread) { const dot=hostDoc.createElement('span');dot.className='sa-char-new';dot.title=`${unread} 张新 CG`;button.appendChild(dot); }
        button.append(media.wrap,name);
        button.addEventListener('click',()=>{
          if (this.homeCharacterId === id && button.classList.contains('selected')) this.renderCharacter(id);
          else { this.homeCharacterId=id; updateStage(id); }
        });
        buttons.set(id,button); grid.appendChild(button);
      }
      this.body.appendChild(grid);
      const hero = this.renderHero(); if (hero) this.body.appendChild(hero);

      const updateStage = id => {
        const char = this.characterById(id); if (!char) return;
        this.homeCharacterId = id;
        for (const [cid,button] of buttons) button.classList.toggle('selected',cid===id);
        const index = Math.max(0,entries.findIndex(([cid])=>cid===id)) + 1;
