    const manager = obj(vars[MANAGER_KEY]);
    const current = obj(vars[CURRENT_KEY]);
    if (text(manager.active_case) !== cid || text(current.case_id) !== cid) throw new Error('案件当前没有处于调查状态');
    if (nextAction(vars, cid)) throw new Error('上一项调查行动仍在处理中');
    const requested = normalizeRequestedAction(action);
    const view = await interactionView(cid);
    if (!view) throw new Error('当前案件交互视图不可用');
    if (requested.type === 'submit_conclusion') {
      const payload = obj(requested.payload);
      const suspect = limitText(payload.suspect, 80);
      const summary = limitText(payload.summary, 1600);
      if (!suspect) throw new Error('请填写指认对象');
      if (!summary) throw new Error('请填写当前结论摘要');
      const allowedEvidence = new Set(view.conclusion.selectableEvidence.map(row => `${row.kind}:${row.id}`));
      const evidence = arr(payload.evidence).map(row => ({kind:text(row?.kind),id:text(row?.id)})).filter(row => allowedEvidence.has(`${row.kind}:${row.id}`)).slice(0,32);
      return { type:'submit_conclusion', target:{}, payload:{ suspect, summary, evidence, method:limitText(payload.method,800), motive:limitText(payload.motive,800), chain:limitText(payload.chain,1200) } };
    }
    const allowed = arr(view.__allowedActions);
    const key = actionKey(requested);
    const match = allowed.find(candidate => actionKey(candidate) === key);
    if (!match) throw new Error('该调查动作当前不可用，案件状态可能已经变化');
