    if (record.target.clue_id) record.clue_id = record.target.clue_id;
    await updateVariablesWith(all => { all = obj(all); all[ACTION_KEY] = record; return all; }, { type:'chat' });
    await syncCaseWorldbookState();
    try { eventEmit('shiomi:authored-case:updated'); } catch (_) {}
